INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 1, 'Which of the following BEST describes ''real estate''?',
   'Land only, from surface to center of the earth', 'Land plus permanently attached improvements', 'Land plus all personal property located on it', 'Any property owned by a person, movable or not',
   'B', '''Bienes raíces'' (real estate) se define como la tierra MÁS todas las mejoras permanentemente adjuntas, como edificios, cercas y estructuras. La tierra sola es solo la superficie. Los bienes raíces (real property) añaden además el conjunto de derechos legales.', Unidad 1, pág. ~3);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 3, 'Which of the following is MOST likely to be considered a fixture?',
   'A portable window air conditioning unit', 'A refrigerator connected only by a power cord', 'Built-in kitchen cabinets bolted to the wall', 'A free-standing bookcase',
   'C', 'Los gabinetes de cocina empotrados son un accesorio (fixture) porque están permanentemente adjuntos por el método de anexión. Para determinar si algo es fixture se usan 3 pruebas: (1) método de anexión, (2) adaptación al inmueble, (3) acuerdo de las partes. Un refrigerador conectado solo por cable sigue siendo propiedad personal.', Unidad 1, pág. ~6);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 4, 'Fructus industriales are BEST described as:',
   'Trees and perennial plants that grow naturally', 'Annual crops produced by the labor of a tenant farmer', 'Wild fruits and berries growing on the land', 'Permanent natural vegetation attached to the soil',
   'B', 'Fructus industriales (también llamados ''emblemas'') son cultivos anuales producidos por el trabajo humano, como maíz o trigo. Se consideran PROPIEDAD PERSONAL. Un arrendatario puede llevárselos al terminar el contrato. Fructus naturales (árboles perennes) son propiedad inmueble.', Unidad 1, pág. ~9);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 5, 'When personal property is permanently attached to real estate and becomes part of it, this process is called:',
   'Severance', 'Hypothecation', 'Annexation', 'Accession',
   'C', '''Anexión'' (annexation) es el proceso por el cual la propiedad personal se convierte en propiedad inmueble al ser adherida permanentemente. Lo contrario es ''separación'' (severance): cuando se retira algo del inmueble y se convierte en propiedad personal.', Unidad 1, pág. ~7);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 6, 'A seller conveys surface rights to a buyer but retains the mineral rights below the surface. The buyer receives:',
   'Fee simple absolute', 'A life estate', 'An interest lesser than fee simple absolute', 'A leasehold estate',
   'C', 'Cuando los derechos minerales han sido separados (''severed'') del título de superficie, el comprador NO recibe el fee simple absolute completo. Recibe un interés menor porque los derechos minerales pertenecen a otra persona. El fee simple absolute incluye TODOS los derechos de la propiedad.', Unidad 1, pág. ~5);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 7, 'Trade fixtures installed by a business tenant must be removed:',
   'Within 30 days after the lease ends', 'No later than the last day of the lease term', 'Anytime within 1 year of installation', 'Only with written permission from the landlord',
   'B', 'Los accesorios comerciales (trade fixtures) son instalados por el arrendatario para uso en su negocio y se consideran PROPIEDAD PERSONAL. DEBEN retirarse antes del ÚLTIMO DÍA del contrato de arrendamiento. Si no los retira, se convierten en propiedad del arrendador por ''accesión''.', Unidad 1, pág. ~8);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 8, 'Under Pennsylvania law, a manufactured home becomes real property when:',
   'It is placed on a permanent lot for more than one year', 'It is connected to all utilities', 'It is permanently attached to a foundation AND its title registration is canceled with the PA Bureau of Motor Vehicles', 'The owner files a declaration with the county recorder of deeds',
   'C', 'En Pennsylvania, una casa prefabricada se convierte en bien raíz SOLO cuando se cumplen DOS condiciones simultáneamente: (1) está permanentemente adjunta a un cimiento, Y (2) su registro de título es cancelado ante la Oficina de Vehículos de Motor de PA. Ambas condiciones son necesarias.', Unidad 1, pág. ~10);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 9, 'The ''bundle of legal rights'' associated with real property ownership includes all of the following EXCEPT the right of:',
   'Possession', 'Control', 'Unlimited and unrestricted use', 'Exclusion',
   'C', 'El ''haz de derechos'' (bundle of rights) incluye: posesión, control, goce/disfrute, exclusión y disposición. El uso NO es ilimitado; está restringido por leyes de zonificación, servidumbres, CC&Rs y otras regulaciones. Por eso la opción C es incorrecta: nadie tiene derecho de uso ''ilimitado''.', Unidad 1, pág. ~4);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 10, 'Which of the following is a PHYSICAL characteristic of land?',
   'Scarcity', 'Immobility', 'Permanence of investment', 'Location (situs)',
   'B', 'Las características FÍSICAS de la tierra son: (1) Inmovilidad (no puede moverse de su ubicación geográfica), (2) Indestructibilidad (la tierra no se destruye), (3) Unicidad (no hay dos parcelas idénticas). Las características ECONÓMICAS son: escasez, mejoras, permanencia de inversión y localización.', Unidad 1, pág. ~4);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 12, 'When a tenant fails to remove trade fixtures before the lease ends, the landlord acquires those fixtures through a concept known as:',
   'Conversion', 'Severance', 'Accession', 'Adverse possession',
   'C', 'La ''accesión'' (accession) es el proceso por el cual el propietario adquiere algo que ha sido adjuntado a su propiedad. Si el arrendatario NO retira sus trade fixtures antes del último día del arrendamiento, esos artículos se convierten en propiedad del arrendador por accesión.', Unidad 1, pág. ~8);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 13, 'The right of a property owner to use the space above their land is known as:',
   'Riparian rights', 'Air rights', 'Mineral rights', 'Surface rights',
   'B', 'Los ''derechos aéreos'' (air rights) son el derecho a usar el espacio aéreo sobre la tierra hasta cierta altura razonable. La definición legal de tierra incluye: la superficie, el espacio aéreo, y la tierra hacia el centro de la Tierra. Derechos de ripario = agua; minerales = debajo del suelo.', Unidad 1, pág. ~5);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 14, 'Regarding Pennsylvania''s coal mine subsidence notice requirement, which statement is CORRECT?',
   'Sellers must purchase mine subsidence insurance before closing', 'Mine subsidence damage is covered by standard homeowner''s insurance policies', 'Sellers of real property must provide buyers with a notice about potential mine subsidence', 'Only commercial property transactions require the subsidence notice',
   'C', 'En Pennsylvania, los vendedores DEBEN proporcionar un aviso a los compradores sobre los posibles efectos de la subsidencia minera (hundimiento causado por minas de carbón). El seguro de subsidencia minera NO está incluido en las pólizas estándar de propietarios; existe el Fondo de Seguro de Subsidencia de Minas de Carbón de PA para esto.', Unidad 1, pág. ~12);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 18, 'Which of the following would be classified as real property?',
   'Annual crops planted last spring by a tenant farmer', 'A portable storage shed resting on concrete blocks', 'An in-ground swimming pool permanently installed in the backyard', 'A window-mounted air conditioning unit',
   'C', 'Una piscina enterrada (in-ground) es propiedad inmueble porque está permanentemente adjunta a la tierra mediante construcción. Los cultivos anuales de un arrendatario son propiedad personal (fructus industriales). Una caseta portátil no está permanentemente adjunta. Un AC de ventana no está empotrado.', Unidad 1, pág. ~7);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 19, 'An appurtenance in real estate is BEST described as:',
   'Personal property that can be moved from place to place', 'Rights, privileges, and improvements that belong to the land and transfer automatically with it', 'A temporary right to use someone else''s property', 'The owner''s exclusive right to sell the property',
   'B', 'Una ''apurtenancia'' (appurtenance) es cualquier derecho, privilegio o mejora que pertenece a la tierra y se transfiere automáticamente con ella cuando la propiedad se vende. Ejemplos: servidumbres, derechos de agua, derechos minerales. La frase legal es: ''runs with the land'' (corre con la tierra).', Unidad 1, pág. ~5);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (1, 20, 'Which of the following identifies the THREE legal tests used to determine if an item is a fixture?',
   'Color, size, and portability of the item', 'Method of annexation, adaptation to the real estate, and agreement of the parties', 'Who paid for the item, who uses it, and its age', 'Monetary value, permanence of installation, and zoning classification',
   'B', 'Las TRES pruebas legales para determinar si un artículo es un accesorio (fixture) son: (1) Método de anexión — ¿cómo está adjuntado?, (2) Adaptación al inmueble — ¿está diseñado especialmente para ese espacio?, (3) Acuerdo de las partes — ¿qué dice el contrato? El acuerdo escrito puede convertir un fixture en propiedad personal o viceversa.', Unidad 1, pág. ~6);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 1, 'The government''s inherent authority to enact laws that protect the public health, safety, and general welfare is known as:',
   'Eminent domain', 'Escheat', 'Police power', 'Taxation',
   'C', 'El ''poder de policía'' (police power) es la autoridad inherente del Estado para aprobar leyes que protejan la salud, seguridad y bienestar público. Es la base legal de las leyes de zonificación, códigos de construcción y regulaciones medioambientales. No requiere compensación al propietario.', Unidad 2, pág. ~31);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 2, 'A comprehensive land-use plan adopted by a municipality is BEST described as:',
   'A legally binding zoning ordinance', 'A guide for community development that is NOT itself a regulatory document', 'A law that restricts what can be built on each parcel', 'A court-ordered land-use restriction',
   'B', 'El ''plan integral'' (comprehensive plan) es una GUÍA de desarrollo comunitario, NO una ordenanza regulatoria. No tiene fuerza de ley por sí solo. Las zonificaciones y ordenanzas municipales son los instrumentos regulatorios basados en ese plan. En PA, la autoridad proviene del Pennsylvania Municipalities Planning Code.', Unidad 2, pág. ~32);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 3, 'A use of property that was legally established before the current zoning ordinance was enacted and is now permitted to continue despite not conforming to current zoning is called a:',
   'Variance', 'Nonconforming use', 'Conditional use', 'Spot zoning',
   'B', 'Un ''uso no conforme'' (nonconforming use) es un uso que existía legalmente ANTES de que se aprobara la ordenanza de zonificación actual y que puede continuar (está ''grandfathered''). Sin embargo, generalmente no puede expandirse ni reconstruirse si se destruye. Nunca se debe asumir que continuará indefinidamente.', Unidad 2, pág. ~34);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 4, 'A property owner seeks relief from a strict application of the zoning ordinance that would cause unnecessary hardship. The owner should apply for a:',
   'Nonconforming use certificate', 'Conditional use permit', 'Variance', 'Spot zoning approval',
   'C', 'Una ''varianza'' (variance) es la aprobación para desviarse de los requisitos de zonificación debido a una dificultad innecesaria (hardship) específica de esa propiedad. El propietario debe demostrar que aplicar estrictamente el código causaría hardship único. Difiere del permiso de uso condicional, que es para usos permitidos con condiciones especiales.', Unidad 2, pág. ~35);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 5, 'When the government takes private property for public use under the power of eminent domain, the owner is entitled to:',
   'Nothing, as the government has absolute authority', 'Just compensation equal to the property''s fair market value', 'Replacement property of equal size', 'A tax exemption for the remaining property',
   'B', 'La 5ª Enmienda de la Constitución exige que cuando el gobierno toma propiedad privada mediante el dominio eminente (eminent domain), el propietario tiene derecho a ''justa compensación'' (just compensation), que equivale al valor justo de mercado de la propiedad. El proceso legal se llama ''condena'' (condemnation).', Unidad 2, pág. ~37);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 6, 'State laws that authorize local governments (cities, counties, townships) to enact zoning ordinances are called:',
   'Building codes', 'Enabling acts', 'Police power statutes', 'Dedication laws',
   'B', 'Las ''enabling acts'' (leyes habilitantes) son leyes estatales que delegan el poder de policía del estado a los gobiernos locales, autorizándolos a aprobar ordenanzas de zonificación. En Pennsylvania, la ley habilitante es el Pennsylvania Municipalities Planning Code (PMPC).', Unidad 2, pág. ~31);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 9, 'Which of the following statements CORRECTLY distinguishes between a subdivider and a developer?',
   'A subdivider divides raw land into lots; a developer improves the land', 'A subdivider improves the land; a developer only divides it', 'Both terms are legally identical in Pennsylvania', 'A developer creates the plat; a subdivider constructs buildings',
   'A', 'Distinción clave: un ''subdivider'' (subdivisor) DIVIDE la tierra en parcelas o lotes. Un ''developer'' (desarrollador) MEJORA la tierra (construye calles, instala servicios, levanta edificios). Una persona puede hacer ambas cosas, pero los términos describen funciones distintas.', Unidad 2, pág. ~40);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 10, 'A plat is BEST described as:',
   'A soil absorption test required before development', 'A fee charged to developers for off-site improvements', 'A detailed map of a subdivision showing lots, streets, and dimensions', 'A government permit to begin construction',
   'C', 'Un ''plat'' es un mapa detallado de una subdivisión que muestra los límites de los lotes, calles, servidumbres, y dimensiones. Debe ser aprobado por las autoridades locales y registrado en el condado. Es la base para el sistema de descripción legal por lote y bloque.', Unidad 2, pág. ~41);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 11, 'When a private property owner voluntarily transfers land to the public for use as a street or park, this is called:',
   'Condemnation', 'Dedication', 'Escheat', 'Annexation',
   'B', 'La ''dedicación'' (dedication) es la transferencia VOLUNTARIA de tierra privada para uso público (calles, parques, áreas comunes). Puede ser expresa (por escritura) o implícita (por uso continuo). Difiere del dominio eminente (condena), que es involuntario.', Unidad 2, pág. ~41);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 12, 'A percolation test is performed to determine:',
   'Whether the soil contains hazardous contaminants', 'The depth of the water table on a parcel', 'The radon gas concentration in the soil', 'The soil''s ability to absorb water, required before installing a septic system',
   'D', 'Una ''prueba de percolación'' (percolation test / ''perc test'') mide la capacidad del suelo para absorber agua. Es REQUISITO antes de instalar un sistema séptico en propiedades sin acceso al alcantarillado municipal. Si el suelo no ''perc'', no se puede aprobar un sistema séptico.', Unidad 2, pág. ~42);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 13, 'Deed restrictions, also known as CC&Rs (Covenants, Conditions, and Restrictions), are BEST described as:',
   'Government zoning laws that control land use', 'Private controls placed in deeds to restrict property use, enforced by HOAs or neighboring owners', 'Court orders restricting construction near wetlands', 'Federal regulations governing fair housing',
   'B', 'Los CC&Rs (Covenants, Conditions & Restrictions) son controles PRIVADOS que los propietarios originales o desarrolladores incluyen en las escrituras. Restringen el uso de la propiedad (ej: no comercios, colores de fachada, tamaño de cercas). Los hace cumplir la HOA o los vecinos afectados. Si son más restrictivos que la zonificación, prevalecen los CC&Rs.', Unidad 2, pág. ~43);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 14, 'After completing a building and passing all required inspections, a property owner needs a _______ before occupying the structure.',
   'Variance', 'Conditional use permit', 'Certificate of occupancy', 'Plat approval',
   'C', 'Un ''certificado de ocupación'' (certificate of occupancy / C of O) es emitido por la autoridad local de construcción DESPUÉS de que el edificio pasa todas las inspecciones requeridas y cumple con los códigos de construcción. Sin él, el edificio no puede ser ocupado legalmente.', Unidad 2, pág. ~38);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 17, 'Fees charged to real estate developers to offset the cost of public infrastructure improvements (roads, schools, utilities) needed due to new development are called:',
   'Transfer taxes', 'Impact fees', 'Special assessments', 'Permit fees',
   'B', 'Las ''tarifas de impacto'' (impact fees) son cargos que los municipios imponen a los desarrolladores para cubrir los costos de mejoras de infraestructura fuera del sitio (escuelas, carreteras, parques) que se necesitan como resultado del nuevo desarrollo. Son diferentes a los impuestos especiales, que se cobran a propietarios existentes.', Unidad 2, pág. ~42);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (2, 20, 'A use permitted in a zoning district only when specific conditions are met and approval is granted by the zoning board is called a:',
   'Nonconforming use', 'Conditional use', 'Variance', 'Spot zoning',
   'B', 'Un ''uso condicional'' (conditional use) es un uso que la ordenanza de zonificación PERMITE en ese distrito, pero solo bajo condiciones específicas y con aprobación de la junta de zonificación. Por ejemplo, una guardería en un vecindario residencial. Difiere de la varianza, que es una excepción por hardship.', Unidad 2, pág. ~35);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 4, 'Under the Lead-Based Paint Hazard Reduction Act (LBPHRA) of 1992, which of the following statements is CORRECT?',
   'The law applies to all homes regardless of when they were built', 'Sellers must remove all lead paint before selling', 'Buyers must be given a 10-day opportunity to test for lead paint in homes built before 1978', 'Lead paint disclosure is only required if children under 6 will live in the home',
   'C', 'La LBPHRA de 1992 exige que en la venta de viviendas construidas ANTES de 1978: (1) el vendedor divulgue lo que sabe sobre pintura de plomo, (2) el comprador reciba el folleto del EPA, (3) el comprador tenga 10 días para inspeccionar. Los efectos del plomo en niños menores de 6 años son IRREVERSIBLES.', Unidad 3, pág. ~63);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 5, 'The EPA''s recommended action level for radon gas in a home is:',
   '1.0 picocuries per liter (pCi/L)', '4.0 picocuries per liter (pCi/L)', '10.0 picocuries per liter (pCi/L)', '0.4 picocuries per liter (pCi/L)',
   'B', 'El nivel de acción del EPA para el radón es 4 pCi/L (picocuries por litro). Por encima de este nivel, se recomienda tomar medidas correctivas. El nivel promedio en exteriores es 0.4 pCi/L. El radón es un gas radiactivo, incoloro e inodoro que proviene de la descomposición natural del uranio en el suelo.', Unidad 3, pág. ~65);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 7, 'Carbon monoxide is BEST described as:',
   'A visible brown gas produced by vehicle exhaust', 'A colorless, odorless gas produced by incomplete combustion of fossil fuels', 'A radioactive gas that seeps from the ground', 'A chemical found in old electrical equipment manufactured before 1979',
   'B', 'El monóxido de carbono (CO) es un gas INCOLORO e INODORO producido por la combustión incompleta de combustibles fósiles. La fuente más común en el hogar es un horno (furnace) que funciona mal. Es llamado el ''asesino silencioso'' porque no puede detectarse sin un detector. Puede ser fatal.', Unidad 3, pág. ~67);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 9, 'Mold growth in a property requires all of the following EXCEPT:',
   'Moisture or water', 'Oxygen', 'An organic food source (wood, drywall, etc.)', 'Sunlight',
   'D', 'El moho necesita TRES condiciones para crecer: (1) humedad o agua, (2) oxígeno, (3) una fuente de alimento orgánico (madera, cartón yeso, papel). El moho NO necesita luz solar; de hecho, puede crecer en lugares oscuros y húmedos como sótanos, áticos y paredes interiores.', Unidad 3, pág. ~68);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 10, 'Asbestos poses a health hazard primarily when it is:',
   'Buried underground near the foundation', 'In an ''intact and undisturbed'' condition (friable)', 'Disturbed and fibers are released into the air', 'Painted over with latex paint',
   'C', 'El asbesto (asbestos) es peligroso cuando se DISTURBA y sus fibras microscópicas son liberadas al aire y pueden ser inhaladas. Si está intacto y en buen estado, puede ser mejor dejarlo en su lugar (encapsulación). Fue ampliamente usado en aislamiento antes de 1978. Causa cáncer (mesotelioma) y enfermedades pulmonares.', Unidad 3, pág. ~66);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 11, 'Chlorofluorocarbons (CFCs) used in refrigeration and air conditioning systems:',
   'Are still manufactured today with strict EPA controls', 'Were banned from new manufacturing since 1996 and may only be handled by EPA-certified technicians', 'Are harmless to the environment and may be vented freely', 'Must be removed from all buildings built before 2000',
   'B', 'Los CFCs (clorofluorocarbonos) dañan la capa de ozono. Desde 1996, ya NO se fabrican en EE.UU. Solo técnicos CERTIFICADOS por el EPA pueden manejar, reciclar o desechar los refrigerantes que los contienen. Esto se aplica a equipos de aire acondicionado y refrigeración que contienen estos gases.', Unidad 3, pág. ~68);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 14, 'CERCLA (the Superfund law) holds parties responsible for hazardous waste cleanup under a liability standard that is:',
   'Based only on fault or negligence', 'Limited to the current property owner', 'Strict, joint, several, and retroactive', 'Limited to a maximum of $1 million per site',
   'C', 'CERCLA (1980) establece responsabilidad ESTRICTA (sin importar negligencia), CONJUNTA (cualquier parte responsable puede ser demandada por el total), SOLIDARIA (todos los responsables son igualmente obligados) y RETROACTIVA (aplica a contaminaciones pasadas). El Superfund inicial fue de $1.6 billones. SARA (1986) lo aumentó a $8.5 billones.', Unidad 3, pág. ~72);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 15, 'The Superfund Amendments and Reauthorization Act (SARA) of 1986 added which important protection for innocent purchasers?',
   'It exempted all residential buyers from Superfund liability', 'It provided innocent landowner immunity to buyers who conducted a Phase I environmental assessment', 'It limited liability to the previous owner only', 'It created a federal fund to pay cleanup costs for all buyers',
   'B', 'SARA (1986) introdujo la ''protección de propietario inocente'' (innocent landowner immunity): si un comprador realizó una Evaluación Ambiental Fase I (Phase I) antes de comprar y no encontró problemas, puede estar protegido de responsabilidad por contaminación preexistente. La Fase I incluye revisión de registros, inspección visual y entrevistas.', Unidad 3, pág. ~72);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (3, 19, 'Under Pennsylvania law, which sellers are required to disclose known material facts about their property?',
   'Only sellers of commercial properties over $500,000', 'Sellers of residential properties with 1 to 4 units', 'All property sellers including commercial and industrial', 'Only sellers who have owned the property for more than 5 years',
   'B', 'La Ley de Divulgación de Pennsylvania requiere que los vendedores de propiedades RESIDENCIALES de 1 a 4 unidades divulguen los hechos materiales conocidos sobre la propiedad. Las propiedades comerciales e industriales están EXCLUIDAS de este requisito. La divulgación continúa siendo válida hasta el cierre.', Unidad 3, pág. ~62);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 1, 'Which of the following are the THREE recognized methods of legal description used in the United States?',
   'Survey, deed, and tax map', 'Metes-and-bounds, lot-and-block (recorded plat), and rectangular survey (government survey)', 'Lot number, parcel ID, and street address', 'Deed of trust, abstract, and title commitment',
   'B', 'Los tres métodos de descripción legal son: (1) Metes-and-bounds (direcciones y distancias con monumentos), (2) Lot-and-block / Recorded Plat (número de lote, bloque y plano registrado), y (3) Rectangular Survey / Government Survey (meridianos, townships y secciones). Pennsylvania NO usa el sistema rectangular.', Unidad 4, pág. ~91);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 2, 'Pennsylvania uses which of the following legal description methods?',
   'Metes-and-bounds and lot-and-block ONLY (not rectangular survey)', 'Rectangular survey only', 'All three methods equally', 'Only lot-and-block',
   'A', 'Pennsylvania utiliza los métodos de metes-and-bounds (linderos y medidas) y lot-and-block (lote y bloque de plano registrado). Pennsylvania NO utiliza el sistema de encuesta rectangular (rectangular survey / government survey), que es más común en estados del centro y oeste de EE.UU.', Unidad 4, pág. ~92);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 5, 'In the rectangular survey system, a township contains:',
   '1 section of 640 acres', '36 sections of 640 acres each, totaling 23,040 acres', '6 sections of 1 mile each', '640 sections of 1 acre each',
   'B', 'En el sistema de encuesta rectangular, un ''township'' (municipio) es un cuadrado de 6 millas por 6 millas, dividido en 36 secciones. Cada sección mide 1 milla cuadrada = 640 acres. Por lo tanto, un township = 36 secciones × 640 acres = 23,040 acres. Las secciones se numeran del 1 al 36 comenzando en la esquina NE.', Unidad 4, pág. ~96);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 10, 'In a metes-and-bounds legal description, a ''monument'' is BEST described as:',
   'A large stone marker placed by the county', 'A fixed object used as a reference point to identify a boundary', 'The starting point of any legal description', 'A measurement of distance in feet or yards',
   'B', 'Un ''monumento'' (monument) en una descripción metes-and-bounds es un objeto FIJO usado como punto de referencia para identificar límites de propiedad. Puede ser natural (árbol, roca, río) o artificial (estaca, poste, esquina de edificio). Principio legal: la ubicación real del monumento prevalece sobre las medidas escritas si hay discrepancia.', Unidad 4, pág. ~93);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 13, 'A lot-and-block legal description identifies property by:',
   'Compass directions and distances from a starting point', 'Lot number, block number, subdivision name, and county and state', 'Township, range, and section numbers', 'Tax parcel identification number and county map',
   'B', 'El método lot-and-block (lote y bloque) identifica la propiedad por: número de lote, número de bloque, nombre o número del plano de subdivisión, y el condado y estado. El plato (plat) debe estar registrado en el condado. Este método se creó para describir propiedades en subdivisiones urbanas de manera simple.', Unidad 4, pág. ~94);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 14, 'In the rectangular survey system, one section of land equals:',
   '640 acres — one square mile', '36 acres — six by six furlongs', '43,560 acres', '160 acres — one quarter section',
   'A', 'Una ''sección'' (section) en el sistema de encuesta rectangular mide 1 milla cuadrada = 640 acres. Un township tiene 36 secciones. Un cuarto de sección (¼ section) = 160 acres. Un cuarto de cuarto (¼ × ¼) = 40 acres. Memotécnico: 1 sección = 640 acres = 1 milla².', Unidad 4, pág. ~96);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 15, 'In the rectangular survey system, townships are created by the intersection of:',
   'Lot lines and block lines', 'Principal meridians (running north-south) and base lines (running east-west)', 'State boundary lines and county lines', 'Section lines running diagonally',
   'B', 'El sistema rectangular se basa en líneas de referencia: meridianos principales (principal meridians) que corren N-S, y líneas base (base lines) que corren E-O. Su intersección crea una cuadrícula. Las filas de townships E-O desde la línea base se llaman ''tiered''; las columnas N-S desde el meridiano se llaman ''ranges''.', Unidad 4, pág. ~95);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 16, 'An Improvement Location Certificate (ILC) in Pennsylvania:',
   'Is a full survey that establishes exact property boundaries', 'Makes the surveyor liable for the accuracy of property lines', 'Is NOT a survey; it only shows the location of improvements on a lot and does not establish boundary lines', 'Is required on all residential sales over $200,000',
   'C', 'Un ILC (Certificado de Ubicación de Mejoras) en Pennsylvania NO es una encuesta completa. Solo muestra la ubicación aproximada de las mejoras (casa, garaje) en el lote. El agrimensor NO asume responsabilidad por los límites de la propiedad. Para una encuesta completa con límites legales, se requiere un agrimensor de tierras registrado en PA.', Unidad 4, pág. ~98);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 18, 'When there is a conflict between a written measurement and the actual location of a monument in a metes-and-bounds description, which prevails?',
   'The written measurement always controls', 'The actual location of the monument prevails over written measurements', 'The courts must decide which to use on a case-by-case basis', 'The more recent survey controls regardless of monuments',
   'B', 'Principio legal establecido: la ubicación REAL del monumento (monument) prevalece sobre las medidas escritas si hay discrepancia. La razón: los monumentos físicos son más confiables que medidas que pudieron haber sido calculadas incorrectamente. Esto es parte del orden de prioridad en resolución de conflictos de descripción legal.', Unidad 4, pág. ~93);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 19, 'Pennsylvania law requires that any survey of a parcel of land be performed by:',
   'Any licensed real estate broker', 'A county assessor', 'A registered land surveyor', 'A title insurance company representative',
   'C', 'En Pennsylvania, cualquier encuesta (survey) de una parcela de tierra debe ser realizada por un agrimensor de tierras REGISTRADO (registered land surveyor). Los agentes de bienes raíces no pueden realizar encuestas. Los ILC (que no son encuestas completas) sí pueden ser realizados por profesionales con menor certificación.', Unidad 4, pág. ~98);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (4, 20, 'Which statement about the rectangular survey system is CORRECT?',
   'It is the primary method used in Pennsylvania', 'Each range line runs east and west', 'A township is six miles square and contains 36 sections', 'Sections are numbered starting in the southwest corner',
   'C', 'En el sistema rectangular: un ''township'' es un cuadrado de 6 millas × 6 millas con 36 secciones. Dato clave: las secciones se numeran comenzando en la esquina NORESTE (no suroeste) y van en serpentina. PA NO usa este sistema. Las líneas de rango (range lines) corren N-S (no E-O).', Unidad 4, pág. ~96);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 1, 'The acronym PETE represents the four governmental powers that limit private property ownership. What does PETE stand for?',
   'Possession, Easement, Title, Encumbrance', 'Police power, Eminent domain, Taxation, Escheat', 'Purchase, Equity, Transfer, Encumbrance', 'Property, Estate, Title, Encroachment',
   'B', 'PETE son las cuatro limitaciones gubernamentales sobre la propiedad privada: (P)olice power (poder de policía — zonificación, códigos), (E)minent domain (dominio eminente — toma para uso público), (T)axation (impuestos — impuesto predial), (E)scheat (reversión al estado si el propietario muere sin herederos). Ninguna requiere compensación excepto el dominio eminente.', Unidad 5, pág. ~111);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 2, 'Which statement CORRECTLY distinguishes eminent domain from condemnation?',
   'They are the same thing; the terms are interchangeable', 'Eminent domain is the RIGHT of the government; condemnation is the PROCESS used to exercise that right', 'Condemnation is voluntary; eminent domain is involuntary', 'Eminent domain applies only to residential property; condemnation applies to commercial',
   'B', 'Distinción importante: el ''dominio eminente'' (eminent domain) es el DERECHO inherente del gobierno de tomar propiedad privada para uso público. La ''condena'' (condemnation) es el PROCESO legal que se usa para ejercer ese derecho. Se requiere justa compensación (5ª Enmienda). PA: los bienes personales Y reales escaetan al estado.', Unidad 5, pág. ~112);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 3, 'A property owner holds ''fee simple absolute.'' This means the owner has:',
   'The right to use the property for 99 years', 'The highest form of ownership — complete and unlimited ownership with no conditions', 'Ownership subject to the condition that the property be used for residential purposes', 'Ownership shared with the government',
   'B', 'El ''fee simple absolute'' es la forma MÁS ALTA de propiedad inmobiliaria. El propietario tiene titularidad completa, sin condiciones, ilimitada en tiempo, y puede transferirse libremente. No hay cláusulas que puedan hacer que la propiedad revierta a alguien más. Es el tipo de propiedad más común en transacciones residenciales.', Unidad 5, pág. ~114);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 4, 'A deed grants property ''to the City of Philadelphia, so long as it is used as a public park.'' This creates a:',
   'Fee simple absolute', 'Fee simple determinable', 'Fee simple subject to a condition subsequent', 'Life estate',
   'B', 'El ''fee simple determinable'' se crea con palabras como ''so long as'', ''while'', ''during'', o ''until''. Si la condición se viola, la propiedad AUTOMÁTICAMENTE revierte al otorgante o sus herederos (sin necesidad de acción judicial). Las palabras clave son ''so long as'' en la pregunta. Diferente del ''fee simple subject to condition subsequent'' que requiere acción legal.', Unidad 5, pág. ~115);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 5, 'A deed states property is granted ''on condition that'' it be used as a school, ''but if'' it ceases to be used as a school, the grantor has the right to re-enter. This creates a:',
   'Fee simple absolute', 'Fee simple determinable', 'Fee simple subject to a condition subsequent', 'Defeasible fee with automatic reversion',
   'C', '''Fee simple subject to condition subsequent'' usa las palabras ''on condition that'', ''provided that'', o ''but if''. La diferencia crucial: la propiedad NO revierte automáticamente. El otorgante debe tomar acción legal (ir a la corte) para ejercer el derecho de re-entrada. Palabras clave aquí: ''on condition that'' + ''right to re-enter''.', Unidad 5, pág. ~115);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 6, 'A life estate is BEST described as:',
   'An ownership interest that lasts forever', 'A freehold estate limited in duration to the life of a specified person', 'A leasehold interest that terminates on the death of the lessee', 'A tenancy that continues indefinitely until notice is given',
   'B', 'Un ''life estate'' (patrimonio vitalicio) es un interés de propiedad cuya duración está limitada a la vida de una persona determinada. El ''life tenant'' puede usar, arrendar y mejorar la propiedad pero NO puede venderla en fee simple ni hipotecarla más allá de su vida. Cuando muere, la propiedad va al ''remainderman'' o revierte al otorgante.', Unidad 5, pág. ~116);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 7, 'A life estate measured by the life of someone OTHER than the life tenant is called:',
   'A fee simple determinable', 'A remainder interest', 'Pur autre vie', 'An estate in reversion',
   'C', '''Pur autre vie'' significa ''por la vida de otro''. Ejemplo: ''a Ana por la vida de Carlos''. Ana tiene el life estate, pero dura mientras Carlos viva, no mientras Ana viva. Si Carlos muere primero, Ana pierde el estate aunque ella siga viva. Es un tipo especial de life estate medido por la vida de una tercera persona.', Unidad 5, pág. ~116);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 8, 'Under Pennsylvania law, a surviving spouse of a deceased property owner is entitled to inherit:',
   'The entire estate regardless of the will', 'One-half of the deceased spouse''s estate', 'One-third of the deceased spouse''s estate if there are children, or the entire estate if there are no children', 'Nothing unless specifically named in the will',
   'C', 'En Pennsylvania, el cónyuge sobreviviente puede elegir tomar UN TERCIO del patrimonio del cónyuge fallecido (elective share), independientemente de lo que diga el testamento, si hay hijos. Si no hay hijos, el cónyuge puede tener derecho al patrimonio completo. Este derecho protege al cónyuge de ser desamparado en el testamento. ACLARACIÓN IMPORTANTE: El ''elective share'' (1/3) aplica cuando hay un testamento — el cónyuge puede renunciar al testamento y elegir tomar el tercio. Por sucesión intestada (sin testamento), la participación del cónyuge en Pennsylvania varía: si tiene hijos (de su matrimonio con el difunto), recibe los primeros $30,000 más la mitad del resto; si no tiene hijos ni padres sobrevivientes, recibe el patrimonio completo. La respuesta C captura los dos escenarios clave del examen.', Unidad 5, pág. ~117);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 9, 'An appurtenant easement involves two parcels. The parcel that BENEFITS from the easement is called the:',
   'Servient tenement', 'Dominant tenement', 'Easement tenement', 'Burdened estate',
   'B', 'En una servidumbre apurtenante (appurtenant easement) hay dos parcelas: el ''dominant tenement'' (fundo dominante) es el que SE BENEFICIA de la servidumbre (tiene el derecho de paso, por ejemplo). El ''servient tenement'' (fundo sirviente) es el que SOPORTA la carga de la servidumbre. La servidumbre ''corre con la tierra'' (runs with the land) y se transfiere con la propiedad.', Unidad 5, pág. ~119);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 10, 'An easement in gross that is held for commercial purposes (such as a utility company''s right-of-way) is:',
   'Personal and cannot be assigned or transferred', 'Assignable and transferable', 'Automatically terminated when the property is sold', 'Only valid for 21 years under Pennsylvania law',
   'B', 'Las servidumbres ''in gross'' existen independientemente de la tierra adyacente (no hay dominant tenement). Las servidumbres in gross COMERCIALES (ej: compañía eléctrica) son ASIGNABLES y transferibles. Las servidumbres in gross PERSONALES (ej: derecho a pescar en el lago del vecino) NO son asignables ni transferibles y terminan con la muerte del titular.', Unidad 5, pág. ~120);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 11, 'To establish an easement by prescription in Pennsylvania, the use must be continuous, open, notorious, hostile, and adverse for a period of:',
   '5 years', '10 years', '21 years', '30 years',
   'C', 'En Pennsylvania, para establecer una servidumbre por prescripción, el uso debe cumplir el acrónimo CANOE: Continuous (continuo), Adverse (adverso), Notorious (notorio/visible), Outstanding/Exclusive (exclusivo), y durar 21 AÑOS. Similar a la posesión adversa. El uso permisivo (con permiso del dueño) NO puede crear una servidumbre por prescripción.', Unidad 5, pág. ~121);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 12, 'A license in real estate is BEST described as:',
   'A permanent right to use another''s land that runs with the property', 'A personal, revocable privilege to use another''s land for a specific purpose', 'An easement created by written agreement', 'A government permit to construct a building',
   'B', 'Una ''licencia'' (license) en bienes raíces es un privilegio PERSONAL y REVOCABLE para usar la propiedad de otro para un propósito específico. A diferencia de una servidumbre, puede ser terminada en cualquier momento por el otorgante. También termina automáticamente con la muerte de cualquiera de las partes. No corre con la tierra.', Unidad 5, pág. ~122);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 13, 'Under riparian rights, the owner of land along a NON-navigable stream typically owns:',
   'Only to the water''s edge', 'To the center (thread) of the stream', 'The entire stream if it borders only their property', 'No rights to the water whatsoever',
   'B', 'Derechos ribereños (riparian rights): para ríos o arroyos NO navegables, el propietario ribereño posee hasta el CENTRO (hilo) del arroyo. Para ríos NAVEGABLES, el propietario solo posee hasta el borde del agua (water''s edge); el estado o el público controla la vía navegable. Derechos litorales (littoral) aplican a lagos y océanos.', Unidad 5, pág. ~123);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 15, 'The gradual deposit of soil by water action, which increases a property owner''s land, is called:',
   'Erosion', 'Avulsion', 'Accretion', 'Reliction',
   'C', 'La ''acreción'' (accretion) es el depósito GRADUAL de suelo arrastrado por el agua que AUMENTA la tierra del propietario ribereño. El material depositado se llama ''alluvion'' o ''alluvium''. Contraste: erosión = pérdida gradual de tierra; avulsión = remoción SÚBITA de tierra por acción del agua; relicción = tierra expuesta por retiro de agua.', Unidad 5, pág. ~124);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 16, 'An ''estate for years'' is BEST described as:',
   'A leasehold that automatically renews each year', 'A leasehold for a fixed, definite period of time with a specific beginning and end date', 'An ownership interest that lasts exactly one year', 'A periodic tenancy that can only be terminated at year-end',
   'B', 'Un ''estate for years'' (arrendamiento por tiempo determinado) es un arrendamiento por un período FIJO y DEFINIDO con fecha de inicio y fin específicas. NO se renueva automáticamente. Al terminar el plazo, finaliza sin necesidad de previo aviso. El nombre ''estate for years'' es engañoso: puede durar días, meses o décadas; lo clave es el período fijo.', Unidad 5, pág. ~125);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 17, 'A periodic tenancy is BEST described as:',
   'A leasehold with a fixed end date', 'A tenancy that continues for successive periods until proper notice is given by either party', 'A tenancy at the will of the landlord only', 'An ownership that lasts for the life of the tenant',
   'B', 'Un ''periodic tenancy'' (arrendamiento periódico) se renueva automáticamente por períodos sucesivos (mes a mes, año a año) hasta que una de las partes dé aviso de terminación. El período de aviso requerido generalmente equivale a un período de renta (ej: 30 días para un arrendamiento mes a mes). Es la forma más común de arrendamiento residencial.', Unidad 5, pág. ~125);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 18, 'A tenancy at will:',
   'Lasts for a fixed period agreed upon by landlord and tenant', 'Automatically renews each month unless notice is given 30 days in advance', 'Can be terminated at any time by either the landlord or the tenant', 'Cannot be terminated without a court order',
   'C', 'Un ''tenancy at will'' (arrendamiento a voluntad) es un arrendamiento sin plazo fijo que PUEDE SER TERMINADO EN CUALQUIER MOMENTO por CUALQUIERA de las partes (arrendador o arrendatario) con poco o ningún aviso. Es el tipo de arrendamiento más informal y menos seguro para el arrendatario. No tiene protecciones específicas de plazo.', Unidad 5, pág. ~126);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (5, 19, 'A person occupies another''s property without permission after their lease has expired. This is called a:',
   'Periodic tenancy', 'Tenancy at will', 'License', 'Estate at sufferance',
   'D', 'Un ''estate at sufferance'' (arrendamiento por tolerancia) ocurre cuando un arrendatario que tenía un arrendamiento válido continúa ocupando la propiedad SIN PERMISO después de que el arrendamiento expira. El arrendatario se convierte en un ''holdover tenant''. El propietario puede desalojarlo o, en algunos estados, convertirlo en arrendatario periódico aceptando su renta.', Unidad 5, pág. ~126);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 3, 'In a tenancy in common, which of the following statements is CORRECT?',
   'All co-owners must hold equal shares', 'The right of survivorship applies automatically to all co-owners', 'Co-owners hold undivided interests with the right of possession of the whole property; shares need not be equal', 'The property cannot be sold without unanimous consent of all co-owners',
   'C', 'En la ''tenancy in common'' (copropiedad por partes alícuotas), los copropietarios tienen intereses indivisos sobre la propiedad. Las características: (1) las participaciones NO necesitan ser iguales, (2) NO hay derecho de supervivencia (survivorship), (3) cada copropietario puede vender, hipotecar o legar su parte independientemente, (4) el único ''unity'' requerido es la posesión.', Unidad 6, pág. ~143);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 4, 'For a valid joint tenancy to exist, all co-owners must acquire their interests at the same time, in the same deed, with equal shares, and with the right to possess the whole property. These requirements are known as the four ''unities'' of:',
   'Time, Title, Interest, and Possession (TTIP)', 'Possession, Interest, Time, and Title (PITT)', 'Purpose, Intent, Tenure, and Title (PITT)', 'Partition, Inheritance, Transfer, and Title',
   'B', 'Las cuatro ''unidades'' de la joint tenancy son PITT: (P)ossession (todos poseen juntos), (I)nterest (partes iguales), (T)ime (adquiridas al mismo tiempo), (T)itle (en el mismo instrumento/escritura). La característica MÁS IMPORTANTE: el derecho de supervivencia (right of survivorship) — al morir un copropietario, su parte pasa automáticamente a los sobrevivientes, sin pasar por sucesión.', Unidad 6, pág. ~144);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 5, 'Under Pennsylvania law, a joint tenancy with right of survivorship:',
   'Is created automatically when two or more people purchase property together', 'Must be clearly and expressly stated in the deed to be recognized', 'Is the same as tenancy by the entirety', 'Is prohibited in Pennsylvania',
   'B', 'En Pennsylvania, el derecho de supervivencia de la joint tenancy DEBE estar claramente expresado en la escritura para ser reconocido. Si dos personas compran juntas sin especificar la forma de copropiedad, se presume ''tenancy in common'' (sin survivorship). Excepción en PA: un marido y esposa que compran juntos automáticamente crean una ''tenancy by the entirety''.', Unidad 6, pág. ~144);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 6, 'A co-owner of property held in tenancy in common wishes to end the co-ownership and separate the property. The legal process to accomplish this is called:',
   'Severance', 'Condemnation', 'Partition', 'Adverse possession',
   'C', 'La ''partición'' (partition) es el proceso legal para disolver la copropiedad de bienes raíces. Puede ser voluntaria (acuerdo entre los copropietarios) o judicial (el tribunal divide o vende la propiedad). Aplica a la tenancy in common y joint tenancy. En la tenancy by the entirety, los cónyuges NO pueden pedir partición unilateralmente.', Unidad 6, pág. ~145);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 7, 'Tenancy by the entirety is a form of co-ownership available ONLY to:',
   'Business partners', 'Any two people who purchase property together', 'Legally married spouses', 'Parents and their adult children',
   'C', 'La ''tenancy by the entirety'' (copropiedad conyugal) está disponible SOLO para cónyuges legalmente casados. En Pennsylvania, cuando un esposo y esposa compran propiedad juntos, automáticamente crean esta forma de copropiedad. Características: derecho de supervivencia, NO puede ser transferida sin el consentimiento de ambos, y ningún acreedor de UN cónyuge puede ejecutarla.', Unidad 6, pág. ~146);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 8, 'A tenancy by the entirety can be terminated by all of the following EXCEPT:',
   'Death of one spouse', 'Voluntary agreement of both spouses', 'Divorce', 'The unilateral decision of one spouse',
   'D', 'La tenancy by the entirety SOLO puede terminarse por: J''s DAD: (J)udgment sale (venta por sentencia judicial CONTRA AMBOS), (D)eath (muerte de un cónyuge), (A)greement (acuerdo mutuo de ambos), (D)ivorce (divorcio). Un solo cónyuge NO puede terminarla unilateralmente ni hipotecarla sin el consentimiento del otro.', Unidad 6, pág. ~146);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 9, 'In a land trust, the beneficial interest held by the beneficiary is classified as:',
   'Real property', 'Personal property', 'Both real and personal property', 'A freehold estate',
   'B', 'En un ''land trust'' (fideicomiso de tierras), el único activo es la propiedad inmueble. Aunque la propiedad es bienes raíces, el interés beneficiario (beneficial interest) del beneficiario se clasifica como PROPIEDAD PERSONAL. Ventaja: el nombre del beneficiario no aparece en los registros públicos. El fideicomisario (trustee) aparece en el título.', Unidad 6, pág. ~147);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 11, 'In a general partnership, the liability of each partner for the debts and obligations of the partnership is:',
   'Limited to the amount each partner invested', 'Full personal liability for all partnership debts', 'Limited to 50% of the partnership debts', 'Eliminated by filing with the state',
   'B', 'En una ''sociedad general'' (general partnership), TODOS los socios tienen responsabilidad personal ILIMITADA por todas las deudas y obligaciones de la sociedad. Esto significa que los acreedores pueden perseguir los bienes personales de cualquier socio. En una ''limited partnership'', los socios limitados tienen responsabilidad limitada a su inversión; solo el socio general tiene responsabilidad ilimitada.', Unidad 6, pág. ~149);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 12, 'An S corporation in real estate:',
   'Pays corporate income tax and then distributes after-tax profits', 'Avoids double taxation by passing profits and losses directly to shareholders', 'Can have unlimited shareholders', 'Is required for all real estate businesses in Pennsylvania',
   'B', 'Una ''corporación S'' (S corporation) evita la doble imposición: las ganancias y pérdidas pasan directamente a los accionistas (máximo 100), quienes las reportan en sus declaraciones personales de impuestos. A diferencia de la corporación C (que paga impuestos corporativos y luego los accionistas pagan sobre dividendos), la S corporation elimina el nivel corporativo de impuestos.', Unidad 6, pág. ~150);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 14, 'In a cooperative (co-op), a resident''s ownership interest is evidenced by:',
   'A deed to their individual unit', 'Stock in the corporation plus a proprietary lease to occupy the unit', 'A condominium declaration and unit deed', 'A partnership agreement with the building owner',
   'B', 'En un ''cooperative'' (cooperativa), una CORPORACIÓN es dueña del edificio entero. Los residentes poseen ACCIONES (stock) de esa corporación y tienen un ''proprietary lease'' (arrendamiento propietario/de dueño) que les da derecho a ocupar su unidad. No tienen una escritura de su unidad individual. El interés posesorio se evidencia por el contrato de arrendamiento propietario.', Unidad 6, pág. ~152);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 15, 'The PRIMARY difference between a condominium and a cooperative is:',
   'Condominiums can only be residential; cooperatives can be commercial', 'In a condominium, the owner holds fee simple title to the unit; in a cooperative, residents own stock and a lease', 'Condominiums have no monthly fees; cooperatives have HOA fees', 'Cooperatives are only found in New York; condominiums are in all states',
   'B', 'Diferencia fundamental: en un CONDOMINIO, el propietario tiene título en ''fee simple'' de su unidad individual (escritura propia) más una parte indivisa de las áreas comunes. En una COOPERATIVA, no hay escritura individual; el residente posee acciones de la corporación y tiene un arrendamiento propietario. En el condo, el propietario puede hipotecar solo su unidad.', Unidad 6, pág. ~151);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 16, 'A Planned Unit Development (PUD) is BEST described as:',
   'A subdivision with only single-family homes on large lots', 'A development that integrates diverse land uses (residential, commercial, open space) governed by special zoning', 'A government-subsidized housing project', 'A condominium development with more than 100 units',
   'B', 'Un ''Planned Unit Development'' (PUD / Desarrollo de Unidad Planificada) es un tipo de desarrollo que combina usos diversos del suelo (residencial, comercial, espacios abiertos, recreación) en un diseño integrado. Se rige por ordenanzas de zonificación especiales que permiten flexibilidad. Los propietarios pagan cuotas a una HOA que mantiene las áreas comunes.', Unidad 6, pág. ~153);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (6, 17, 'A Limited Liability Company (LLC) combines characteristics of both a corporation and a partnership. Its main advantage in real estate is:',
   'No management structure is required', 'Members enjoy limited liability while avoiding double taxation', 'It can only have one member', 'Members are personally liable for all company debts',
   'B', 'Una LLC (Sociedad de Responsabilidad Limitada) combina lo mejor de dos mundos: (1) como corporación, los ''members'' (socios) tienen responsabilidad LIMITADA (no son personalmente responsables de las deudas de la LLC), y (2) como sociedad general, las ganancias y pérdidas pasan directamente a los miembros sin doble imposición. Es muy popular en inversiones inmobiliarias.', Unidad 6, pág. ~150);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 1, 'A lien that affects ALL property owned by a debtor (both real and personal) is called a:',
   'Specific lien', 'General lien', 'Mechanic''s lien', 'Voluntary lien',
   'B', 'Un ''gravamen general'' (general lien) afecta TODA la propiedad del deudor, tanto inmueble como personal. Ejemplos: sentencias judiciales (judgment liens), impuestos federales sobre el patrimonio, gravámenes del IRS. Un ''gravamen específico'' (specific lien) solo afecta una propiedad concreta, como una hipoteca o un gravamen de mecánico.', Unidad 7, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 2, 'The general rule for lien priority is:',
   'The lien with the largest amount takes priority', 'Government liens always have first priority', 'First to be recorded has priority — ''first in time, first in right''', 'The most recently recorded lien has priority',
   'C', 'La regla general de prioridad de gravámenes es ''first in time, first in right'' (primero en registrar, primero en derecho). El gravamen registrado primero tiene prioridad sobre los posteriores. EXCEPCIÓN IMPORTANTE: los impuestos inmobiliarios (real estate taxes) y las evaluaciones especiales (special assessments) tienen PRIORIDAD SOBRE TODOS los demás gravámenes, independientemente de cuándo se registraron.', Unidad 7, pág. ~167);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 3, 'Which of the following liens ALWAYS has priority over ALL other liens, regardless of the date they were recorded?',
   'First mortgage liens', 'Federal income tax liens', 'Real estate property taxes and special assessments', 'Mechanic''s liens',
   'C', 'Los impuestos inmobiliarios (real estate taxes) y las evaluaciones especiales (special assessments) son la excepción principal a la regla de ''primero en registrar''. Estos gravámenes tienen PRIORIDAD AUTOMÁTICA sobre TODOS los demás gravámenes, incluyendo hipotecas de primer rango. Esto es porque el gobierno necesita asegurarse de cobrar sus impuestos.', Unidad 7, pág. ~167);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 4, 'A mill, as used in property tax calculations, equals:',
   '$1.00 per $1,000 of assessed value ($0.001)', '$10.00 per $1,000 of assessed value', '$1.00 per $100 of assessed value', 'One-tenth of a cent',
   'A', 'Un ''mill'' (milésima) = $0.001 = $1 por cada $1,000 de valor tasado. Ejemplo de cálculo: si la tasa es 25 mills y el valor tasado es $100,000: 25 mills × $100,000 / 1,000 = $2,500 de impuesto anual. También se puede expresar como: valor tasado × tasa en decimales ($100,000 × 0.025 = $2,500).', Unidad 7, pág. ~169);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 5, 'Pennsylvania''s Property Tax Rebate program (funded by the PA Lottery) is available to homeowners who are:',
   'Any PA homeowner regardless of age or income', 'Age 65+, widows/widowers age 50+, or disabled persons age 18+, with income limits', 'Only residents age 70 or older', 'Renters only, not homeowners',
   'B', 'El programa de rebate de impuesto predial de PA (financiado por la Lotería de PA) es para: propietarios de 65+ años, viudos/viudas de 50+ años, o personas discapacitadas de 18+ años. Límite de ingresos: $45,000 para propietarios, $15,000 para arrendatarios. El rebate máximo es $817. Los arrendatarios calificados también pueden beneficiarse.', Unidad 7, pág. ~170);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 6, 'Under Pennsylvania law, a mechanic''s lien must be filed within _______ of the last work performed, and enforced within _______ of filing.',
   '3 months / 1 year', '6 months / 2 years', '1 year / 3 years', '90 days / 1 year',
   'B', 'En Pennsylvania, un ''mechanic''s lien'' (gravamen de contratistas/materiales) debe: (1) archivarse dentro de 6 MESES del último trabajo realizado, y (2) ejecutarse (foreclose) dentro de 2 AÑOS desde que se archivó. La prioridad del mechanic''s lien se establece desde la fecha del primer ''visible construction'' (construcción visible), no desde que se archivó.', Unidad 7, pág. ~172);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 7, 'Pennsylvania''s commercial real estate broker lien law allows a licensed broker to file a lien on:',
   'Any residential or commercial property where commissions are owed', 'ONLY commercial real estate (NOT 1-4 unit residential properties), and ONLY by licensed brokers', 'Only new construction properties', 'Any property if the commission exceeds $10,000',
   'B', 'La ley de gravamen de corretaje inmobiliario comercial de PA permite SOLO a corredores LICENCIADOS archivar un gravamen por comisiones no pagadas sobre BIENES RAÍCES COMERCIALES ÚNICAMENTE. NO aplica a propiedades residenciales de 1 a 4 unidades. El corredor debe archivar dentro de 90 DÍAS de la transacción y ejecutar dentro de 2 AÑOS.', Unidad 7, pág. ~173);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 8, 'Special assessments are levied against properties to pay for:',
   'General government operating expenses and salaries', 'Specific public improvements that directly benefit the assessed properties (curbs, sidewalks, sewers)', 'Federal environmental cleanup programs', 'School district budgets',
   'B', 'Las ''evaluaciones especiales'' (special assessments) son cargos contra propiedades específicas para pagar mejoras públicas que BENEFICIAN DIRECTAMENTE esas propiedades (calles, aceras, alcantarillado, alumbrado). Típicamente se pagan en 5-10 años. El interés anual sobre las evaluaciones especiales SÍ es deducible de impuestos federales.', Unidad 7, pág. ~174);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 9, 'A ''lis pendens'' is BEST described as:',
   'A court order to immediately sell a property', 'A notice recorded in public records that litigation is pending that may affect the title to a specific property', 'A tax lien placed by the IRS', 'A mechanic''s lien for unpaid construction work',
   'B', 'Un ''lis pendens'' (pleito pendiente) es un aviso registrado en los registros públicos que informa que hay un litigio PENDIENTE que puede afectar el título de una propiedad específica. Avisa a posibles compradores de que el título puede estar sujeto a cambios por la decisión judicial. No es un gravamen en sí mismo, sino un aviso de posible gravamen futuro.', Unidad 7, pág. ~175);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 10, 'Real estate taxes are calculated based on:',
   'The purchase price of the property', 'The replacement cost of improvements only', 'The assessed value of the property multiplied by the tax (mill) rate', 'The income produced by the property',
   'C', 'Los impuestos inmobiliarios (property taxes / ad valorem taxes) se calculan multiplicando el VALOR TASADO (assessed value) por la TASA IMPOSITIVA (tax/mill rate). Fórmula: Valor de mercado × Ratio de tasación = Valor tasado; Valor tasado × Tasa = Impuesto anual. ''Ad valorem'' significa ''según el valor'' en latín.', Unidad 7, pág. ~168);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 11, 'A subordination agreement in real estate allows:',
   'A senior lien to move to a lower priority position', 'A junior lien to move to a higher priority position', 'Either lien holder to change the priority of their lien relative to another', 'The government to take priority over all private liens',
   'C', 'Un ''acuerdo de subordinación'' (subordination agreement) es un contrato en el que el titular de un gravamen acepta cambiar la prioridad de su gravamen. Por ejemplo, un primer gravamen hipotecario puede aceptar subordinarse a un nuevo préstamo de construcción. Permite a los titulares de gravámenes acordar mutuamente el orden de prioridad.', Unidad 7, pág. ~176);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 12, 'A judgment lien against a property owner is an example of a:',
   'Specific voluntary lien', 'Specific involuntary lien', 'General involuntary lien', 'General voluntary lien',
   'C', 'Un ''gravamen de sentencia judicial'' (judgment lien) es: GENERAL (afecta TODA la propiedad del deudor, no una propiedad específica) e INVOLUNTARIO (impuesto por el tribunal sin el consentimiento del deudor). Una hipoteca, en cambio, es un gravamen ESPECÍFICO y VOLUNTARIO. Los impuestos prediales son gravámenes específicos e involuntarios.', Unidad 7, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 13, 'In Pennsylvania, when a property is sold at a tax sale for unpaid real estate taxes, the original owner:',
   'Has a 2-year right of redemption to reclaim the property', 'Has a 1-year statutory right of redemption', 'Has NO redemption period; the sale is final', 'Can redeem the property at any time by paying the back taxes plus interest',
   'C', 'En Pennsylvania, NO existe período de redención (redemption period) para el propietario que pierde su propiedad en una venta por impuestos (tax sale). Una vez vendida en la subasta por impuestos vencidos, la venta es DEFINITIVA. Esto es diferente de otros estados que otorgan al propietario tiempo para redimir la propiedad pagando los impuestos más costos.', Unidad 7, pág. ~171);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 14, 'An IRS federal tax lien is an example of a:',
   'Specific voluntary lien', 'Specific involuntary lien', 'General involuntary lien', 'Equitable lien',
   'C', 'Un gravamen fiscal federal del IRS es GENERAL (afecta toda la propiedad del deudor, tanto inmueble como personal) e INVOLUNTARIO (impuesto por el gobierno sin el consentimiento del contribuyente). Es uno de los gravámenes más poderosos y difíciles de superar en el orden de prioridad, aunque los impuestos prediales locales lo superan.', Unidad 7, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 15, 'The priority of a Pennsylvania mechanic''s lien is established from:',
   'The date the lien was filed in the court', 'The date the first ''visible construction'' began on the property', 'The date the contractor signed the construction contract', 'The date the building permit was issued',
   'B', 'La prioridad del mechanic''s lien en PA se establece desde la fecha del primer ''VISIBLE CONSTRUCTION'' (primera construcción visible), que puede ser antes de que el gravamen se archive formalmente. Esto protege a los contratistas que comenzaron a trabajar antes de que otros gravámenes fueran archivados. El gravamen puede retroactivamente tener prioridad sobre hipotecas registradas después.', Unidad 7, pág. ~172);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 16, 'Which of the following BEST describes an ad valorem tax?',
   'A tax based on the income produced by a property', 'A tax imposed according to the value of the property', 'A special assessment for a specific public improvement', 'A transfer tax paid when property is sold',
   'B', '''Ad valorem'' significa ''según el valor'' en latín. Un impuesto ad valorem se basa en el VALOR de la propiedad. El impuesto predial anual es el ejemplo principal: se calcula sobre el valor tasado de la propiedad. Diferente de un impuesto fijo (flat tax) que es el mismo para todos, o de un impuesto especial que paga por una mejora específica.', Unidad 7, pág. ~168);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 17, 'A homeowner fails to pay the property taxes. The county places a tax lien on the property. This lien is BEST classified as:',
   'Voluntary and specific', 'Involuntary and general', 'Involuntary and specific', 'Voluntary and general',
   'C', 'Un gravamen por impuestos prediales es: INVOLUNTARIO (impuesto por el gobierno sin el consentimiento del propietario — nadie ''elige'' no pagar impuestos) y ESPECÍFICO (afecta únicamente ESA propiedad específica sobre la que se deben los impuestos, no toda la propiedad del propietario). Recuerde: los gravámenes prediales tienen PRIORIDAD sobre todos los demás.', Unidad 7, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (7, 20, 'Which type of lien is created when a homeowner takes out a mortgage to purchase property?',
   'Involuntary specific lien', 'Voluntary specific lien', 'Involuntary general lien', 'Voluntary general lien',
   'B', 'Una hipoteca es un gravamen VOLUNTARIO (el propietario ELIGE hipotecar su propiedad para obtener el préstamo) y ESPECÍFICO (solo afecta ESA propiedad específica usada como garantía, no toda la propiedad del propietario). Es el tipo más común de gravamen específico voluntario en bienes raíces.', Unidad 7, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 1, 'Which of the following is an ESSENTIAL element of a valid deed?',
   'Earnest money deposit from the buyer', 'Notarization by a notary public', 'A granting clause identifying the grantor and grantee with consideration', 'Recording in the county recorder''s office',
   'C', 'Los elementos ESENCIALES de una escritura válida incluyen: otorgante con capacidad legal (18+), nombre del otorgado (grantee), consideración, cláusula de otorgamiento (granting clause), descripción legal exacta, firma del otorgante, y entrega y aceptación. La notarización es necesaria para registrar pero NO para la validez. El registro tampoco es esencial para la validez, pero sí para proteger al comprador.', Unidad 8, pág. ~197);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 2, 'A deed signed by a person who had their signature forged is:',
   'Voidable at the grantor''s option', 'Valid as long as it was recorded', 'Void — it has no legal effect whatsoever', 'Valid only if the grantee paid value',
   'C', 'Una escritura con firma FALSIFICADA (forged) es absolutamente NULA (VOID) — no tiene ningún efecto legal. No se puede ratificar, no puede transferir título válido, y no crea ningún derecho para el adquirente. Un título basado en una escritura falsificada nunca puede convertirse en válido. Compare: una escritura firmada por un menor es VOIDABLE (anulable), no void.', Unidad 8, pág. ~198);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 3, 'A deed signed by a minor (someone under 18) is:',
   'Void — it has absolutely no legal effect', 'Voidable — it can be disaffirmed by the minor upon reaching majority', 'Valid — minors can convey real estate with parental permission', 'Illegal — minors cannot sign any document',
   'B', 'Una escritura firmada por un MENOR (menor de 18 años) es ANULABLE (VOIDABLE), no nula. Esto significa que es válida y ejecutable HASTA QUE el menor la desafíe. Al llegar a la mayoría de edad, el menor puede: (1) ratificarla (confirmarla) o (2) desafiarla (disaffirm). Si la ratifica, se vuelve completamente vinculante. Compare: una escritura con firma falsificada es VOID (nula ab initio).', Unidad 8, pág. ~198);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 8, 'A quitclaim deed:',
   'Provides the greatest protection against title defects going back to the original grant', 'Warrants the title only against claims arising during the grantor''s ownership', 'Transfers whatever interest the grantor has with NO warranties whatsoever', 'Is commonly used in arm''s-length residential sales transactions',
   'C', 'Una ''quitclaim deed'' transfiere CUALQUIER INTERÉS que el otorgante tenga — que puede ser nada — SIN NINGUNA GARANTÍA. Es la escritura con MENOS protección. No garantiza que el otorgante tenga algún título válido. Se usa típicamente para: eliminar nubes en el título (cloud on title), transferencias entre familiares, y corrección de escrituras anteriores.', Unidad 8, pág. ~200);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 9, 'A general warranty deed provides the GREATEST protection to the buyer because:',
   'It is required by law in Pennsylvania for all residential sales', 'The grantor warrants and defends the title against ALL claims from ANY source — including before the grantor owned it', 'The grantor warrants only against claims arising during their ownership', 'It includes a survey of the property',
   'B', 'La ''general warranty deed'' otorga la MAYOR protección al comprador. El otorgante garantiza el título contra TODOS los defectos, desde el origen de la propiedad hasta el momento de la transferencia, incluyendo el tiempo ANTES de que el otorgante la poseyera. Las seis garantías (covenants): seisin, quiet enjoyment, against encumbrances, further assurance, warranty forever, right to convey.', Unidad 8, pág. ~199);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 10, 'Pennsylvania imposes a real estate transfer tax of 2% of the sales price. How is this tax typically divided?',
   'Buyer pays 2%; seller pays nothing', 'Seller pays 2%; buyer pays nothing', '1% paid by the state and 1% by the local municipality; typically shared equally between buyer and seller', 'Split equally only if agreed in the contract',
   'C', 'El impuesto de transferencia inmobiliaria de PA es del 2%: 1% para el estado y 1% para el municipio local. Por convenio, normalmente el comprador Y el vendedor CADA UNO paga el 1% (total 2%). Sin embargo, esto puede negociarse en el contrato de compraventa. En Filadelfia, hay un impuesto de transferencia adicional de la ciudad.', Unidad 8, pág. ~202);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 11, 'Which of the following transactions is EXEMPT from the Pennsylvania real estate transfer tax?',
   'Sale between two unrelated strangers', 'Sale from parent to adult child', 'Sale between business partners', 'Sale of a commercial property to a corporation',
   'B', 'Las transferencias entre PADRES e HIJOS (y otros familiares directos como hermanos) están EXENTAS del impuesto de transferencia de PA. Otras exenciones: escrituras que no estén relacionadas con una venta (ej: donaciones), transferencias a entidades gubernamentales, y algunas transferencias a corporaciones o fideicomisos bajo ciertas condiciones. Las transferencias padre-hijo son las más comunes en exámenes.', Unidad 8, pág. ~202);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 12, 'To acquire title through adverse possession in Pennsylvania, a person must occupy the property openly, notoriously, exclusively, and hostilely (without permission) for:',
   '7 years', '10 years', '21 years', '30 years',
   'C', 'En Pennsylvania, la posesión adversa (adverse possession) requiere posesión CONTINUA, ABIERTA, NOTORIA, EXCLUSIVA, ADVERSA (sin permiso del dueño) por 21 AÑOS. Después de cumplir este período, el poseedor debe presentar una acción judicial (quiet title action) para obtener el título legal. Si el dueño da permiso, el período se interrumpe y comienza de nuevo.', Unidad 8, pág. ~203);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 13, 'A person who dies leaving a valid will dies:',
   'Intestate', 'Testate', 'In fee simple', 'In probate',
   'B', '''Testate'' = morir CON testamento válido. La propiedad se distribuye según las instrucciones del testamento. ''Intestate'' = morir SIN testamento. La propiedad se distribuye según las leyes de sucesión del estado (statute of descent and distribution). La propiedad transferida por testamento se llama ''devise'' (bienes raíces) o ''bequest/legacy'' (bienes personales/dinero).', Unidad 8, pág. ~204);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 14, 'Under Pennsylvania law, which types of wills are recognized?',
   'Only typed and formally witnessed wills', 'Formal attested wills, holographic (handwritten) wills, and nuncupative (oral) wills', 'Only holographic wills are valid in Pennsylvania', 'Only wills prepared by an attorney are valid',
   'B', 'Pennsylvania reconoce TRES tipos de testamentos: (1) Testamento formal atestiguado (typed/printed, signed, two witnesses), (2) Testamento holográfico (MANUSCRITO y firmado por el testador — NO requiere testigos en PA), y (3) Testamento nuncupativo (ORAL, declarado ante testigos, luego puesto por escrito). PA es uno de los pocos estados que permite los tres tipos.', Unidad 8, pág. ~205);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 15, 'In a will, the term ''devise'' refers to:',
   'Personal property left to a beneficiary', 'Money left to a beneficiary', 'Real estate left to a beneficiary through a will', 'The executor''s fee for administering the estate',
   'C', 'Terminología testamentaria: ''DEVISE'' = bienes RAÍCES transferidos por testamento (el beneficiario es el ''devisee''). ''BEQUEST'' = PROPIEDAD PERSONAL transferida por testamento. ''LEGACY'' = DINERO transferido por testamento. Ejemplo: ''Le dejo mi casa (devise) a mi hija, mis joyas (bequest) a mi esposa, y $50,000 (legacy) a mi hijo.''', Unidad 8, pág. ~204);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 16, 'The habendum clause in a deed begins with the words ''to have and to hold.'' Its purpose is to:',
   'Identify the purchase price paid for the property', 'Define and limit the extent of ownership being transferred', 'State the legal description of the property', 'List the encumbrances affecting the property',
   'B', 'La ''cláusula habendum'' (habendum clause) comienza con las palabras ''to have and to hold'' (para tener y mantener). Define y LIMITA el alcance del interés de propiedad que se transfiere. Debe ser CONSISTENTE con la cláusula de otorgamiento (granting clause). Si transfieren en fee simple en la cláusula de otorgamiento, el habendum debe confirmar ese interés.', Unidad 8, pág. ~197);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 17, 'For a deed to be valid and effective to transfer title, which of the following MUST occur?',
   'The deed must be recorded in the county recorder''s office', 'The deed must be notarized', 'The deed must be delivered by the grantor and accepted by the grantee', 'The deed must specify the purchase price',
   'C', 'Para que una escritura sea VÁLIDA y transfiera el título, DEBE ser ENTREGADA por el otorgante (grantor) y ACEPTADA por el adquirente (grantee). Sin entrega y aceptación, no hay transferencia de título, incluso si la escritura fue firmada y notariada. La entrega debe ser con la INTENCIÓN de transferir el título INMEDIATAMENTE. El registro protege pero no es esencial para la validez.', Unidad 8, pág. ~201);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 18, 'A special warranty deed differs from a general warranty deed in that the grantor warrants the title only:',
   'Against any claim that might arise from anywhere in history', 'Against claims arising during the grantor''s period of ownership', 'Against claims arising from zoning violations', 'Against encumbrances not visible on the property',
   'B', 'La ''special warranty deed'' garantiza el título SOLO contra reclamaciones que surjan DURANTE el período de propiedad del otorgante. A diferencia de la general warranty deed (que cubre toda la historia del título), la special warranty dice: ''garantizo el título contra cualquier cosa que YO hice o permití.'' Es común en transferencias de fiduciarios, ejecutores y personas en esa capacidad.', Unidad 8, pág. ~199);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (8, 19, 'Recording a deed in the county recorder''s office provides:',
   'Actual notice to the grantee of any defects in the title', 'Constructive notice to the world of the transfer of ownership', 'Government approval of the sales transaction', 'Proof that the purchase price was paid in full',
   'B', 'El registro (recording) de una escritura proporciona AVISO CONSTRUCTIVO (constructive notice) al mundo entero sobre la transferencia de propiedad. El aviso constructivo es el conocimiento que la ley presume que todos tienen sobre los documentos registrados públicamente, independientemente de si realmente los leyeron. El aviso REAL (actual notice) = conocimiento directo y personal de un hecho.', Unidad 8, pág. ~201);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 1, 'The difference between actual notice and constructive notice is:',
   'Actual notice is presumed by law; constructive notice requires direct knowledge', 'Actual notice is direct, personal knowledge of a fact; constructive notice is knowledge the law presumes you have', 'They are the same thing', 'Constructive notice only applies to recorded documents in federal courts',
   'B', 'AVISO REAL (actual notice) = conocimiento DIRECTO y PERSONAL de un hecho (ej: el comprador vio personalmente los linderos). AVISO CONSTRUCTIVO (constructive notice) = conocimiento que la ley PRESUME que todos tienen, aunque no lo sepan directamente (ej: documentos registrados en registros públicos, o posesión visible de la propiedad). El registro de documentos crea aviso constructivo.', Unidad 9, pág. ~227);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 3, 'A ''chain of title'' is BEST described as:',
   'A list of all encumbrances affecting a property', 'The chronological sequence of all recorded ownership transfers of a property from the original grant to the present', 'A physical description of a property''s boundaries', 'A court order confirming ownership',
   'B', 'La ''cadena de título'' (chain of title) es la secuencia cronológica de todas las transferencias de propiedad registradas, desde el propietario original hasta el propietario actual. Permite rastrear todos los dueños anteriores. Una ''nube en el título'' (cloud on title) es cualquier defecto que interrumpe la cadena. Una quitclaim deed se usa frecuentemente para eliminar nubes.', Unidad 9, pág. ~228);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 4, 'An abstract of title is BEST described as:',
   'A guarantee that the title is free and clear of all defects', 'A condensed summary of all recorded documents affecting a property''s title', 'A full survey of the property boundaries', 'An insurance policy protecting the buyer against title defects',
   'B', 'Un ''resumen de título'' (abstract of title) es un SUMARIO condensado de todos los documentos registrados que afectan el título de una propiedad (escrituras, hipotecas, gravámenes, sentencias, etc.). Un abogado revisa el abstract para emitir una ''opinion of title''. IMPORTANTE: el abstract NO revela encroachments (invasiones físicas) ni defectos de documentos no registrados.', Unidad 9, pág. ~228);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 6, 'Standard title insurance coverage protects against all of the following EXCEPT:',
   'Forged documents in the chain of title', 'Defects in the public record', 'Rights of parties in physical possession of the property', 'Deeds delivered under duress or by incompetent grantors',
   'C', 'La cobertura ESTÁNDAR del seguro de título protege contra defectos en registros públicos: documentos falsificados, actos de personas incompetentes, escrituras entregadas bajo coacción, descripciones legales incorrectas, y declaraciones maritales incorrectas. NO cubre: derechos de personas en posesión física (que requiere inspección/extended coverage), encroachments físicos, ni gravámenes no registrados desconocidos.', Unidad 9, pág. ~230);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 11, 'Extended (ALTA) title insurance coverage differs from standard coverage in that it ALSO covers:',
   'Defects visible in the recorded public record', 'Rights of parties in actual possession, survey issues, and unrecorded liens not known to the policyholder', 'Only commercial properties over $1 million', 'Zoning violations that occurred before the policy was issued',
   'B', 'La cobertura EXTENDIDA (ALTA/extended) añade sobre la estándar: (1) derechos de personas en POSESIÓN REAL (inquilinos, etc.), (2) problemas de encuesta (survey issues), y (3) gravámenes NO REGISTRADOS no conocidos por el asegurado (ej: mechanic''s liens por trabajo reciente). Requiere una inspección y encuesta física. Es más cara pero proporciona protección más amplia.', Unidad 9, pág. ~230);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 13, 'When a title insurance company pays a claim to its insured and then pursues the party responsible for the title defect, this is called:',
   'Indemnification', 'Subrogation', 'Escheat', 'Condemnation',
   'B', 'La ''subrogación'' (subrogation) en seguros de título ocurre cuando la compañía de seguros PAGA la reclamación al asegurado y luego ADQUIERE los derechos del asegurado para demandar a la parte RESPONSABLE del defecto de título. Ejemplo: la aseguradora paga al comprador por una falsificación, luego demanda al falsificador en nombre propio.', Unidad 9, pág. ~231);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 16, 'A UCC Financing Statement (UCC-1) filed with the recorder of deeds is used to:',
   'Transfer real estate from seller to buyer', 'Create a mortgage lien on real property', 'Establish a security interest in personal property that is used as collateral for a loan', 'Record a judgment against a debtor',
   'C', 'Un ''UCC Financing Statement'' (UCC-1) se rige por el Código Comercial Uniforme y se usa para establecer un interés de seguridad (security interest) sobre PROPIEDAD PERSONAL usada como garantía de un préstamo. Se archiva con el Registrador de Escrituras. Es importante en transacciones inmobiliarias cuando hay accesorios (fixtures) que podrían considerarse personales o reales.', Unidad 9, pág. ~232);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 17, 'A preliminary title report (or title commitment) is BEST described as:',
   'A guarantee that the buyer will receive perfect title', 'A commitment to issue a title insurance policy if certain conditions are met, showing current title status', 'A survey of the property boundaries', 'A government document verifying zoning compliance',
   'B', 'Un ''reporte preliminar de título'' (preliminary title report / title commitment) es un COMPROMISO de la compañía de seguros de título de emitir una póliza de seguro de título si se cumplen ciertas condiciones. Muestra el estado actual del título, incluyendo gravámenes, servidumbres y otros defectos encontrados en la búsqueda de título. Es el documento que el prestamista y el comprador revisan antes del cierre.', Unidad 9, pág. ~229);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (9, 18, 'A ''marketable title'' is BEST described as a title that:',
   'Has absolutely no defects of any kind', 'Is free from serious defects that would cause a reasonable buyer to reject it or significantly impair its value', 'Has been insured by a title insurance company', 'Has been held for at least 21 years without challenge',
   'B', 'Un ''título comercializable'' (marketable title) es aquel libre de DEFECTOS SERIOS que harían que un comprador razonable lo rechace o que afecten significativamente su valor. No tiene que ser perfecto — todos los títulos tienen algún defecto menor. El comprador contrata que el vendedor entregue título comercializable. Si el título no es comercializable, el comprador puede rescindir el contrato.', Unidad 9, pág. ~228);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 1, 'To be legally valid, a real estate contract must include all of the following EXCEPT:',
   'Offer and acceptance', 'Consideration', 'Competent parties', 'A notary public''s signature',
   'D', 'Un contrato inmobiliario válido requiere: (1) oferta y aceptación, (2) consideración (algo de valor intercambiado), (3) partes competentes (legalmente capaces), (4) propósito legal y (5) generalmente debe ser por escrito. La firma de un notario NO es un requisito para la validez del contrato, aunque sí puede requerirse para registrar documentos en el registro público.', Unidad 10, pág. ~160);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 2, 'Which of the following BEST describes ''mutual assent'' in a contract?',
   'Both parties must use the same attorney', 'The meeting of the minds — a genuine agreement between all parties', 'The buyer must accept any counteroffer within 24 hours', 'Mutual assent is only required in leases, not in sales contracts',
   'B', '''Mutual assent'' (consentimiento mutuo) significa que hay una ''reunión de mentes'' — ambas partes realmente acordaron los mismos términos. Esto se logra a través del proceso de oferta y aceptación. Si hay cualquier malentendido material sobre los términos esenciales, no hay mutual assent y el contrato puede ser inválido.', Unidad 10, pág. ~161);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 4, 'A contract that has been fully performed by all parties is called:',
   'Executory', 'Voidable', 'Executed', 'Bilateral',
   'C', 'Un contrato ''executed'' (ejecutado/cumplido) es aquel que ha sido completamente cumplido por TODAS las partes. Por el contrario, un contrato ''executory'' es aquel en que todavía hay obligaciones pendientes por cumplir. La mayoría de los contratos de compraventa son ''executory'' desde la firma hasta el cierre, momento en que se convierten en ''executed''.', Unidad 10, pág. ~163);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 5, 'Which of the following is an example of an ''executory'' contract?',
   'A deed that has been delivered and accepted', 'A sales contract that has been signed but not yet closed', 'A lease that has expired', 'A mortgage that has been paid in full',
   'B', 'Un contrato ''executory'' (en ejecución) es aquel en que las obligaciones AÚN no se han cumplido completamente. Un contrato de compraventa firmado pero cuyo cierre aún no ha ocurrido es el ejemplo clásico: el vendedor aún no ha transferido el título y el comprador aún no ha pagado el precio completo. Las obligaciones quedan pendientes hasta el día del cierre.', Unidad 10, pág. ~163);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 7, 'A listing agreement is BEST described as which type of contract?',
   'Bilateral — the seller promises to pay a commission and the broker promises to use diligence to find a buyer', 'Unilateral — only the broker makes a promise', 'Unilateral — only the seller makes a promise', 'A unilateral option that only the seller may exercise',
   'A', 'Un contrato de listado (listing agreement) es BILATERAL porque AMBAS partes hacen promesas: el vendedor promete pagar una comisión si el corredor encuentra un comprador en los términos acordados, y el corredor promete usar diligencia razonable para comercializar la propiedad. Ambas partes tienen obligaciones contractuales que cumplir.', Unidad 10, pág. ~164);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 9, 'In Pennsylvania, real estate contracts for the sale of property must be:',
   'Oral agreements confirmed by a handshake', 'In writing to be enforceable under the Statute of Frauds', 'Notarized to be valid', 'Recorded at the county courthouse to be binding',
   'B', 'En Pennsylvania (y en todos los estados de EE.UU.), los contratos de compraventa de bienes inmuebles DEBEN ser por escrito para ser ejecutables bajo el ''Statute of Frauds'' (Estatuto de Fraudes). Esta ley exige que ciertos tipos de contratos — incluyendo los de venta de bienes inmuebles — consten por escrito y estén firmados por la parte contra quien se ejecutará. Los contratos orales de venta de bienes raíces generalmente no son ejecutables.', Unidad 10, pág. ~165);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 10, 'Which of the following would make a contract VOIDABLE?',
   'The contract was signed by a minor', 'The contract involved an illegal purpose', 'One party was legally declared insane before signing', 'There was no consideration',
   'A', 'Un contrato firmado por un menor (persona bajo 18 años) es VOIDABLE — no es automáticamente nulo, pero el menor tiene la opción de rescindirlo (deshacer el contrato). El menor puede elegir cumplirlo o cancelarlo cuando alcance la mayoría de edad. En contraste, un contrato para un propósito ilegal o firmado por alguien legalmente declarado incapaz es directamente VOID (nulo de pleno derecho).', Unidad 10, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 11, 'A contract is considered ''void'' when:',
   'One party is a minor', 'One party was induced to sign through fraud', 'It has no legal effect from the very beginning because it lacks essential elements', 'It was never recorded',
   'C', 'Un contrato VOID (nulo) es aquel que no tiene efecto legal desde el principio — es como si nunca hubiera existido. Esto ocurre cuando le falta algún elemento esencial (como propósito legal, consentimiento, etc.) o cuando una de las partes estaba legalmente incapacitada. No puede ser ratificado ni hacerse cumplir por ninguna de las partes.', Unidad 10, pág. ~166);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 12, 'Which of the following BEST describes an option contract in real estate?',
   'A bilateral contract where both parties must buy or sell', 'A unilateral contract giving the buyer the right, but not the obligation, to purchase at a set price within a set time', 'A lease agreement with a purchase clause', 'A listing agreement with an automatic renewal',
   'B', 'Un contrato de opción (option contract) es UNILATERAL: el vendedor promete mantener abierta la oferta para vender la propiedad a un precio determinado durante un período específico. El comprador PAGA por este derecho (la consideración de la opción) pero NO ESTÁ OBLIGADO a comprar. Si el comprador decide ejercer la opción, entonces se convierte en un contrato bilateral de compraventa.', Unidad 10, pág. ~168);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 13, 'In an installment land contract (also called a contract for deed or articles of agreement), who holds legal title during the payment period?',
   'The buyer (vendee)', 'The seller (vendor)', 'An escrow company', 'The county recorder',
   'B', 'En un contrato de tierra a plazos (installment land contract / contract for deed), el VENDEDOR retiene el título legal durante todo el período de pago. El comprador obtiene la posesión y ''título equitativo'' (equitable title), pero el título legal no se transfiere hasta que se realice el pago final. Esto representa un riesgo para el comprador si el vendedor tiene problemas financieros.', Unidad 10, pág. ~170);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 14, 'The earnest money deposit in a sales contract is BEST described as:',
   'The down payment paid at closing', 'Evidence of the buyer''s good faith and part of the consideration for the contract', 'A nonrefundable fee paid to the listing broker', 'A payment made directly to the seller''s mortgage lender',
   'B', 'El depósito de garantía (earnest money) demuestra la buena fe del comprador y forma parte de la consideración del contrato. NO es el pago inicial completo — ese se paga al cierre. El earnest money típicamente se mantiene en custodia (escrow) hasta el cierre, momento en que se aplica al precio de compra. Si el comprador incumple sin causa justificada, puede perder este depósito.', Unidad 10, pág. ~171);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 16, 'If a buyer defaults on a real estate contract, which remedy may the seller pursue?',
   'The seller may only retain the earnest money deposit', 'The seller may retain the earnest money, sue for damages, or seek specific performance', 'The seller must return the earnest money and re-list the property', 'The seller may only seek specific performance',
   'B', 'Cuando un comprador incumple un contrato inmobiliario, el vendedor tiene MÚLTIPLES opciones: (1) retener el depósito de garantía como daños liquidados, (2) demandar por daños reales (la diferencia entre el precio contratado y el precio de venta posterior), o (3) buscar ''specific performance'' (ejecución específica) — obligar al comprador a completar la compra. La estrategia depende de las circunstancias específicas del caso.', Unidad 10, pág. ~173);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (10, 17, 'Which of the following clauses in a sales contract allows the buyer to cancel if financing is not obtained?',
   'Subordination clause', 'Contingency clause (financing contingency)', 'Defeasance clause', 'Acceleration clause',
   'B', 'Una ''contingency clause'' (cláusula de contingencia) — específicamente una contingencia de financiamiento — le permite al comprador cancelar el contrato sin penalidad si no puede obtener un préstamo en los términos especificados. Por ejemplo: ''Este contrato está condicionado a que el comprador obtenga un préstamo de $X al X% por 30 años.'' Si el banco rechaza al comprador, puede recuperar su depósito.', Unidad 10, pág. ~174);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 1, 'The document that creates a lien on real property as security for a mortgage loan is called a:',
   'Promissory note', 'Mortgage or deed of trust', 'Deed', 'Satisfaction of mortgage',
   'B', 'La hipoteca (mortgage) o escritura de fideicomiso (deed of trust) es el documento que crea un GRAVAMEN (lien) sobre la propiedad inmueble como garantía del préstamo. Es importante distinguirla del pagaré (promissory note), que es la promesa personal de pagar la deuda. El pagaré crea obligación personal; la hipoteca crea gravamen sobre la propiedad.', Unidad 11, pág. ~183);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 2, 'In a mortgage loan, who is the mortgagor and who is the mortgagee?',
   'The mortgagor is the lender; the mortgagee is the borrower', 'The mortgagor is the borrower; the mortgagee is the lender', 'Both terms refer to the lending institution', 'The mortgagor is the title company; the mortgagee is the seller',
   'B', 'Es fácil confundirse: el MORTGAGOR es el PRESTATARIO (quien toma el préstamo y grava su propiedad). El MORTGAGEE es el PRESTAMISTA (quien otorga el préstamo y recibe el gravamen). Regla mnemotécnica: el ''or'' al final de mortgagor es quien ''da'' (otorga) el gravamen sobre su propiedad; el ''ee'' al final de mortgagee es quien ''recibe'' el gravamen como garantía.', Unidad 11, pág. ~183);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 4, 'Which of the following BEST describes a ''conventional'' mortgage loan?',
   'A loan guaranteed by the Department of Veterans Affairs', 'A loan insured by the Federal Housing Administration', 'A loan that is not insured or guaranteed by a government agency', 'Any loan with a fixed interest rate',
   'C', 'Un préstamo CONVENCIONAL es simplemente uno que NO está asegurado ni garantizado por ninguna agencia gubernamental. Se basa en el crédito del prestatario y la garantía de la propiedad. Los préstamos FHA están asegurados por la FHA; los VA están garantizados por el Departamento de Veteranos. Los préstamos convencionales pueden requerir PMI (seguro hipotecario privado) si el pago inicial es menor al 20%.', Unidad 11, pág. ~186);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 5, 'An FHA-insured mortgage loan is BEST described as:',
   'A loan made directly by the federal government', 'A loan where the FHA insures the lender against borrower default', 'A loan available only to first-time homebuyers', 'A loan with no down payment requirement',
   'B', 'Un préstamo FHA es uno donde la FHA (Federal Housing Administration) ASEGURA al prestamista contra el incumplimiento del prestatario. La FHA NO presta dinero directamente — los préstamos son otorgados por prestamistas privados aprobados. Si el prestatario incumple, la FHA indemniza al prestamista. Esto permite condiciones más favorables (pagos iniciales más bajos, calificaciones más flexibles) para los compradores.', Unidad 11, pág. ~187);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 6, 'The VA loan benefit is available to:',
   'Any U.S. citizen who served in the military', 'Eligible veterans, active-duty service members, and surviving spouses', 'Only veterans who served in combat', 'Veterans who have not previously used the VA loan benefit',
   'B', 'El beneficio de préstamo VA está disponible para: veteranos elegibles, miembros activos del servicio militar y cónyuges sobrevivientes de veteranos que fallecieron en servicio o por discapacidad relacionada con el servicio. Una gran ventaja: el beneficio VA puede usarse múltiples veces a lo largo de la vida del veterano, no solo una vez. No requiere pago inicial ni seguro hipotecario mensual.', Unidad 11, pág. ~188);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 7, 'Which federal act requires lenders to disclose the annual percentage rate (APR) to borrowers?',
   'Equal Credit Opportunity Act (ECOA)', 'Truth in Lending Act (TILA / Regulation Z)', 'Real Estate Settlement Procedures Act (RESPA)', 'Community Reinvestment Act (CRA)',
   'B', 'La Truth in Lending Act (TILA), implementada a través de la Regulación Z, exige que los prestamistas divulguen la TASA PORCENTUAL ANUAL (APR) y otros términos del préstamo a los prestatarios antes del cierre. El APR incluye no solo la tasa de interés sino también los cargos y costos del préstamo, lo que permite a los consumidores comparar préstamos de manera justa.', Unidad 11, pág. ~190);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 8, 'RESPA (Real Estate Settlement Procedures Act) is designed to:',
   'Set maximum interest rates on mortgage loans', 'Prohibit discrimination in lending', 'Ensure consumers receive disclosures about settlement costs and prohibit kickbacks', 'Regulate the secondary mortgage market',
   'C', 'RESPA (Real Estate Settlement Procedures Act) protege a los consumidores al: (1) requerir divulgación oportuna de los costos de cierre a través del Loan Estimate y Closing Disclosure, y (2) PROHIBIR los ''kickbacks'' (comisiones ilegales entre proveedores de servicios). Por ejemplo, es ilegal que una compañía de títulos pague a un agente inmobiliario por referir clientes.', Unidad 11, pág. ~191);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 9, 'The secondary mortgage market is BEST described as:',
   'Loans made by savings banks directly to homebuyers', 'Where existing mortgage loans are bought and sold between investors and institutions', 'Loans with second-priority liens on properties', 'The market for second mortgages (home equity loans)',
   'B', 'El mercado hipotecario SECUNDARIO es donde los préstamos hipotecarios existentes son comprados y vendidos entre inversores e instituciones (como Fannie Mae, Freddie Mac). Los prestamistas originales venden sus préstamos en este mercado para recuperar liquidez y poder hacer más préstamos. Esto es distinto del mercado PRIMARIO donde los prestamistas hacen préstamos directamente a los compradores.', Unidad 11, pág. ~193);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 10, 'Which of the following BEST describes an ''adjustable-rate mortgage'' (ARM)?',
   'A mortgage with a fixed interest rate for the entire loan term', 'A mortgage with an interest rate that changes periodically based on an index', 'A mortgage that can be assumed by a new buyer', 'A mortgage with a balloon payment at the end',
   'B', 'Una hipoteca de tasa ajustable (ARM) tiene una tasa de interés que CAMBIA periódicamente basándose en un índice financiero (como el SOFR o los bonos del Tesoro). Generalmente comienzan con una tasa inicial más baja que las hipotecas de tasa fija, pero la tasa puede subir o bajar en intervalos establecidos. Los préstamos ARM tienen ''caps'' (límites) sobre cuánto puede cambiar la tasa en cada período y en total.', Unidad 11, pág. ~195);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 11, 'A ''due-on-sale'' clause in a mortgage means:',
   'The seller must pay the mortgage before the property can be sold', 'The full loan balance becomes due if the property is sold or transferred', 'The buyer must make a larger down payment', 'The lender may increase the interest rate when the property is sold',
   'B', 'Una cláusula ''due-on-sale'' (también llamada cláusula de aceleración por venta o alienation clause) estipula que el SALDO COMPLETO del préstamo vence inmediatamente si la propiedad es vendida o transferida. Esto previene que los compradores asuman la hipoteca del vendedor sin aprobación del prestamista. Si el prestamista no tiene esta cláusula, la hipoteca podría ser ''assumable'' (asumible por el nuevo comprador).', Unidad 11, pág. ~196);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 13, 'Which of the following is an example of a ''junior lien'' or ''subordinate lien''?',
   'The first mortgage on a property', 'A mechanic''s lien that was filed before the mortgage', 'A home equity loan (second mortgage)', 'A property tax lien',
   'C', 'Un gravamen JUNIOR o SUBORDINADO es cualquier gravamen con menor prioridad que el primero. Un préstamo de capital de vivienda (home equity loan / segunda hipoteca) es un ejemplo clásico: si el propietario no paga, la primera hipoteca se paga primero en una ejecución hipotecaria, y la segunda hipoteca recibe lo que quede (si algo queda). Por eso los préstamos junior tienen tasas más altas — mayor riesgo para el prestamista.', Unidad 11, pág. ~197);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 14, 'Private mortgage insurance (PMI) is typically required when:',
   'The borrower has a credit score above 750', 'The down payment is less than 20% of the purchase price on a conventional loan', 'The loan is insured by the FHA', 'The property is located in a flood zone',
   'B', 'El seguro hipotecario privado (PMI) generalmente se requiere en préstamos CONVENCIONALES cuando el pago inicial es MENOR al 20% del precio de compra. El PMI protege al prestamista (no al prestatario) si el prestatario incumple. Una vez que el prestatario ha acumulado un 20% de capital en la propiedad, puede solicitar cancelar el PMI. Los préstamos FHA tienen su propio seguro hipotecario (MIP) que funciona de manera diferente.', Unidad 11, pág. ~198);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 15, 'The term ''amortization'' in a mortgage loan refers to:',
   'The penalty for paying off a loan early', 'The gradual reduction of the loan balance through scheduled principal and interest payments', 'The process of refinancing a mortgage', 'The transfer of a mortgage from one lender to another',
   'B', 'La AMORTIZACIÓN es el proceso de reducir gradualmente el saldo del préstamo mediante pagos programados de capital e intereses. En los primeros años de un préstamo amortizado, la mayor parte del pago va a intereses y muy poco al capital. Con el tiempo, la proporción se invierte hasta que el saldo llega a cero con el último pago. Un ''schedule de amortización'' muestra exactamente cuánto de cada pago va a capital vs. intereses.', Unidad 11, pág. ~199);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 16, 'Which of the following BEST describes ''points'' in mortgage financing?',
   'Points are prepaid interest — one point equals 1% of the loan amount', 'Points are fees paid to the real estate agent', 'Points represent the margin added to an ARM''s index rate', 'Points are penalties charged for paying off a loan early',
   'A', 'Los ''puntos'' (points) en financiamiento hipotecario son intereses PREPAGADOS. Un punto equivale al 1% del monto del préstamo. El prestamista puede cobrar puntos para obtener una tasa de interés más baja. Por ejemplo, pagar 2 puntos en un préstamo de $200,000 significa pagar $4,000 por adelantado para obtener una tasa menor. Cuánto tiempo planeas quedarte en la casa determina si vale la pena pagar puntos.', Unidad 11, pág. ~200);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 17, 'Fannie Mae and Freddie Mac are BEST described as:',
   'Federal agencies that make direct mortgage loans to consumers', 'Government-sponsored enterprises that purchase mortgages in the secondary market', 'Private insurance companies that insure FHA loans', 'State agencies that regulate mortgage lenders',
   'B', 'Fannie Mae (Federal National Mortgage Association) y Freddie Mac (Federal Home Loan Mortgage Corporation) son EMPRESAS PATROCINADAS POR EL GOBIERNO (GSEs) que compran préstamos hipotecarios en el mercado secundario. Al comprar préstamos a los prestamistas originales, liberan capital para que estos puedan hacer más préstamos. NO hacen préstamos directamente a consumidores. Ambas tienen criterios estándar que los préstamos deben cumplir para ser ''conformes''.', Unidad 11, pág. ~201);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 18, 'The Equal Credit Opportunity Act (ECOA) prohibits lenders from discriminating against credit applicants based on:',
   'Credit score and debt-to-income ratio', 'Race, color, religion, national origin, sex, marital status, age, or receipt of public assistance', 'The type of property being purchased', 'The loan-to-value ratio of the mortgage',
   'B', 'La Equal Credit Opportunity Act (ECOA) prohíbe la discriminación en el crédito basada en: raza, color, religión, origen nacional, sexo, estado civil, edad (siempre que el solicitante sea mayor de edad), o recibir asistencia pública. Los prestamistas PUEDEN considerar factores financieros legítimos como puntaje crediticio, ingresos, deudas, etc. También deben dar razones específicas si niegan crédito.', Unidad 11, pág. ~203);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (11, 19, '''Redlining'' in real estate lending refers to:',
   'A legal practice of marking flood zones on maps', 'The illegal practice of refusing to make loans in certain geographic areas based on the racial composition of those areas', 'The process of marking foreclosed properties on a lender''s books', 'A technique for marking boundaries in a property survey',
   'B', 'El ''redlining'' es la práctica ILEGAL en que los prestamistas se niegan a otorgar préstamos o seguros en ciertas áreas geográficas basándose en la composición racial o étnica de esa área, independientemente de la solvencia individual del solicitante. El nombre viene de la práctica histórica de literalmente trazar líneas rojas en mapas alrededor de barrios con mayoría de minorías. Está prohibido por la Fair Housing Act y ECOA.', Unidad 11, pág. ~204);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 1, 'The Pennsylvania Real Estate Licensing and Registration Act (RELRA) is administered by:',
   'The Pennsylvania Department of State through the State Real Estate Commission', 'The National Association of REALTORS®', 'The Pennsylvania Attorney General''s office', 'The Federal Real Estate Commission',
   'A', 'RELRA (Real Estate Licensing and Registration Act) es administrada por el DEPARTAMENTO DE ESTADO DE PENNSYLVANIA a través de la COMISIÓN ESTATAL DE BIENES RAÍCES (State Real Estate Commission). La Comisión tiene la autoridad para emitir, suspender y revocar licencias, además de disciplinar a los licenciatarios por violaciones de la ley.', Unidad 12, pág. ~215);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 2, 'Under RELRA, which of the following activities requires a Pennsylvania real estate license?',
   'A person selling their own home', 'An attorney acting under a power of attorney for their client', 'A licensed broker who represents a buyer in a purchase transaction for compensation', 'A property owner managing their own rental properties',
   'C', 'Bajo RELRA, se requiere licencia cuando alguien realiza actividades inmobiliarias POR COMPENSACIÓN para OTROS. Un corredor con licencia que representa a un comprador a cambio de comisión requiere licencia. Las EXCEPCIONES incluyen: propietarios vendiendo su propia propiedad, abogados actuando bajo poder notarial, administradores de propiedades propias, y funcionarios públicos en el desempeño de sus funciones.', Unidad 12, pág. ~216);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 3, 'In Pennsylvania, a real estate salesperson''s license must be held by:',
   'The Pennsylvania Real Estate Commission', 'A licensed Pennsylvania real estate broker', 'The salesperson themselves', 'The real estate association in their county',
   'B', 'En Pennsylvania, la licencia de vendedor inmobiliario (salesperson) debe estar AFILIADA y en custodia de un CORREDOR (broker) con licencia activa en Pennsylvania. El vendedor NO puede ejercer independientemente — todas sus actividades deben realizarse bajo la supervisión del corredor. El corredor es responsable de las acciones de sus vendedores afiliados.', Unidad 12, pág. ~217);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 4, 'Which of the following is a requirement to obtain a salesperson''s license in Pennsylvania?',
   'Three years of experience in real estate', 'Completion of 75 hours of approved pre-licensure education', 'Passing both a state and national exam, and a personal interview with the Commission', 'A college degree in business or a related field',
   'B', 'Para obtener la licencia de vendedor en Pennsylvania, se deben completar 75 HORAS de educación pre-licencia aprobada, pasar el examen de licencia (que incluye porciones estatales y nacionales), tener al menos 18 años, y tener un carácter moral bueno. No se requiere experiencia previa, entrevista personal con la Comisión, ni título universitario.', Unidad 12, pág. ~218);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 5, 'After passing the licensing exam in Pennsylvania, a salesperson has how long to apply for a license before the exam results expire?',
   '30 days', '60 days', '6 months', '1 year',
   'C', 'En Pennsylvania, después de aprobar el examen de licencia, el candidato tiene SEIS MESES (6 meses) para solicitar su licencia ante la Comisión. Si no lo hace dentro de ese período, los resultados del examen expiran y deberá volver a tomar el examen. Es importante no dejar pasar este plazo.', Unidad 12, pág. ~219);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 6, 'Pennsylvania real estate licenses must be renewed every:',
   '1 year', '2 years', '3 years', '4 years',
   'B', 'Las licencias inmobiliarias de Pennsylvania se renuevan cada DOS AÑOS (biennially). El período de licencia es de dos años. Para renovar, los licenciatarios deben completar los requisitos de educación continua (14 horas para vendedores y corredores) y pagar las tarifas de renovación correspondientes. El no renovar a tiempo puede resultar en una licencia caducada.', Unidad 12, pág. ~220);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 7, 'How many hours of continuing education must a Pennsylvania salesperson complete for each license renewal?',
   '7 hours', '14 hours', '21 hours', '30 hours',
   'B', 'Los vendedores (y corredores) de bienes raíces de Pennsylvania deben completar 14 HORAS de educación continua aprobada para cada renovación bienal de licencia. De estas 14 horas, al menos 3.5 deben ser en materia de IGUALDAD DE OPORTUNIDADES EN LA VIVIENDA (Fair Housing), y 3.5 horas en ÉTICA. El resto puede ser en otras materias aprobadas.', Unidad 12, pág. ~221);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 8, 'Under RELRA, what is the minimum age requirement to apply for a Pennsylvania real estate salesperson license?',
   '16 years old', '18 years old', '19 years old', '21 years old',
   'B', 'La edad mínima para solicitar una licencia de vendedor inmobiliario en Pennsylvania es 18 AÑOS. Esta es la edad de mayoría legal en Pennsylvania para entrar en contratos vinculantes. Un menor (menor de 18 años) no puede obtener licencia porque no puede legalmente firmar contratos de representación con clientes.', Unidad 12, pág. ~218);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 9, 'Which of the following BEST describes the role of the Pennsylvania Real Estate Commission?',
   'To promote real estate sales and marketing', 'To license, regulate, and discipline real estate licensees to protect the public', 'To set commission rates for real estate transactions', 'To manage the Multiple Listing Service (MLS) in Pennsylvania',
   'B', 'El rol principal de la Comisión Estatal de Bienes Raíces de Pennsylvania es LICENCIAR, REGULAR y DISCIPLINAR a los licenciatarios para PROTEGER AL PÚBLICO. La Comisión establece los estándares educativos, administra el proceso de licenciamiento, investiga quejas, y puede imponer sanciones disciplinarias incluyendo multas, suspensiones y revocaciones de licencia.', Unidad 12, pág. ~215);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 10, 'In Pennsylvania, a broker''s license requires how many hours of pre-licensure education?',
   '75 hours (same as salesperson)', '150 hours', '240 hours', '300 hours',
   'C', 'Para obtener una licencia de CORREDOR (broker) en Pennsylvania, se requieren 240 HORAS de educación pre-licencia aprobada. Esto es mucho más que los 75 horas requeridas para vendedores, reflejando el mayor nivel de responsabilidad y conocimiento requerido de un corredor. Además, generalmente se requiere experiencia previa como vendedor licenciado.', Unidad 12, pág. ~222);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 11, 'Under RELRA, a broker who wishes to open a new branch office must:',
   'Simply register the address with the local county', 'Obtain a branch office license and appoint a branch manager who is a licensed broker', 'Get approval from the National Association of REALTORS®', 'Hire at least 5 salespeople before the branch can open',
   'B', 'Para abrir una SUCURSAL (branch office) en Pennsylvania, el corredor debe obtener una LICENCIA DE SUCURSAL de la Comisión y designar un GERENTE DE SUCURSAL que sea un corredor con licencia activa. La sucursal no puede operar sin esta licencia. El gerente de sucursal es responsable de supervisar las actividades de todos los licenciatarios que trabajan en esa oficina.', Unidad 12, pág. ~223);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 12, 'Which of the following actions would be grounds for disciplinary action under RELRA in Pennsylvania?',
   'Representing both buyer and seller as a dual agent with proper disclosure and consent', 'Commingling client funds with the broker''s personal or business funds', 'Advertising a property without mentioning the listing price', 'Showing a property on a Sunday',
   'B', 'La MEZCLA DE FONDOS (commingling) — combinar el dinero de clientes (como depósitos de garantía) con los fondos personales o comerciales del corredor — es una violación grave de RELRA. Los fondos de clientes DEBEN mantenerse en una cuenta de fideicomiso (escrow account) separada. Esta práctica protege los fondos de los clientes si el corredor tiene problemas financieros.', Unidad 12, pág. ~225);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 13, 'The Pennsylvania Real Estate Commission has the authority to impose which of the following penalties on a licensee who violates RELRA?',
   'Criminal imprisonment only', 'Civil lawsuits only', 'Revocation, suspension, probation, fines up to $1,000 per violation, and/or required education', 'Only a formal written warning',
   'C', 'La Comisión tiene amplia autoridad disciplinaria que incluye: REVOCAR o SUSPENDER la licencia, imponer PROBATORIA, emitir MULTAS de hasta $1,000 por violación, y/o requerir EDUCACIÓN adicional. Las penalidades se aplican según la gravedad de la violación. Las violaciones criminales se manejan por separado a través del sistema judicial penal.', Unidad 12, pág. ~226);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 14, 'Under RELRA, when must a licensee provide the ''Consumer Notice'' to a consumer?',
   'Only at the time of closing', 'At the first contact with a consumer involving a specific property', 'Only when the consumer signs a listing agreement', 'Only when the consumer asks for it',
   'B', 'El ''Consumer Notice'' (Aviso al Consumidor) DEBE proporcionarse AL PRIMER CONTACTO con un consumidor que involucre una propiedad específica. Este documento informa al consumidor sobre los diferentes tipos de relaciones de agencia disponibles en Pennsylvania y los deberes que el licenciatario tiene hacia diferentes partes. Es obligatorio y NO puede omitirse — el licenciatario debe obtener el acuse de recibo del consumidor.', Unidad 12, pág. ~228);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 15, 'In Pennsylvania, the Consumer Notice must be provided by the licensee:',
   'Only when a buyer signs a buyer agency agreement', 'At the initial interview or first substantive contact with a consumer regarding a specific property', 'Only after the seller signs the listing agreement', 'Only if the consumer specifically requests information about agency',
   'B', 'El Consumer Notice debe entregarse en el PRIMER CONTACTO SUSTANTIVO con el consumidor respecto a una propiedad específica — no después. Si un comprador llama preguntando sobre una propiedad específica o un vendedor solicita una consulta de listado, ese es el momento de presentar el Consumer Notice. Esto garantiza que los consumidores entiendan la relación de agencia desde el principio.', Unidad 12, pág. ~228);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 16, 'Under RELRA, a Pennsylvania licensee who acts as a ''dual agent'' must:',
   'Obtain written consent from both the buyer and the seller', 'Charge only one commission', 'Represent only the seller''s interests', 'Refer the transaction to another broker',
   'A', 'En Pennsylvania, para actuar como AGENTE DUAL (representar tanto al comprador como al vendedor en la misma transacción), el licenciatario DEBE obtener CONSENTIMIENTO ESCRITO DE AMBAS PARTES — tanto del comprador como del vendedor. El agente dual tiene deberes reducidos hacia ambas partes: no puede divulgar información confidencial de una parte a la otra ni abogar completamente por ninguna.', Unidad 12, pág. ~229);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 17, 'Which of the following BEST describes a ''designated agent'' under Pennsylvania law?',
   'A broker who works without salespeople', 'A specific salesperson within a brokerage who is designated to represent only one party in a transaction, while the broker acts as dual agent', 'The managing broker of a real estate office', 'An agent who specializes in commercial properties only',
   'B', 'En Pennsylvania, el AGENTE DESIGNADO es un vendedor específico dentro de una firma de corretaje que es DESIGNADO para representar SOLO UNA PARTE en una transacción. Cuando la misma empresa representa tanto al comprador como al vendedor, el corredor puede designar un vendedor para el comprador y otro para el vendedor, con el corredor sirviendo técnicamente como agente dual. Esto permite una representación más completa de cada parte.', Unidad 12, pág. ~230);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 18, 'Under RELRA, if a salesperson is terminated by their broker, how many days does the broker have to notify the Pennsylvania Real Estate Commission?',
   '5 days', '10 days', '30 days', '60 days',
   'B', 'Cuando un vendedor es terminado (o renuncia) de una firma de corretaje, el CORREDOR tiene 10 DÍAS para notificar a la Comisión Estatal de Bienes Raíces de Pennsylvania. Durante este período de transición, el vendedor no puede ejercer actividades inmobiliarias hasta que se afilie a un nuevo corredor. Es responsabilidad del corredor reportar el cambio de afiliación oportunamente.', Unidad 12, pág. ~232);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 19, 'The Pennsylvania Real Estate Commission is composed of:',
   'Only licensed brokers appointed by the Governor', '11 members: 6 licensed real estate brokers, 2 licensed salespeople, and 3 public members, appointed by the Governor', '7 members: all licensed real estate professionals', 'Members elected by the Pennsylvania Association of REALTORS®',
   'B', 'La Comisión Estatal de Bienes Raíces de Pennsylvania está compuesta por 11 MIEMBROS nombrados por el Gobernador: 6 corredores con licencia, 2 vendedores con licencia, y 3 miembros del PÚBLICO GENERAL (no licenciatarios). La inclusión de miembros del público asegura representación de los intereses de los consumidores en la regulación de la profesión.', Unidad 12, pág. ~215);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (12, 20, 'Under RELRA, which of the following is TRUE regarding a referral fee or finder''s fee paid to an unlicensed person?',
   'It is permitted if the amount is less than $500', 'It is permitted if the unlicensed person is a relative of the licensee', 'It is illegal — compensation for real estate activities may only be paid to licensed individuals', 'It is permitted if the unlicensed person only referred a name and did not show property',
   'C', 'Bajo RELRA, pagar honorarios de referido o comisiones a personas SIN LICENCIA es ILEGAL, independientemente del monto, la relación familiar o el nivel de participación en la transacción. La compensación por actividades inmobiliarias en Pennsylvania SOLO puede pagarse a licenciatarios activos. Pagar a no licenciatados es una violación que puede resultar en sanciones disciplinarias para el licenciatario que realiza el pago.', Unidad 12, pág. ~234);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 1, 'The purpose of a real estate appraisal is to:',
   'Determine the exact selling price of a property', 'Provide an unbiased estimate of a property''s market value', 'Guarantee that a property will sell at the appraised value', 'Set the minimum price at which a property must be listed',
   'B', 'El propósito de una tasación (appraisal) es proporcionar una ESTIMACIÓN IMPARCIAL del valor de mercado de una propiedad. Un tasador NO determina el precio exacto de venta ni garantiza que la propiedad se venderá a ese valor. El valor de mercado es una estimación de lo que un comprador informado pagaría a un vendedor informado en condiciones de mercado normales.', Unidad 14, pág. ~245);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 2, 'Which of the following BEST defines ''market value'' in real estate appraisal?',
   'The price a seller asks for a property', 'The most probable price a property would sell for in a competitive and open market under normal conditions', 'The assessed value set by the local government for tax purposes', 'The replacement cost of the structure',
   'B', 'El VALOR DE MERCADO es el precio más probable al que una propiedad se vendería en un mercado competitivo y abierto, con compradores y vendedores informados, sin presiones y con tiempo razonable. Es diferente del precio de listado (lo que el vendedor pide), del precio de venta (lo que alguien pagó) y del valor tasado para impuestos (que puede ser una fracción del valor de mercado).', Unidad 14, pág. ~245);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 4, 'The ''sales comparison approach'' to appraisal is BEST described as:',
   'Estimating value based on the cost to replace the improvements', 'Estimating value based on the income the property generates', 'Estimating value by comparing the subject property to recently sold similar properties', 'Averaging the assessed values of all properties in the neighborhood',
   'C', 'El ENFOQUE DE COMPARACIÓN DE VENTAS (sales comparison approach) estima el valor comparando la propiedad en cuestión con propiedades similares vendidas recientemente (''comparables'' o ''comps''). El tasador hace ajustes por diferencias entre las propiedades comparables y la propiedad sujeto. Este es el enfoque más común para propiedades residenciales y se basa en el principio de sustitución.', Unidad 14, pág. ~248);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 5, 'The ''cost approach'' to appraisal is MOST useful for valuing:',
   'Income-producing apartment buildings', 'Single-family homes with many recent comparable sales', 'Special-use properties like schools or churches with few comparables', 'Vacant land parcels',
   'C', 'El ENFOQUE DE COSTO es más útil para propiedades de uso especial (escuelas, iglesias, hospitales, edificios gubernamentales) que rara vez se venden y tienen pocos comparables. El enfoque calcula el valor como: VALOR DEL TERRENO + COSTO DE REEMPLAZO/REPRODUCCIÓN DE LAS MEJORAS - DEPRECIACIÓN. También es útil para propiedades nuevas donde la depreciación es mínima.', Unidad 14, pág. ~250);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 6, 'Which of the following BEST describes the ''income approach'' to appraisal?',
   'Estimating value based on recent comparable sales', 'Estimating value based on the cost to construct the improvements', 'Estimating value by capitalizing the net operating income the property produces', 'Estimating value based on the assessed value for tax purposes',
   'C', 'El ENFOQUE DE INGRESOS estima el valor de una propiedad capitalizando el ingreso operativo neto (NOI) que genera. La fórmula básica es: VALOR = NOI / TASA DE CAPITALIZACIÓN. Por ejemplo, si una propiedad genera $50,000 de NOI anual y la tasa de capitalización (cap rate) de mercado es 5%, el valor estimado sería $50,000 / 0.05 = $1,000,000. Es el enfoque principal para propiedades de inversión.', Unidad 14, pág. ~252);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 7, '''Depreciation'' in the cost approach to appraisal refers to:',
   'The decrease in a property''s value due to any cause', 'The annual tax deduction allowed by the IRS for investment properties', 'The physical wear and tear on a building only', 'A decrease in value caused only by external factors',
   'A', 'En la tasación, la DEPRECIACIÓN es cualquier pérdida de valor de una propiedad debida a CUALQUIER CAUSA. Los tres tipos son: (1) DETERIORO FÍSICO — desgaste normal; (2) OBSOLESCENCIA FUNCIONAL — diseño inadecuado, características anticuadas; (3) OBSOLESCENCIA EXTERNA/ECONÓMICA — factores externos como ruido de aeropuertos, zonificación desfavorable o declive del vecindario. Este concepto es diferente a la depreciación fiscal del IRS.', Unidad 14, pág. ~251);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 9, 'The principle of ''substitution'' in appraisal states that:',
   'Buyers will always pay more for a unique property', 'A buyer will not pay more for a property than the cost of acquiring an equally desirable substitute property', 'Improvements to a property always increase its value by more than their cost', 'The value of a property is determined by its highest and best use',
   'B', 'El PRINCIPIO DE SUSTITUCIÓN es fundamental en tasación: un comprador informado no pagará MÁS por una propiedad de lo que costaría adquirir una propiedad igualmente deseable como sustituto. Este principio es la base del enfoque de comparación de ventas — los compradores comparan propiedades similares. También explica por qué el costo de construir algo nuevo representa el límite superior del valor de una propiedad existente.', Unidad 14, pág. ~247);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 10, 'Which of the following BEST describes the principle of ''highest and best use'' in appraisal?',
   'The use that generates the most rental income', 'The most profitable legally permitted, physically possible, financially feasible, and maximally productive use of a property', 'The current use of a property', 'The use that the local zoning law designates',
   'B', 'El ''HIGHEST AND BEST USE'' (uso óptimo) es el uso legal, físicamente posible, financieramente factible y que maximiza la productividad/valor de una propiedad. Los cuatro criterios deben cumplirse: (1) legalmente permitido, (2) físicamente posible, (3) económicamente viable, y (4) maximalmente productivo. Un terreno vacante en una zona comercial puede tener su más alto y mejor uso como edificio de oficinas, no como residencia.', Unidad 14, pág. ~246);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 11, 'A real estate appraiser''s opinion of value is MOST influenced by:',
   'The listing price set by the seller', 'The purchase price agreed upon by buyer and seller', 'Recent sales of comparable properties and market data', 'The assessed value for property tax purposes',
   'C', 'La opinión de valor de un tasador está PRINCIPALMENTE influenciada por datos de mercado objetivos — especialmente las ventas recientes de propiedades comparables. Los tasadores ignoran el precio de listado, el precio de venta acordado (que puede no reflejar el valor de mercado) y el valor catastral para impuestos. Los buenos tasadores se basan en evidencia de mercado, no en lo que el vendedor quiere o el comprador pide.', Unidad 14, pág. ~248);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 12, 'In the income approach, ''gross rent multiplier'' (GRM) is calculated as:',
   'Annual NOI divided by the cap rate', 'Sale price divided by monthly gross rent', 'Monthly rent multiplied by 12', 'Net operating income divided by total expenses',
   'B', 'El MULTIPLICADOR DE RENTA BRUTA (GRM) se calcula dividiendo el PRECIO DE VENTA entre la RENTA BRUTA MENSUAL: GRM = Precio de Venta / Renta Mensual Bruta. Por ejemplo, si una propiedad se vendió en $180,000 y la renta mensual es $1,500, el GRM = $180,000 / $1,500 = 120. Luego se aplica ese GRM a la renta de la propiedad sujeto para estimar su valor. Es una herramienta más simple que la capitalización de ingresos.', Unidad 14, pág. ~253);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 14, 'Which of the following is an example of ''external obsolescence'' (also called economic obsolescence)?',
   'A home with a floor plan that buyers find awkward', 'A roof that is 30 years old and needs replacement', 'A residential property located next to a newly built highway', 'A kitchen with outdated fixtures',
   'C', 'La OBSOLESCENCIA EXTERNA (económica) es una pérdida de valor causada por factores FUERA de la propiedad misma, que generalmente NO son curables (o son muy costosos de remediar). Una casa junto a una autopista nueva sufre obsolescencia externa porque el ruido y el tráfico disminuyen su valor, pero el propietario no puede eliminar la autopista. Otros ejemplos: fábricas cercanas, declive económico del vecindario, zonificación desfavorable adyacente.', Unidad 14, pág. ~251);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 16, 'In the sales comparison approach, an appraiser makes ''adjustments'' to comparable sales. If a comparable property had an extra bathroom that the subject property does NOT have, the appraiser would:',
   'Add the value of the bathroom to the subject property''s value', 'Subtract the value of the bathroom from the comparable''s sale price', 'Ignore the difference if it is minor', 'Automatically disqualify that comparable from use',
   'B', 'En el enfoque de comparación de ventas, los ajustes SIEMPRE se hacen AL PRECIO DE LA COMPARABLE, no a la propiedad sujeto. La regla es: si el COMPARABLE es SUPERIOR a la propiedad sujeto en alguna característica, se RESTA ese valor del precio de la comparable (porque el comparable vendió más caro por esa característica extra). Si el comparable es INFERIOR, se SUMA. ''CBS'' = Comparable Better, Subtract.', Unidad 14, pág. ~249);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 17, 'Which federal law requires that appraisals for federally related mortgage transactions be performed by state-licensed or certified appraisers?',
   'RESPA', 'TILA', 'FIRREA (Financial Institutions Reform, Recovery, and Enforcement Act)', 'The Equal Credit Opportunity Act',
   'C', 'FIRREA (Financial Institutions Reform, Recovery, and Enforcement Act de 1989) exige que las tasaciones para transacciones hipotecarias federalmente relacionadas sean realizadas por tasadores CERTIFICADOS o con LICENCIA ESTATAL. Esto fue una respuesta a los escándalos de savings & loan de los años 80 donde las tasaciones infladas contribuyeron al colapso de muchas instituciones. Pennsylvania tiene su propio sistema de certificación de tasadores bajo FIRREA.', Unidad 14, pág. ~255);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 18, 'The three approaches to value in appraisal are:',
   'Market, income, and replacement approaches', 'Sales comparison, cost, and income approaches', 'Comparative, assessed, and replacement approaches', 'Direct, indirect, and mixed approaches',
   'B', 'Los TRES ENFOQUES de valor en tasación son: (1) COMPARACIÓN DE VENTAS (Sales Comparison) — compara con propiedades similares vendidas recientemente; (2) COSTO (Cost) — valor del terreno + costo de reemplazo de mejoras - depreciación; (3) INGRESOS (Income) — capitaliza el ingreso neto que genera la propiedad. Para una tasación residencial típica, el enfoque de comparación de ventas generalmente recibe el mayor peso.', Unidad 14, pág. ~247);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 19, 'Which of the following BEST describes ''reconciliation'' (or correlation) in the appraisal process?',
   'The process of averaging the three value indicators', 'The appraiser''s reasoned judgment about which value indicator(s) best reflect market behavior for that property type', 'The process of verifying the comparable sales with county records', 'The final negotiation between buyer and seller on price',
   'B', 'La RECONCILIACIÓN (o correlación) es el proceso final donde el tasador usa su JUICIO PROFESIONAL para ponderar las indicaciones de valor de los tres enfoques y llegar a una estimación final. NO es un promedio matemático — el tasador da más peso al enfoque más apropiado para ese tipo de propiedad. Para una vivienda unifamiliar, el enfoque de comparación de ventas típicamente recibe el mayor peso.', Unidad 14, pág. ~256);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (14, 20, 'An appraisal report that provides the full explanation of the data, reasoning, and analyses used to develop the opinion of value is called a:',
   'Restricted Use Report', 'Summary Report (now called ''Appraisal Report'')', 'Desktop Appraisal', 'Drive-by Appraisal',
   'B', 'Bajo las Normas Uniformes de Práctica Profesional de Tasación (USPAP), el ''APPRAISAL REPORT'' (antes llamado Summary Report) es el informe más completo que proporciona toda la explicación de los datos, razonamiento y análisis usados. El ''Restricted Appraisal Report'' contiene menos detalles y está destinado solo para uso interno del cliente. Las tasaciones para préstamos hipotecarios generalmente requieren el Appraisal Report completo.', Unidad 14, pág. ~257);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 2, 'Which of the following is a PRIMARY advantage of investing in real estate compared to stocks?',
   'Real estate is always more liquid than stocks', 'Real estate can be leveraged — you can control a large asset with a relatively small down payment', 'Real estate values never decrease', 'Real estate requires no management or maintenance',
   'B', 'Una ventaja primaria de invertir en bienes raíces es el APALANCAMIENTO (leverage) — puedes controlar un activo grande con una cantidad relativamente pequeña de dinero propio (el pago inicial). Por ejemplo, con $50,000 puedes comprar una propiedad de $250,000 (usando financiamiento), lo que amplifica los retornos sobre la inversión. Si la propiedad sube de valor, tu retorno sobre el capital invertido es mucho mayor que si hubieras pagado en efectivo.', Unidad 15, pág. ~265);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 4, '''Equity'' in a real estate investment refers to:',
   'The total value of the property', 'The difference between the property''s market value and the outstanding mortgage balance', 'The annual rental income generated by the property', 'The amount of the original purchase price',
   'B', 'El CAPITAL PROPIO o EQUIDAD (equity) es la diferencia entre el VALOR DE MERCADO de la propiedad y el SALDO PENDIENTE de la hipoteca. Por ejemplo, si tu propiedad vale $300,000 y debes $180,000, tu equity es $120,000. El equity crece de dos maneras: (1) cuando el valor de la propiedad aumenta (apreciación), y (2) cuando el saldo del préstamo disminuye (amortización de pagos).', Unidad 15, pág. ~266);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 5, 'Which of the following BEST describes ''cash flow'' in a rental property investment?',
   'The total rental income collected', 'The net income remaining after all expenses and mortgage payments are paid', 'The appreciation in property value', 'The equity built up over time',
   'B', 'El FLUJO DE CAJA (cash flow) es el dinero que queda después de pagar TODOS los gastos operativos Y los pagos de la hipoteca. Fórmula: Renta Bruta - Vacancia - Gastos Operativos - Pago Hipoteca = Flujo de Caja. Un flujo de caja POSITIVO significa que la propiedad genera ganancia mensual. Un flujo de caja NEGATIVO significa que el propietario debe aportar dinero de su bolsillo cada mes para cubrir los costos.', Unidad 15, pág. ~267);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 7, '''Depreciation'' as a tax benefit for real estate investors refers to:',
   'A decrease in the market value of the property', 'An annual income tax deduction allowed by the IRS for the wear and tear of income-producing property', 'The physical deterioration of the building', 'A reduction in the assessed value for property tax purposes',
   'B', 'La DEPRECIACIÓN FISCAL es una deducción del impuesto sobre la renta permitida por el IRS que refleja el ''desgaste'' de una propiedad de inversión a lo largo del tiempo. Para propiedades residenciales de alquiler, el IRS permite depreciar el edificio (no el terreno) a lo largo de 27.5 años. Para propiedades comerciales, son 39 años. Esta deducción reduce los ingresos imponibles del inversor sin ser un gasto real en efectivo — una gran ventaja fiscal.', Unidad 15, pág. ~270);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 8, 'A ''1031 exchange'' (tax-deferred exchange) allows a real estate investor to:',
   'Exchange properties with another investor without paying any taxes ever', 'Defer capital gains taxes by reinvesting the proceeds from the sale of investment property into another like-kind property', 'Exchange a residential property for a commercial property tax-free permanently', 'Avoid all real estate taxes by reinvesting',
   'B', 'El INTERCAMBIO 1031 (llamado así por la Sección 1031 del Código Tributario) permite a los inversores DIFERIR (no eliminar) los impuestos sobre las ganancias de capital al reinvertir los beneficios de la venta de una propiedad de inversión en otra propiedad ''similar'' (like-kind). Los plazos son estrictos: 45 días para identificar la propiedad de reemplazo y 180 días para cerrar. Si se cumplen las reglas, los impuestos se difieren hasta que eventualmente se vende sin intercambio.', Unidad 15, pág. ~271);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 9, 'Which of the following BEST describes a ''Real Estate Investment Trust'' (REIT)?',
   'A private partnership between two real estate investors', 'A company that owns income-producing real estate and allows investors to buy shares, similar to a stock', 'A government program for affordable housing investment', 'A type of mortgage used for commercial properties',
   'B', 'Un REIT (Real Estate Investment Trust) es una empresa que posee y/o opera bienes raíces que generan ingresos, y permite a los inversores comprar acciones (como un fondo de acciones). Los REIT deben distribuir al menos el 90% de sus ingresos imponibles a los accionistas como dividendos. Esto permite a los pequeños inversores participar en carteras de bienes raíces comerciales sin necesidad de comprar propiedades enteras.', Unidad 15, pág. ~272);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 10, 'Which of the following is considered a ''disadvantage'' of real estate as an investment?',
   'Real estate can provide rental income', 'Real estate can be leveraged', 'Real estate is relatively illiquid compared to stocks and bonds', 'Real estate can appreciate in value',
   'C', 'La ILIQUIDEZ es una desventaja importante de la inversión inmobiliaria. No puedes vender una propiedad tan rápido como vendes acciones — el proceso de venta puede tomar semanas o meses, y los costos de transacción (comisiones, impuestos de transferencia, costos de cierre) son significativos. En contraste, las acciones pueden venderse en segundos con costos mínimos. La iliquidez significa que el capital puede quedar ''atrapado'' en la propiedad.', Unidad 15, pág. ~265);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 12, '''Net operating income'' (NOI) is calculated as:',
   'Gross income minus vacancy minus operating expenses (before debt service)', 'Gross income minus mortgage payments only', 'Total rental income collected', 'Cash flow after all expenses including mortgage payments',
   'A', 'El INGRESO OPERATIVO NETO (NOI) = Ingreso Bruto Potencial - Pérdidas por Vacancia/Cobranza - Gastos Operativos. Los GASTOS OPERATIVOS incluyen: impuestos a la propiedad, seguros, mantenimiento, administración, servicios públicos. IMPORTANTE: el NOI se calcula ANTES de los pagos de deuda (hipoteca). El NOI se usa en el enfoque de ingresos para tasación y para calcular la tasa de capitalización.', Unidad 15, pág. ~268);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 13, 'The ''capitalization rate'' (cap rate) is used to:',
   'Calculate the monthly mortgage payment', 'Convert net operating income into an estimate of property value', 'Determine the maximum allowable rent for a unit', 'Calculate the depreciation deduction for tax purposes',
   'B', 'La TASA DE CAPITALIZACIÓN (cap rate) convierte el Ingreso Operativo Neto (NOI) en una estimación del valor de la propiedad. Fórmula: Cap Rate = NOI / Valor de Propiedad. Si conoces el NOI y el cap rate del mercado, puedes estimar el valor: Valor = NOI / Cap Rate. Por ejemplo: NOI de $60,000 con un cap rate del 6% = valor estimado de $1,000,000. Un cap rate más alto indica mayor riesgo o menor valor relativo.', Unidad 15, pág. ~269);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 14, 'Which of the following statements about leverage in real estate is MOST accurate?',
   'Leverage always increases investment returns regardless of market conditions', 'Leverage amplifies both gains AND losses — it increases risk as well as potential return', 'Using leverage is risk-free because real estate always appreciates', 'Leverage reduces an investor''s exposure to market fluctuations',
   'B', 'El APALANCAMIENTO amplifica tanto las GANANCIAS como las PÉRDIDAS. Si la propiedad se aprecia, el retorno sobre el capital propio es mucho mayor (positivo). Pero si la propiedad PIERDE valor, las pérdidas sobre el capital también se amplifican (negativo). Además, el apalancamiento requiere pagos de deuda regulares — si la propiedad queda vacante o los ingresos caen, el inversor aún debe hacer los pagos de la hipoteca. El riesgo aumenta con el apalancamiento.', Unidad 15, pág. ~266);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 15, 'An investment property was purchased for $500,000. The investor made a $100,000 down payment and financed the rest. After one year, the property is worth $550,000. What is the investor''s return on equity?',
   '10% (based on total property value)', '50% (based on the $100,000 equity invested)', '5% (based on the $50,000 appreciation)', '20% (based on the mortgage amount)',
   'B', 'El retorno sobre el CAPITAL PROPIO (equity) se calcula sobre el dinero que el inversor REALMENTE invirtió: La propiedad subió $50,000 ($550,000 - $500,000). El inversor invirtió $100,000 de capital propio. Retorno = $50,000 / $100,000 = 50%. Este poderoso efecto del apalancamiento demuestra cómo los bienes raíces pueden generar altos retornos sobre el capital invertido, aunque la apreciación total fue solo del 10%.', Unidad 15, pág. ~266);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 16, 'Which of the following BEST describes ''positive leverage'' in real estate investment?',
   'When the interest rate on borrowed money is higher than the overall return on the property', 'When the return on the total investment exceeds the cost of borrowed money, increasing the return on equity', 'When the property increases in value regardless of financing', 'When rents increase faster than operating expenses',
   'B', 'El APALANCAMIENTO POSITIVO ocurre cuando el RETORNO de la propiedad es MAYOR que el COSTO del dinero prestado (tasa de interés). Por ejemplo, si la propiedad genera un retorno del 8% y el préstamo cuesta 5%, el inversor gana la diferencia del 3% sobre el dinero prestado. Esto aumenta el retorno sobre el capital propio por encima del retorno total de la propiedad. El apalancamiento NEGATIVO ocurre cuando el costo del préstamo supera el retorno de la propiedad.', Unidad 15, pág. ~267);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 17, 'Which of the following is an example of a ''limited partnership'' in real estate investment?',
   'Two equal partners who both manage a rental property', 'An investment structure where limited partners provide capital but have limited liability and no management role, while a general partner manages the investment', 'A corporation that owns real estate', 'A joint venture between two real estate brokers',
   'B', 'Una SOCIEDAD LIMITADA (limited partnership) en bienes raíces tiene dos tipos de socios: (1) SOCIOS LIMITADOS — aportan capital, tienen responsabilidad LIMITADA (solo pueden perder lo que invirtieron) y NO participan en la gestión; (2) SOCIO GENERAL — gestiona la inversión pero tiene responsabilidad ILIMITADA. Es una estructura popular para sindicatos inmobiliarios que reúnen capital de múltiples inversores para comprar propiedades grandes.', Unidad 15, pág. ~273);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 18, 'For tax purposes, a real estate investor''s ''basis'' in a property is MOST accurately described as:',
   'The current market value of the property', 'The original purchase price plus the cost of capital improvements, minus depreciation taken', 'The assessed value for property tax purposes', 'The outstanding mortgage balance',
   'B', 'La BASE (basis) de un inversor en una propiedad es el PRECIO DE COMPRA ORIGINAL + COSTO DE MEJORAS DE CAPITAL - DEPRECIACIÓN TOMADA. La base es crucial para calcular las ganancias de capital cuando se vende la propiedad (Precio de Venta - Base = Ganancia de Capital). Si el inversor ha tomado deducciones de depreciación, su base se reduce, lo que significa una mayor ganancia imponible al vender.', Unidad 15, pág. ~274);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 19, 'Which of the following statements about real estate syndication is MOST accurate?',
   'A syndication is only legal if all investors are licensed real estate brokers', 'A syndication pools money from multiple investors to purchase properties that would be too large for any one investor alone', 'Syndications are only used for residential properties', 'A syndication requires all investors to actively manage the property',
   'B', 'La SINDICACIÓN inmobiliaria agrupa capital de MÚLTIPLES INVERSORES para adquirir propiedades que serían demasiado grandes o costosas para un solo inversor. Los inversores individuales compran participaciones en el sindicato y reciben retornos proporcionales a su inversión sin necesidad de gestionar la propiedad directamente. Los sindicatos pueden estructurarse como sociedades limitadas, LLCs u otras entidades.', Unidad 15, pág. ~273);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (15, 20, 'Which of the following BEST describes ''appreciation'' as a component of real estate return?',
   'The tax deduction for depreciation', 'The increase in property value over time', 'The monthly cash flow from rental income', 'The equity build-up from mortgage amortization',
   'B', 'La APRECIACIÓN es el aumento en el valor de una propiedad con el tiempo. Es uno de los cuatro componentes del retorno inmobiliario (junto con flujo de caja, beneficios fiscales y reducción de deuda). La apreciación puede ser: (1) NATURAL — inflación general y aumento de demanda; (2) FORZADA — mejoras al inmueble que aumentan su valor. A largo plazo, los bienes raíces históricamente se han apreciado, aunque el valor puede fluctuar en el corto plazo.', Unidad 15, pág. ~265);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 1, 'A property sells for $285,000. The commission rate is 6%. How much is the total commission?',
   '$1,710', '$17,100', '$171,000', '$285',
   'B', 'Comisión = Precio de Venta × Tasa de Comisión = $285,000 × 0.06 = $17,100. Recuerda: para convertir porcentaje a decimal, divide entre 100 (6% = 0.06). La comisión total es lo que recibe la firma de corretaje TOTAL, que luego se divide entre el corredor listador y el corredor del comprador según el acuerdo de división.', Unidad 16, pág. ~285);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 2, 'A salesperson receives 60% of the commission earned by their broker on a sale. The total commission was $12,000. How much does the salesperson receive?',
   '$4,800', '$7,200', '$6,000', '$2,000',
   'B', 'Pago al vendedor = Comisión Total × Porcentaje del Vendedor = $12,000 × 0.60 = $7,200. El corredor recibe el restante: $12,000 - $7,200 = $4,800. Las divisiones de comisión entre corredor y vendedor son negociables y varían entre firmas, típicamente desde 50/50 hasta 70/30 o más a favor del vendedor según su experiencia y producción.', Unidad 16, pág. ~285);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 3, 'A house sold for $320,000. The seller paid a 5.5% commission. How much did the seller NET after paying the commission?',
   '$17,600', '$302,400', '$285,000', '$337,600',
   'B', 'Comisión = $320,000 × 0.055 = $17,600. Cantidad neta del vendedor = $320,000 - $17,600 = $302,400. El ''neto del vendedor'' es lo que el vendedor recibe después de pagar la comisión. En transacciones reales, el vendedor también paga otros costos de cierre, pero este problema solo pregunta por el efecto de la comisión.', Unidad 16, pág. ~286);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 4, 'A seller wants to net $250,000 after paying a 6% commission. What must the property sell for?',
   '$265,000', '$265,957', '$260,000', '$266,000',
   'B', 'Si el vendedor quiere recibir $250,000 DESPUÉS de la comisión del 6%, el precio de venta debe ser: Precio = Neto Deseado / (1 - Tasa de Comisión) = $250,000 / (1 - 0.06) = $250,000 / 0.94 = $265,957 (aprox.). ERROR COMÚN: muchos calculan $250,000 × 1.06 = $265,000, pero esto es incorrecto. El 6% de $265,000 es $15,900, y $265,000 - $15,900 = $249,100, no $250,000.', Unidad 16, pág. ~286);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 5, 'An investment property has a gross annual income of $48,000. Operating expenses are $18,000. The mortgage payment is $24,000 per year. What is the annual cash flow?',
   '$30,000', '$6,000', '$24,000', '-$6,000',
   'B', 'Flujo de Caja = Ingreso Bruto - Gastos Operativos - Pago Hipoteca = $48,000 - $18,000 - $24,000 = $6,000 anuales de flujo de caja positivo. Esto equivale a $500 por mes. El NOI (Ingreso Operativo Neto) sería: $48,000 - $18,000 = $30,000 (antes del pago de hipoteca). El flujo de caja se calcula DESPUÉS de todos los gastos incluyendo la hipoteca.', Unidad 16, pág. ~287);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 6, 'A property''s NOI is $45,000 and the cap rate in the market is 7.5%. What is the estimated value of the property?',
   '$337,500', '$3,375', '$600,000', '$45,000',
   'C', 'Valor = NOI / Cap Rate = $45,000 / 0.075 = $600,000. La fórmula del enfoque de ingresos: V = NOI / R (donde R es la tasa de capitalización). Si conoces dos de los tres valores, puedes calcular el tercero. Por ejemplo, si el valor es $600,000 y el NOI es $45,000: Cap Rate = $45,000 / $600,000 = 7.5%.', Unidad 16, pág. ~288);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 7, 'A property has a Gross Rent Multiplier (GRM) of 110. The monthly rent is $1,800. What is the estimated value?',
   '$180,000', '$198,000', '$21,600', '$1,980,000',
   'B', 'Valor = GRM × Renta Mensual Bruta = 110 × $1,800 = $198,000. El GRM es una herramienta rápida para estimar valor en propiedades de alquiler residencial. Primero calculas el GRM dividiendo los precios de venta de propiedades comparables entre sus rentas mensuales, luego aplicas ese GRM a la propiedad que estás evaluando. Es más simple que el enfoque de capitalización de ingresos pero menos preciso.', Unidad 16, pág. ~289);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 8, 'A loan of $200,000 is obtained at 7% annual interest. What is the monthly interest for the FIRST month?',
   '$14,000', '$1,167', '$116.67', '$583.33',
   'B', 'Interés mensual = (Saldo del préstamo × Tasa anual) / 12 = ($200,000 × 0.07) / 12 = $14,000 / 12 = $1,166.67 ≈ $1,167. En el primer mes, la mayor parte del pago hipotecario va a intereses. Con el tiempo, a medida que el saldo disminuye, la porción de interés disminuye y la de capital aumenta. Este es el principio de la amortización.', Unidad 16, pág. ~290);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 10, 'A property was purchased for $180,000 and sold 3 years later for $216,000. What was the total percentage gain?',
   '$36,000', '20%', '12%', '6.67% per year',
   'B', 'Ganancia Total en % = (Precio de Venta - Precio de Compra) / Precio de Compra × 100 = ($216,000 - $180,000) / $180,000 × 100 = $36,000 / $180,000 × 100 = 20%. Nota: esto es el porcentaje de ganancia TOTAL en 3 años, no el porcentaje anual. La ganancia anual promedio sería 20% / 3 ≈ 6.67% por año.', Unidad 16, pág. ~291);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 11, 'A property has a market value of $350,000 and is assessed at 80% of market value for tax purposes. The tax rate is 25 mills. What are the annual property taxes?',
   '$8,750', '$7,000', '$87,500', '$70,000',
   'B', 'Paso 1: Valor Catastral = $350,000 × 0.80 = $280,000. Paso 2: Impuesto = Valor Catastral × Tasa de Impuesto. 25 mills = $25 por $1,000 de valor catastral = 0.025 (2.5%). Impuesto = $280,000 × 0.025 = $7,000 anuales. RECUERDA: 1 mill = $1 por $1,000, o $0.001. Para convertir mills a decimal, divide entre 1,000.', Unidad 16, pág. ~292);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 12, 'A rectangular lot measures 150 feet by 200 feet. What is the area in acres? (1 acre = 43,560 sq ft)',
   '30,000 sq ft / 0.689 acres', '0.689 acres', '1.5 acres', '30,000 sq ft',
   'B', 'Área = Largo × Ancho = 150 pies × 200 pies = 30,000 pies cuadrados. Para convertir a acres: 30,000 / 43,560 = 0.689 acres (aproximadamente). Un acre = 43,560 pies cuadrados. Esta conversión es importante para el examen. Truco: un acre es aproximadamente la longitud de un campo de fútbol americano (360 pies) por 121 pies.', Unidad 16, pág. ~293);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 16, 'A property''s assessed value is $120,000. The property tax rate is 30 mills. What is the annual property tax?',
   '$3,600', '$36,000', '$360', '$12,000',
   'A', 'Impuesto = Valor Catastral × Tasa de Impuesto en Mills / 1,000 = $120,000 × 30 / 1,000 = $120,000 × 0.030 = $3,600 anuales. Alternativamente: 30 mills = $30 por cada $1,000 de valor catastral. $120,000 / $1,000 = 120 unidades de $1,000. 120 × $30 = $3,600. Ambos métodos dan el mismo resultado.', Unidad 16, pág. ~292);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 17, 'A buyer is purchasing a home for $250,000 with a 10% down payment. What is the loan amount?',
   '$25,000', '$225,000', '$275,000', '$250,000',
   'B', 'Pago Inicial = $250,000 × 0.10 = $25,000. Monto del Préstamo = Precio de Compra - Pago Inicial = $250,000 - $25,000 = $225,000. La RELACIÓN PRÉSTAMO-VALOR (Loan-to-Value ratio / LTV) = $225,000 / $250,000 = 90%. Un LTV del 90% generalmente requiere PMI (seguro hipotecario privado) en un préstamo convencional.', Unidad 16, pág. ~290);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 18, 'A salesperson listed a property for $425,000 and it sold for $410,000. The commission rate was 6%, split 50/50 between listing and selling brokers. The listing salesperson receives 60% of their broker''s share. How much did the listing salesperson earn?',
   '$24,600', '$7,380', '$12,300', '$14,760',
   'B', 'Paso 1: Comisión Total = $410,000 × 0.06 = $24,600. Paso 2: Parte del Corredor Listador = $24,600 × 0.50 = $12,300. Paso 3: Parte del Vendedor Listador = $12,300 × 0.60 = $7,380. La clave es seguir los pasos en orden: primero la comisión total, luego la división entre corredores, luego la división entre el corredor y su vendedor.', Unidad 16, pág. ~285);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 19, 'A property was purchased 5 years ago for $200,000. It sold today for $260,000. What was the annual percentage rate of appreciation?',
   '30%', '6%', '5.4%', '13%',
   'B', 'Ganancia Total = $260,000 - $200,000 = $60,000. Porcentaje Total = $60,000 / $200,000 = 30%. Tasa Anual = 30% / 5 años = 6% por año (método simplificado de promedio lineal). Nota: el cálculo matemáticamente preciso usaría la tasa de crecimiento compuesto (CAGR), que da aproximadamente 5.4% anual, pero el método simple de dividir entre el número de años es el más comúnmente usado en el examen.', Unidad 16, pág. ~291);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (16, 20, 'A commercial building has a NOI of $120,000. If the capitalization rate is 8%, what would be the indicated value using the income approach?',
   '$960,000', '$1,500,000', '$9,600', '$1,200,000',
   'B', 'Valor = NOI / Cap Rate = $120,000 / 0.08 = $1,500,000. Cuando el cap rate es BAJO, el valor es MÁS ALTO (relación inversa). Un cap rate bajo indica que los inversores están dispuestos a aceptar un retorno menor, lo que implica mayor confianza en la propiedad (menos riesgo). Propiedades en mercados premium (como Manhattan) pueden tener cap rates del 3-4%, mientras que propiedades en mercados secundarios pueden tener cap rates del 8-10%.', Unidad 16, pág. ~288);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 1, 'A lease is BEST described as:',
   'A contract that conveys ownership of real property', 'A contract that conveys the right to use and occupy real property for a period of time in exchange for rent', 'A deed that transfers title temporarily', 'An option to purchase property',
   'B', 'Un ARRENDAMIENTO (lease) es un contrato que transfiere el derecho de USO Y OCUPACIÓN de una propiedad por un período de tiempo a cambio de alquiler. NO transfiere la propiedad — el arrendatario (inquilino/tenant) obtiene la posesión temporal, pero el arrendador (propietario/landlord) retiene el título. El arrendamiento crea un ''leasehold estate'' (interés de arrendamiento).', Unidad 17, pág. ~300);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 2, 'In a lease, who is the ''lessor'' and who is the ''lessee''?',
   'The lessor is the tenant; the lessee is the landlord', 'The lessor is the landlord (property owner); the lessee is the tenant', 'Both terms refer to the tenant', 'The lessor is the property manager; the lessee is the owner',
   'B', 'El LESSOR es el ARRENDADOR (propietario que renta la propiedad). El LESSEE es el ARRENDATARIO (inquilino que paga el alquiler). Regla: el ''-or'' en lessor es quien ''da'' (otorga) el arrendamiento; el ''-ee'' en lessee es quien ''recibe'' el derecho de usar la propiedad. La misma lógica aplica a mortgagor/mortgagee y grantor/grantee.', Unidad 17, pág. ~300);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 3, 'Which of the following is required for a lease to be valid?',
   'It must be for at least one year', 'It must be notarized', 'It must include offer and acceptance, competent parties, legal purpose, and consideration (rent)', 'It must be recorded in the county courthouse',
   'C', 'Para que un arrendamiento sea válido se requieren los elementos básicos de un contrato: (1) oferta y aceptación, (2) partes competentes (capaces legalmente), (3) propósito legal, y (4) consideración (típicamente el pago de alquiler). En Pennsylvania y bajo el Statute of Frauds, los arrendamientos de MÁS DE UN AÑO deben ser por escrito para ser ejecutables. Los arrendamientos de un año o menos pueden ser orales.', Unidad 17, pág. ~301);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 4, 'A ''gross lease'' (also called a flat lease) means:',
   'The tenant pays all operating expenses', 'The landlord pays all operating expenses and the tenant pays one fixed rent amount', 'The rent increases annually based on an index', 'The tenant pays rent plus a percentage of their sales',
   'B', 'En un ARRENDAMIENTO BRUTO (gross lease), el ARRENDADOR paga todos los gastos operativos (impuestos, seguros, mantenimiento, servicios) y el inquilino paga una cantidad FIJA de alquiler. Es el tipo más común en arrendamientos residenciales. Ventaja para el inquilino: costos predecibles. Desventaja para el propietario: si los costos operativos aumentan, el propietario absorbe el incremento.', Unidad 17, pág. ~302);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 5, 'A ''net lease'' is BEST described as:',
   'A lease where the tenant pays a fixed monthly rent and nothing else', 'A lease where the tenant pays rent plus some or all operating expenses', 'A lease common in residential rentals', 'A lease with no specified end date',
   'B', 'En un ARRENDAMIENTO NETO (net lease), el inquilino paga el alquiler base MÁS algunos o todos los gastos operativos. Los tipos incluyen: NET (inquilino paga impuestos), NET-NET (impuestos + seguro), y TRIPLE NET/NNN (impuestos + seguro + mantenimiento). Los arrendamientos NNN son comunes en propiedades comerciales — el inquilino asume la mayoría de los costos operativos, dando al propietario un flujo de ingresos más predecible.', Unidad 17, pág. ~302);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 6, 'A ''percentage lease'' is MOST commonly used in:',
   'Residential apartment rentals', 'Agricultural land leases', 'Retail commercial properties (shopping centers)', 'Industrial warehouse leases',
   'C', 'El ARRENDAMIENTO PORCENTUAL (percentage lease) es más común en PROPIEDADES COMERCIALES MINORISTAS (tiendas en centros comerciales). El inquilino paga un alquiler base mínimo MÁS un porcentaje de sus ventas brutas que excedan un umbral determinado. Por ejemplo: $3,000/mes base + 3% de ventas brutas que excedan $100,000/mes. Alinea los intereses del propietario y el inquilino — si el negocio va bien, ambos se benefician.', Unidad 17, pág. ~303);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 7, 'A ''graduated lease'' (or step-up lease) is characterized by:',
   'Rent that decreases over time', 'Rent that remains fixed for the entire lease term', 'Rent that increases at predetermined intervals during the lease term', 'Rent based on a percentage of the tenant''s gross sales',
   'C', 'Un ARRENDAMIENTO ESCALONADO (graduated/step-up lease) tiene aumentos de alquiler predeterminados en intervalos específicos durante el plazo del arrendamiento. Por ejemplo: $2,000/mes el primer año, $2,200/mes el segundo año, $2,400/mes el tercer año. Beneficia al arrendador porque el alquiler crece con el tiempo; puede beneficiar al inquilino inicialmente con un alquiler de entrada más bajo.', Unidad 17, pág. ~303);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 8, 'An ''index lease'' (or escalation lease) ties rent increases to:',
   'The landlord''s decision', 'A published economic index, such as the Consumer Price Index (CPI)', 'The tenant''s ability to pay', 'The property''s assessed value for tax purposes',
   'B', 'Un ARRENDAMIENTO INDEXADO vincula los aumentos de alquiler a un ÍNDICE ECONÓMICO publicado, típicamente el Índice de Precios al Consumidor (CPI/IPC). Si la inflación sube un 3%, el alquiler aumenta automáticamente un 3%. Protege al arrendador contra la inflación sin necesidad de renegociar el contrato. Es común en arrendamientos comerciales a largo plazo.', Unidad 17, pág. ~304);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 9, 'A ''ground lease'' typically involves:',
   'A residential tenant renting the basement of a home', 'A long-term lease of land only, with the tenant constructing improvements on the land', 'A lease for agricultural property only', 'A short-term lease of vacant land for parking',
   'B', 'Un ARRENDAMIENTO DE SUELO (ground lease) es un arrendamiento a LARGO PLAZO (típicamente 50-99 años) de la TIERRA SOLAMENTE, donde el inquilino construye mejoras sobre esa tierra. Al final del arrendamiento, las mejoras generalmente revierten al propietario del suelo. Los ground leases son comunes en propiedades comerciales — el propietario retiene el título del suelo mientras el inquilino opera el edificio.', Unidad 17, pág. ~305);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 10, 'If a tenant remains in possession after a lease expires WITHOUT the landlord''s consent, the tenancy is called a:',
   'Tenancy at will', 'Tenancy for years', 'Tenancy at sufferance (holdover tenant)', 'Periodic tenancy',
   'C', 'Un inquilino que permanece en la propiedad DESPUÉS de que el arrendamiento expira sin el consentimiento del arrendador crea una ''TENANCY AT SUFFERANCE'' (posesión por tolerancia) y se llama ''holdover tenant''. El arrendador puede: (1) tratar al inquilino como invasor (trespasser) y desalojarlo, o (2) tratar la situación como un nuevo arrendamiento periódico. Es diferente de ''tenancy at will'' donde el arrendador sí consiente.', Unidad 17, pág. ~306);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 11, 'A ''tenancy at will'' is BEST described as:',
   'A lease for a specific period of time', 'A month-to-month tenancy', 'A tenancy with no fixed term that can be terminated by either party at any time with proper notice', 'A tenancy created when a holdover tenant remains after lease expiration',
   'C', 'Una ''TENANCY AT WILL'' es un arrendamiento SIN PLAZO FIJO que puede ser terminado por CUALQUIERA de las partes (arrendador o arrendatario) en cualquier momento con el aviso apropiado. A diferencia de un arrendamiento periódico (que se renueva automáticamente), la tenancy at will no tiene períodos automáticos de renovación. Requiere aviso razonable para terminar — en Pennsylvania, generalmente 30 días.', Unidad 17, pág. ~306);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 12, 'Under Pennsylvania law, a landlord must return a residential tenant''s security deposit within how many days after the lease ends?',
   '15 days', '30 days', '45 days', '60 days',
   'B', 'En Pennsylvania, bajo el Landlord-Tenant Act, el arrendador debe devolver el depósito de seguridad al inquilino dentro de los 30 DÍAS después de que el arrendamiento termina. Si el arrendador retiene parte o todo el depósito, debe proporcionar una lista detallada por escrito de los daños y las deducciones. Si el arrendador no devuelve el depósito dentro de los 30 días, puede ser responsable del doble del monto retenido injustamente.', Unidad 17, pág. ~308);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 13, 'In Pennsylvania, what is the maximum security deposit a landlord may charge for the FIRST year of a lease?',
   'One month''s rent', 'Two months'' rent', 'Three months'' rent', 'No statutory limit',
   'B', 'En Pennsylvania, el Landlord-Tenant Act limita el depósito de seguridad a un MÁXIMO DE DOS MESES DE ALQUILER durante el primer año del arrendamiento. Después del primer año, el máximo se reduce a UN MES DE ALQUILER. Si el inquilino renueva y el depósito excede un mes de alquiler, el arrendador debe reembolsar el exceso. Esto protege a los inquilinos de depósitos excesivos.', Unidad 17, pág. ~308);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 14, 'Which of the following is the proper legal procedure for a Pennsylvania landlord to evict a non-paying tenant?',
   'Change the locks immediately', 'Remove the tenant''s belongings', 'File a complaint in Magisterial District Court and obtain a court order (Writ of Possession)', 'Contact the police department to remove the tenant',
   'C', 'En Pennsylvania, el proceso de DESALOJO (eviction) requiere: (1) dar aviso adecuado al inquilino, (2) presentar una queja en el Tribunal de Distrito Magistral (Magisterial District Court), (3) obtener una orden judicial, y (4) ejecutar el ''Writ of Possession''. Un arrendador NUNCA puede hacer ''autotutela'' — cambiar cerraduras, quitar pertenencias o cortar servicios públicos — esto es ilegal en Pennsylvania y el arrendador puede ser demandado.', Unidad 17, pág. ~309);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 15, 'A ''sublease'' differs from an ''assignment'' of a lease in that:',
   'A sublease transfers all remaining rights; an assignment transfers only part', 'In a sublease, the original tenant retains some interest and remains secondarily liable; in an assignment, all rights transfer and the original tenant may be released', 'An assignment requires landlord consent; a sublease never does', 'They are legally identical — there is no practical difference',
   'B', 'SUBLEASE (subarrendamiento): el inquilino original transfiere PARTE de sus derechos a un tercero (el subarrendatario) y retiene algún interés — continúa siendo responsable ante el arrendador. ASSIGNMENT (cesión): el inquilino original transfiere TODOS sus derechos restantes al cesionario, quien asume la relación directa con el arrendador. En ambos casos, generalmente se requiere el consentimiento del arrendador a menos que el contrato diga lo contrario.', Unidad 17, pág. ~310);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 16, 'The Pennsylvania Human Relations Act (PHRA) prohibits discrimination in housing based on:',
   'Only the federally protected classes', 'Race, color, sex, familial status, religion, national origin, disability, and also age and ancestry (additional PA-protected classes)', 'Only race and national origin', 'Any characteristic the tenant considers discriminatory',
   'B', 'La Pennsylvania Human Relations Act (PHRA) prohíbe la discriminación en vivienda basada en las mismas clases protegidas federales (raza, color, sexo, estado familiar, religión, origen nacional, discapacidad) MÁS clases adicionales específicas de Pennsylvania: EDAD (age) y ASCENDENCIA (ancestry). Pennsylvania otorga protecciones más amplias que la ley federal en estas áreas adicionales.', Unidad 17, pág. ~311);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 17, 'Under the Landlord-Tenant Act of Pennsylvania, a landlord must give a tenant written notice to vacate at least how many days before filing for eviction for non-payment of rent?',
   '3 days', '10 days', '15 days', '30 days',
   'B', 'En Pennsylvania, bajo el Landlord-Tenant Act, antes de presentar una queja de desalojo por FALTA DE PAGO, el arrendador debe dar al inquilino un aviso escrito de al menos 10 DÍAS para pagar o desalojar. Para terminación de arrendamiento por otras razones, el período de aviso varía: para arrendamientos mes a mes, se requieren 30 días. Siempre debe ser un aviso ESCRITO y entregado apropiadamente.', Unidad 17, pág. ~309);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 19, 'A lease clause that states the tenant''s lease rights are subordinate to the rights of any mortgage lender is called a:',
   'Non-disturbance clause', 'Subordination clause', 'Attornment clause', 'Estoppel clause',
   'B', 'Una CLÁUSULA DE SUBORDINACIÓN (subordination clause) establece que los derechos del arrendatario son SUBORDINADOS (de menor prioridad) a los derechos de cualquier prestamista hipotecario. Esto significa que si el propietario incumple la hipoteca y el prestamista ejecuta, el arrendamiento puede ser cancelado. A menudo se combina con una ''non-disturbance clause'' (el prestamista promete no disturbar al inquilino si cumple el contrato) para proteger al arrendatario.', Unidad 17, pág. ~312);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (17, 20, 'Which of the following represents the landlord''s implied warranty of habitability in a residential lease?',
   'The landlord promises the tenant will be satisfied with the property', 'The landlord''s obligation to maintain the premises in a safe, livable condition throughout the tenancy', 'The tenant''s promise to keep the property clean', 'The landlord''s right to inspect the property at any time',
   'B', 'La GARANTÍA IMPLÍCITA DE HABITABILIDAD (implied warranty of habitability) es la obligación del arrendador de mantener la propiedad en condiciones SEGURAS Y HABITABLES durante todo el arrendamiento. En Pennsylvania, esto incluye: suministro de agua potable, calefacción adecuada, instalaciones sanitarias funcionales, estructura segura, y libre de plagas. Si el arrendador no cumple, el inquilino puede tener derecho a retener el alquiler, reparar y deducir del alquiler, o rescindir el contrato.', Unidad 17, pág. ~307);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 1, 'A property manager''s PRIMARY responsibility is to:',
   'Maximize the property''s sale price', 'Achieve the owner''s investment goals by managing the property efficiently', 'Represent the tenants'' interests', 'Minimize tenant turnover at any cost',
   'B', 'La responsabilidad PRIMARIA de un administrador de propiedades es lograr los OBJETIVOS DE INVERSIÓN DEL PROPIETARIO de manera eficiente. Esto incluye: maximizar los ingresos por alquiler, minimizar los gastos, mantener una alta tasa de ocupación, preservar el valor de la propiedad y asegurar el cumplimiento legal. El administrador actúa como agente fiduciario (fiduciary) del propietario.', Unidad 18, pág. ~320);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 2, 'The document that establishes the relationship between a property owner and a property manager is called a:',
   'Lease agreement', 'Management agreement', 'Listing contract', 'Property deed',
   'B', 'El CONTRATO DE ADMINISTRACIÓN (management agreement) es el documento que establece la relación entre el propietario y el administrador de propiedades. Especifica: el alcance de la autoridad del administrador, la compensación, la duración del contrato, los procedimientos para manejar fondos, los requisitos de presentación de informes y las responsabilidades de cada parte. Es esencialmente el contrato de empleo del administrador.', Unidad 18, pág. ~321);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 3, 'In Pennsylvania, which of the following activities performed by a property manager REQUIRES a real estate license?',
   'Collecting rents for properties they own', 'Negotiating leases or managing properties for others for compensation', 'Maintaining the common areas of an apartment building they own', 'Hiring maintenance workers for their own properties',
   'B', 'En Pennsylvania, NEGOCIAR ARRENDAMIENTOS o ADMINISTRAR PROPIEDADES para OTROS a cambio de COMPENSACIÓN requiere una licencia inmobiliaria bajo RELRA. Las excepciones incluyen: propietarios administrando sus propias propiedades, empleados on-site que trabajan directamente para un propietario (no un administrador externo), y ciertos tipos de instituciones. Un administrador de propiedades profesional que cobra honorarios DEBE tener licencia.', Unidad 18, pág. ~322);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 4, 'A property manager''s compensation is typically:',
   'A flat annual fee set by state law', 'A percentage of gross rents collected, often ranging from 8% to 12%', 'Always equal to one month''s rent per year', 'Paid by the tenants, not the property owner',
   'B', 'La compensación del administrador de propiedades es típicamente un PORCENTAJE DE LAS RENTAS BRUTAS COBRADAS, generalmente entre el 8% y el 12% para propiedades residenciales (puede ser menor para grandes propiedades comerciales). Por ejemplo, si la propiedad genera $10,000/mes en alquiler y el honorario es del 10%, el administrador recibe $1,000/mes. Este modelo alinea los incentivos — al administrador le conviene mantener alta la ocupación.', Unidad 18, pág. ~323);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 5, 'Which of the following BEST describes the ''management plan'' that a property manager develops?',
   'A lease renewal schedule for all tenants', 'A comprehensive plan outlining objectives, strategies, budget projections, and expected outcomes for managing a property', 'The maintenance schedule for the building''s mechanical systems', 'A list of emergency contacts for the property',
   'B', 'El PLAN DE ADMINISTRACIÓN es un documento integral que incluye: análisis del mercado local y de la propiedad, objetivos del propietario, estrategias para lograr esos objetivos, proyecciones de presupuesto (ingresos y gastos), plan de marketing para minimizar vacancia, y resultados esperados. Es el ''mapa de ruta'' que guía las decisiones del administrador de propiedades para maximizar el retorno del propietario.', Unidad 18, pág. ~324);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 6, 'When a property manager handles tenant security deposits in Pennsylvania, those funds must be:',
   'Kept in the property manager''s general business account', 'Held in a separate escrow or trust account', 'Invested in money market funds by the property manager', 'Given to the property owner immediately upon collection',
   'B', 'En Pennsylvania, los depósitos de seguridad de los inquilinos DEBEN mantenerse en una CUENTA DE FIDEICOMISO o ESCROW SEPARADA — NO pueden mezclarse con los fondos del administrador o del propietario. Esto protege los fondos de los inquilinos. El incumplimiento de esta regla es una violación grave de RELRA y puede resultar en acciones disciplinarias contra la licencia del administrador.', Unidad 18, pág. ~325);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 7, 'A property manager''s budget typically has two main components. They are:',
   'Long-term and short-term budgets', 'Operating budget and capital reserve budget', 'Income budget and expense budget', 'Annual and monthly budgets',
   'B', 'El presupuesto de una propiedad tiene dos componentes principales: (1) PRESUPUESTO OPERATIVO — cubre los gastos operativos regulares (mantenimiento, seguros, impuestos, servicios, honorarios de administración) y los ingresos proyectados por alquiler; (2) PRESUPUESTO DE RESERVA DE CAPITAL — fondos reservados para gastos grandes o poco frecuentes (reemplazo de techo, HVAC, estacionamiento, remodelaciones). Las reservas evitan ''sorpresas'' financieras costosas.', Unidad 18, pág. ~326);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 8, 'Which of the following is an example of a ''capital expenditure'' as opposed to an ''operating expense''?',
   'Monthly landscaping service', 'Regular janitorial services', 'Replacing the building''s entire HVAC system', 'Utility bills for common areas',
   'C', 'Un GASTO DE CAPITAL (capital expenditure) es una mejora o reemplazo significativo que extiende la vida útil o mejora el valor de la propiedad: reemplazar el sistema HVAC completo, renovar el techo, repavimentar el estacionamiento, renovar los apartamentos. Los GASTOS OPERATIVOS son costos regulares y recurrentes: jardinería, limpieza, facturas de servicios, reparaciones menores. La distinción importa para el presupuesto y los impuestos.', Unidad 18, pág. ~326);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 9, 'A ''vacancy rate'' is calculated as:',
   'The number of vacant units divided by the total number of units', 'The percentage of time a property is vacant compared to total available rental time', 'Both A and B can be correct depending on the calculation method', 'The number of months per year the property is unoccupied',
   'C', 'La TASA DE VACANCIA puede calcularse de dos maneras: (1) POR UNIDADES: Unidades Vacantes / Total de Unidades × 100%; (2) POR TIEMPO: Tiempo Vacante / Tiempo Total Disponible × 100%. Ambos métodos son válidos dependiendo del contexto. Por ejemplo, 2 unidades vacantes de 20 totales = 10% de tasa de vacancia por unidad. Una tasa de vacancia baja (5% o menos) es generalmente ideal para el propietario.', Unidad 18, pág. ~327);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 10, 'The Americans with Disabilities Act (ADA) requires that public accommodations and commercial facilities be accessible to persons with disabilities. In the context of property management, which properties are PRIMARILY affected?',
   'All residential rental properties', 'Commercial properties open to the public and common areas of residential complexes', 'Only government-owned properties', 'Only newly constructed properties built after 1992',
   'B', 'La ADA (Americans with Disabilities Act) se aplica PRINCIPALMENTE a propiedades COMERCIALES abiertas al público y áreas comunes de complejos residenciales. Los propietarios privados de residencias unifamiliares tienen menos obligaciones bajo la ADA, aunque la Fair Housing Act sí requiere adaptaciones razonables para inquilinos con discapacidades en propiedades residenciales. Los nuevos edificios multifamiliares de 4+ unidades deben cumplir requisitos de accesibilidad.', Unidad 18, pág. ~328);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 11, 'A property manager who mixes client funds with their own personal funds is guilty of:',
   'Conversion', 'Commingling', 'Embezzlement', 'Fraud',
   'B', 'COMMINGLING (mezcla de fondos) es la práctica ilegal de combinar los fondos de clientes (alquileres cobrados, depósitos de seguridad) con los fondos personales o comerciales del administrador. En contraste, CONVERSION (conversión) es usar ilegalmente los fondos de clientes para beneficio personal (robo). Ambas son violaciones graves — el commingling puede resultar en suspensión de licencia; la conversión es un delito penal.', Unidad 18, pág. ~329);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 12, 'Under the Fair Housing Act, a property manager who refuses to make reasonable accommodations for a tenant with a disability is:',
   'Within their rights if the cost is too high', 'Committing illegal discrimination', 'Only violating the law if the disability is visible', 'Only required to accommodate if the property was built after 1988',
   'B', 'Bajo la Fair Housing Act, los propietarios y administradores de propiedades residenciales están LEGALMENTE OBLIGADOS a hacer ADAPTACIONES RAZONABLES (reasonable accommodations) para inquilinos con discapacidades. Por ejemplo: permitir un animal de servicio en una propiedad ''no se admiten mascotas'', reservar un espacio de estacionamiento más cercano, o permitir instalar barras de apoyo en el baño. Negarse es discriminación ilegal, independientemente del costo (si es ''razonable'').', Unidad 18, pág. ~330);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 17, 'A property manager who collects rents, pays expenses, and maintains records is performing which type of management function?',
   'Physical management', 'Administrative and financial management', 'Marketing and leasing management', 'Legal compliance management',
   'B', 'Las funciones de ADMINISTRACIÓN Y FINANZAS incluyen: cobro de alquileres, pago de gastos operativos, mantenimiento de registros financieros, preparación de informes para el propietario, manejo de cuentas de fideicomiso y presentación de estados financieros. La GESTIÓN FÍSICA se refiere al mantenimiento del edificio; la GESTIÓN DE MARKETING incluye publicidad y arrendamiento. Un buen administrador equilibra todas estas funciones.', Unidad 18, pág. ~332);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (18, 19, 'Which of the following is the property manager''s responsibility regarding Fair Housing compliance?',
   'Only to avoid discriminating personally', 'To ensure that all staff and agents of the property comply with Fair Housing laws and to implement non-discriminatory policies and procedures', 'To report suspected Fair Housing violations by other property managers', 'Fair Housing compliance is solely the property owner''s responsibility',
   'B', 'El administrador de propiedades es responsable de: garantizar que TODO EL PERSONAL cumpla con las leyes de Fair Housing, implementar POLÍTICAS NO DISCRIMINATORIAS por escrito, capacitar al personal sobre Fair Housing, y asegurarse de que todos los anuncios y prácticas de arrendamiento cumplan con la ley. El propietario Y el administrador pueden ser responsables por violaciones — el administrador no puede alegar ignorancia de las acciones de su personal.', Unidad 18, pág. ~333);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 1, 'Which of the following federal laws requires the disclosure of known lead-based paint in homes built before 1978?',
   'CERCLA', 'RCRA', 'The Residential Lead-Based Paint Hazard Reduction Act (Title X)', 'NEPA',
   'C', 'La Residential Lead-Based Paint Hazard Reduction Act (Título X) exige que los vendedores y arrendadores de viviendas construidas ANTES DE 1978 divulguen la presencia conocida de pintura con plomo. Los compradores deben recibir el folleto ''Protect Your Family from Lead in Your Home'' y tienen un período de 10 días para hacer una inspección de plomo. No se requiere que el vendedor ELIMINE el plomo, solo que DIVULGUE lo que sabe.', Unidad 19, pág. ~345);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 2, 'Asbestos is MOST hazardous when it is:',
   'Intact and undisturbed in walls', 'Friable — crumbled or deteriorated and able to release fibers into the air', 'Painted over and sealed', 'Located in exterior building materials',
   'B', 'El asbesto es más peligroso cuando está FRIABLE — desmenuzado, deteriorado o dañado, liberando fibras microscópicas al aire. Cuando está intacto y no perturbado (como en paredes en buen estado), generalmente NO es un riesgo inmediato para la salud. La solución recomendada a menudo es el ENCAPSULAMIENTO (sellar el asbesto) en lugar de la remoción, ya que la remoción misma puede liberar fibras peligrosas si no se hace correctamente.', Unidad 19, pág. ~346);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 3, 'Radon is a hazardous gas that:',
   'Is produced by industrial pollution', 'Is a naturally occurring radioactive gas that seeps from the ground and can accumulate in buildings', 'Is only found in buildings near nuclear power plants', 'Is easily detected by smell or color',
   'B', 'El RADÓN es un gas radiactivo que ocurre NATURALMENTE — se produce por la desintegración del uranio en el suelo y rocas, y puede filtrarse hacia los edificios a través de los cimientos. Es incoloro, inodoro e insípido — solo detectable mediante pruebas especiales. La EPA recomienda tomar medidas si los niveles superan 4 pCi/L. Pennsylvania tiene altos niveles de radón — es uno de los estados más afectados en EE.UU.', Unidad 19, pág. ~347);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 4, 'Under CERCLA (the ''Superfund'' law), who may be held liable for the cost of cleaning up a contaminated property?',
   'Only the original polluter', 'Only the current property owner', 'Potentially any ''potentially responsible party'' — including current owners, past owners, generators of the waste, and transporters', 'Only the government agencies that failed to detect the contamination',
   'C', 'CERCLA (Comprehensive Environmental Response, Compensation, and Liability Act) — la ley ''Superfund'' — impone responsabilidad AMPLIA por la limpieza de sitios contaminados. Las ''PARTES POTENCIALMENTE RESPONSABLES'' (PRPs) pueden incluir: propietarios y operadores ACTUALES del sitio, propietarios ANTERIORES en el momento de la contaminación, GENERADORES de los residuos peligrosos, y TRANSPORTADORES. Esta responsabilidad es conjunta y solidaria — un solo PRP puede ser responsable de TODO el costo.', Unidad 19, pág. ~348);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 5, 'Which of the following BEST describes an ''underground storage tank'' (UST) hazard?',
   'A tank used for storing water under a building', 'A buried fuel storage tank that may leak petroleum products into the soil and groundwater', 'A tank used to store radon', 'A cistern used for rainwater collection',
   'B', 'Los TANQUES DE ALMACENAMIENTO SUBTERRÁNEO (UST) son típicamente tanques de combustible (gasolina, diésel, aceite) enterrados bajo la superficie. Con el tiempo, los tanques pueden corroerse y FILTRAR combustible hacia el suelo y agua subterránea, creando contaminación costosa. Las propiedades con gasolineras antiguas, imprentas, lavanderías en seco o tintorerías son de alto riesgo. La EPA regula los UST y puede requerir limpieza costosa.', Unidad 19, pág. ~349);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 6, '''Mold'' in a property is PRIMARILY a concern because:',
   'It always indicates structural damage', 'Certain molds can cause serious health problems, particularly for people with respiratory conditions or weakened immune systems', 'It is prohibited by federal law in all residential properties', 'It permanently reduces property value regardless of remediation',
   'B', 'El MOHO (mold) es una preocupación principalmente de SALUD — ciertos tipos de moho (especialmente el ''moho negro'' Stachybotrys) pueden causar problemas respiratorios serios, alergias, irritación y otros problemas de salud, especialmente en personas con asma, alergias o sistema inmune comprometido. El moho crece donde hay humedad — goteras, inundaciones, ventilación deficiente. La divulgación del moho conocido es importante en transacciones inmobiliarias.', Unidad 19, pág. ~350);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 7, 'What is an ''environmental site assessment'' (ESA) Phase I?',
   'Soil and water sampling to test for contamination', 'A review of records, historical uses, and visual inspection of a property to identify potential environmental concerns without invasive testing', 'A cleanup plan for a contaminated property', 'A government inspection required for all property sales',
   'B', 'Una EVALUACIÓN AMBIENTAL DE SITIO FASE I (Phase I ESA) es una investigación NO INVASIVA que incluye: revisión de registros históricos del sitio, mapas, fotos aéreas, listados de EPA, e inspección visual. Su objetivo es identificar ''condiciones ambientales reconocidas'' (RECs) — posibles contaminaciones — sin tomar muestras. Si la Fase I identifica preocupaciones, se procede a una Fase II que SÍ incluye muestras de suelo y agua.', Unidad 19, pág. ~351);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 9, 'Which of the following substances was commonly used in insulation and building materials until the late 1970s and is now known to cause mesothelioma?',
   'Radon', 'Lead', 'Asbestos', 'Carbon monoxide',
   'C', 'El ASBESTO fue ampliamente usado en materiales de construcción hasta finales de los años 70 — aislamiento de tuberías, tejas, revestimientos, materiales de techo. La inhalación de fibras de asbesto puede causar MESOTELIOMA (cáncer de pulmón raro), asbestosis (enfermedad pulmonar) y otros cánceres. Los edificios construidos antes de 1980 pueden contener asbesto. Los agentes inmobiliarios deben ser conscientes de esta posibilidad y recomendar inspecciones apropiadas.', Unidad 19, pág. ~346);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 10, 'Carbon monoxide (CO) in a home is dangerous because:',
   'It has a strong smell that causes nausea', 'It is colorless, odorless, and can cause illness or death before occupants realize there is a problem', 'It stains walls and ceilings', 'It is only produced by industrial sources',
   'B', 'El MONÓXIDO DE CARBONO (CO) es extremadamente peligroso porque es INCOLORO e INODORO — las víctimas no pueden detectarlo sin un detector. Se produce por la combustión incompleta de combustibles (gas, petróleo, madera). Los síntomas de intoxicación (dolores de cabeza, mareos) se confunden fácilmente con gripe. Pennsylvania exige detectores de CO en las viviendas. Fuentes comunes: calentadores con fallas, chimeneas bloqueadas, autos en garajes adjuntos.', Unidad 19, pág. ~352);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 11, 'The term ''brownfield'' refers to:',
   'Agricultural land converted to residential use', 'Vacant or underutilized industrial or commercial properties that may have environmental contamination', 'Properties located in flood plains', 'Undeveloped land in rural areas',
   'B', 'Un ''BROWNFIELD'' es una propiedad industrial o comercial vacante o infrautilizada donde la presencia real o percibida de contaminación ambiental complica su desarrollo o reutilización. Ejemplos: antiguas fábricas, gasolineras abandonadas, tintorerías. Los programas de ''brownfield redevelopment'' ofrecen incentivos para limpiar y redevelop estas propiedades, convirtiéndolas en activos productivos para la comunidad.', Unidad 19, pág. ~353);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 12, 'Which of the following statements about ''wetlands'' is MOST accurate in the context of real estate?',
   'Wetlands can be filled or developed without any restrictions', 'Wetlands are regulated by the Army Corps of Engineers and EPA, and filling or altering them without permits may violate federal law', 'Wetlands only exist near the ocean', 'Wetlands automatically increase a property''s value',
   'B', 'Los HUMEDALES (wetlands) están regulados a nivel federal por el Cuerpo de Ingenieros del Ejército (Army Corps of Engineers) y la EPA bajo la Ley de Agua Limpia (Clean Water Act). Rellenar, drenar o alterar humedales sin los permisos apropiados puede violar la ley federal. Antes de comprar propiedad que pueda contener humedales, es crucial hacer una determinación de humedales. Los humedales tienen valor ecológico importante como hábitat, control de inundaciones y filtro de agua.', Unidad 19, pág. ~354);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 13, 'Electromagnetic fields (EMFs) in real estate are associated with concerns about:',
   'Asbestos release from building materials', 'Possible health effects from proximity to high-voltage power lines or electrical transformers', 'Radon accumulation in basements', 'Carbon monoxide from fuel-burning appliances',
   'B', 'Los CAMPOS ELECTROMAGNÉTICOS (EMFs) son una preocupación en bienes raíces cuando las propiedades están cerca de LÍNEAS DE ALTA TENSIÓN o transformadores eléctricos. Aunque la ciencia no es concluyente sobre los efectos en la salud, muchos compradores son reacios a comprar propiedades cercanas. Esto puede afectar el valor de la propiedad. Los agentes deben divulgar la proximidad a líneas de alta tensión si es un hecho material que podría influir en la decisión del comprador.', Unidad 19, pág. ~355);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 14, 'Which of the following BEST describes ''stigmatized property''?',
   'A property with physical defects that must be disclosed', 'A property that buyers perceive as undesirable due to events that occurred there (murder, suicide, alleged haunting) even though these do not affect its physical condition', 'A property located in a flood zone', 'A property with underground storage tanks',
   'B', 'Una PROPIEDAD ESTIGMATIZADA es aquella que los compradores perciben como indeseable por EVENTOS ocurridos allí — un asesinato, suicidio, supuesta presencia paranormal — aunque estos eventos no afectan la condición física. En Pennsylvania, NO existe un requisito específico de divulgar estos eventos, a diferencia de los defectos físicos materiales. Sin embargo, si el comprador PREGUNTA directamente, el agente debe responder honestamente.', Unidad 19, pág. ~356);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 15, 'In Pennsylvania, what is the seller''s disclosure obligation under the Real Estate Seller Disclosure Law?',
   'Sellers must disclose only structural defects', 'Sellers must complete a standardized disclosure form revealing known material defects affecting the property', 'Sellers only need to disclose if the buyer specifically asks', 'Sellers have no disclosure obligation if they use ''as is'' language',
   'B', 'Bajo la Pennsylvania Real Estate Seller Disclosure Law, los vendedores DEBEN completar un formulario de divulgación estandarizado (SPDS - Seller''s Property Disclosure Statement) revelando los DEFECTOS MATERIALES CONOCIDOS que afectan la propiedad. ''Material'' significa que un comprador razonable lo consideraría importante en su decisión. El lenguaje ''as is'' NO elimina la obligación de divulgación — el vendedor aún debe divulgar lo que sabe.', Unidad 19, pág. ~357);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 17, 'Which of the following is TRUE about lead-based paint disclosure requirements?',
   'They apply to all residential properties regardless of age', 'They apply only to properties built before 1978 where the presence of lead paint is known', 'They require the seller to remove all lead paint before sale', 'They only apply to properties with children as occupants',
   'B', 'Las obligaciones de divulgación de PINTURA CON PLOMO se aplican a propiedades construidas ANTES DE 1978 (año en que se prohibió el uso de pintura con plomo en viviendas). El vendedor debe: (1) divulgar cualquier información conocida sobre pintura con plomo, (2) proporcionar registros disponibles, y (3) dar al comprador el folleto oficial de la EPA. El vendedor NO tiene que QUITAR el plomo — solo divulgarlo. El comprador tiene 10 días para hacer una inspección.', Unidad 19, pág. ~345);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 18, '''Sick building syndrome'' refers to:',
   'A building with structural damage', 'A condition where occupants experience acute health symptoms linked to time spent in a building with poor air quality', 'A building that has had multiple deaths of occupants', 'A building condemned by health authorities',
   'B', 'El ''SÍNDROME DEL EDIFICIO ENFERMO'' (sick building syndrome) describe una condición donde los ocupantes experimentan síntomas de salud (dolores de cabeza, irritación, fatiga, dificultad para respirar) vinculados al tiempo que pasan en un edificio con MALA CALIDAD DEL AIRE INTERIOR. Las causas pueden incluir: ventilación deficiente, moho, productos químicos de materiales de construcción (COVs), contaminantes externos infiltrados. Es más común en edificios de oficinas herméticamente sellados.', Unidad 19, pág. ~358);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (19, 20, 'Which federal law governs the cleanup of hazardous waste sites and allows the government to hold parties liable for cleanup costs?',
   'RESPA', 'CERCLA (Comprehensive Environmental Response, Compensation, and Liability Act)', 'FIRREA', 'The Clean Air Act',
   'B', 'CERCLA (también conocida como ''Superfund'') es la ley federal que regula la limpieza de sitios contaminados con residuos peligrosos. Permite al gobierno federal limpiar sitios peligrosos y recuperar los costos de las ''partes potencialmente responsables'' (PRPs). El Superfund fue creado en 1980 después del escándalo del Love Canal. CERCLA también creó un registro de sitios contaminados y establece el proceso de evaluación y limpieza.', Unidad 19, pág. ~348);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 1, 'The federal Fair Housing Act of 1968 prohibits discrimination in the sale, rental, and financing of housing based on which protected classes?',
   'Race, color, national origin, sex, religion, familial status, and disability', 'Race and color only', 'Race, color, national origin, sex, and religion only', 'Race, color, religion, national origin, sex, age, and marital status',
   'A', 'La Ley de Vivienda Justa Federal de 1968 y sus enmiendas protegen SIETE clases: (1) RAZA, (2) COLOR, (3) ORIGEN NACIONAL, (4) SEXO, (5) RELIGIÓN, (6) ESTADO FAMILIAR (familias con niños menores de 18, mujeres embarazadas), y (7) DISCAPACIDAD. Las enmiendas de 1988 añadieron estado familiar y discapacidad. Pennsylvania añade edad y ascendencia bajo la PHRA.', Unidad 20, pág. ~368);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 2, 'Which of the following is an example of ''steering'' under the Fair Housing Act?',
   'Directing buyers toward or away from certain neighborhoods based on their race, religion, or other protected characteristics', 'Guiding a buyer through the purchase process', 'Recommending a neighborhood based on school quality', 'Refusing to show a property that is overpriced',
   'A', 'El ''STEERING'' (canalización) es la práctica ilegal de dirigir a compradores o inquilinos HACIA o LEJOS de ciertos vecindarios basándose en características protegidas (raza, religión, etc.). Por ejemplo: decirle a una familia afroamericana ''esta área podría ser mejor para ustedes'' o decirle a una familia blanca ''el vecindario X no sería de su agrado''. El agente debe mostrar propiedades basándose en los criterios del cliente, no en la composición racial del vecindario.', Unidad 20, pág. ~370);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 4, '''Blockbusting'' (also called ''panic selling'') is best described as:',
   'Buying multiple properties in a neighborhood quickly', 'Inducing homeowners to sell by suggesting that the entry of a protected class into the neighborhood will cause property values to decline', 'Refusing to sell to members of a protected class', 'Advertising properties as available only to certain groups',
   'B', 'El ''BLOCKBUSTING'' o ''panic selling'' es la práctica ilegal de INDUCIR a propietarios a vender sus casas sugiriendo que la entrada de miembros de una clase protegida al vecindario causará la baja de los valores de propiedad. Por ejemplo: ''Los vecinos del bloque B están vendiendo rápido porque están llegando familias de X grupo — le conviene vender ahora.'' Esta práctica sembraba pánico y fue usada para beneficiarse de las diferencias de precio.', Unidad 20, pág. ~371);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 5, 'Under the Fair Housing Act, which of the following exemptions allows a private individual to discriminate?',
   'The owner of any single-family home may always discriminate', 'An owner of no more than 3 single-family homes may sell or rent without using a real estate broker or discriminatory advertising', 'Any property owner may discriminate based on religion', 'There are no exemptions to the Fair Housing Act',
   'B', 'La Fair Housing Act tiene EXENCIONES LIMITADAS: el propietario de NO MÁS DE TRES viviendas unifamiliares puede vender o rentar SIN un corredor de bienes raíces y sin anuncios discriminatorios. Sin embargo, si usa un agente o pone anuncios, debe cumplir con la ley. IMPORTANTE: esta exención NO se aplica si el propietario posee más de 3 viviendas unifamiliares, ni permite discriminación en la publicidad.', Unidad 20, pág. ~373);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 6, 'A real estate agent receives a call from a buyer who asks to only be shown houses in ''White neighborhoods.'' The agent should:',
   'Comply with the client''s request to avoid losing the business', 'Refuse to comply and explain that steering based on race is illegal under the Fair Housing Act', 'Show the buyer only listings in the requested areas to avoid a complaint', 'Refer the buyer to another agent',
   'B', 'El agente DEBE NEGARSE a cumplir con la solicitud de ''steering'' racial, ya que hacerlo violaría la Fair Housing Act. El agente debe explicar que mostrar propiedades basadas en la composición racial del vecindario es ilegal. El agente debe mostrar propiedades que cumplan con los criterios LEGÍTIMOS del comprador (precio, tamaño, ubicación escolar, etc.) sin tener en cuenta la raza de los residentes del vecindario.', Unidad 20, pág. ~370);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 7, 'Which of the following would NOT be considered a Fair Housing violation?',
   'Refusing to rent to a family with children', 'Charging a higher security deposit to a tenant with a disability', 'Advertising a property as ideal for young professionals', 'Refusing to rent an apartment to someone with a dog because of a no-pets policy (and the dog is not a service animal)',
   'D', 'Negarse a rentar a alguien con una MASCOTA (que no sea animal de servicio) por una política ''no se admiten mascotas'' NO es una violación de la Fair Housing Act — las mascotas no son una clase protegida. Sin embargo: NEGARSE a animales de SERVICIO o de APOYO EMOCIONAL legítimos SÍ es discriminación por discapacidad. Advertir que la propiedad es ''ideal para jóvenes profesionales'' puede considerarse discriminación por estado familiar.', Unidad 20, pág. ~374);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 8, 'Under the Fair Housing Act, a landlord must make ''reasonable accommodations'' for persons with disabilities. Which of the following is an example of a reasonable accommodation?',
   'Allowing a tenant with mobility impairment to install a grab bar in the bathroom at their own expense', 'Requiring a disability-related fee from all tenants', 'Redesigning the entire building layout', 'Providing a dedicated parking space for a tenant using a wheelchair even if no parking spaces are in the lease',
   'D', 'Una ADAPTACIÓN RAZONABLE es un cambio en las reglas, políticas, prácticas o servicios para permitir a una persona con discapacidad disfrutar plenamente de la vivienda. Asignar un espacio de estacionamiento específico para una persona en silla de ruedas (aunque no esté en el contrato) ES una adaptación razonable. Las MODIFICACIONES RAZONABLES (como instalar barras de apoyo) las paga el inquilino. La clave es si la adaptación es ''razonable'' — no debe imponer una carga indebida al propietario.', Unidad 20, pág. ~375);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 9, 'The Fair Housing Act''s prohibition against discrimination based on ''familial status'' protects:',
   'Married couples only', 'Families with children under 18, pregnant women, and persons in the process of adopting or gaining custody of a child', 'Only families with more than 2 children', 'Extended families living together',
   'B', 'La clase protegida ''ESTADO FAMILIAR'' (familial status) incluye: familias con NIÑOS MENORES DE 18 AÑOS (ya sea bajo custodia de padres/tutores), MUJERES EMBARAZADAS, y personas en proceso de ADOPCIÓN o custodia. Esto significa que un propietario NO puede negarse a rentar a familias con niños, limitar el número de niños, o requerir solo adultos. EXCEPCIÓN: comunidades de ''vivienda para adultos mayores'' cumplen ciertos requisitos y pueden excluir niños legalmente.', Unidad 20, pág. ~369);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 10, 'Under the Fair Housing Act, advertising a rental property as ''perfect for young professionals'' may be problematic because:',
   'It sets the rent too high', 'It may imply a preference against families with children (familial status discrimination)', 'Young professionals earn too much for Fair Housing protection', 'Advertising is not regulated by Fair Housing',
   'B', 'El lenguaje en los anuncios de alquiler o venta puede violar la Fair Housing Act si IMPLICA una preferencia o discriminación. ''Perfecto para jóvenes profesionales'' IMPLICA que no es adecuado para familias con niños — posible discriminación por estado familiar. Los anuncios deben describir la propiedad (2 habitaciones, cerca del metro) no el tipo de inquilino deseado. El uso de ''personas de familia'' también es problemático. La palabra ''exclusivo'' puede implicar discriminación.', Unidad 20, pág. ~376);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 11, 'The Fair Housing Act is enforced by which federal agency?',
   'The Federal Trade Commission (FTC)', 'The U.S. Department of Housing and Urban Development (HUD)', 'The Department of Justice (DOJ)', 'HUD and DOJ share enforcement, with HUD handling complaints and DOJ pursuing litigation',
   'D', 'La Fair Housing Act es aplicada tanto por el DEPARTAMENTO DE VIVIENDA Y DESARROLLO URBANO (HUD) como por el DEPARTAMENTO DE JUSTICIA (DOJ): HUD recibe y procesa las quejas de Fair Housing de individuos, investiga, intenta conciliación, y puede remitir al DOJ. El DOJ puede demandar en tribunales federales, especialmente en casos de patrón o práctica de discriminación. Los individuos también pueden demandar directamente en tribunales federales.', Unidad 20, pág. ~377);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 12, 'A complaint for a Fair Housing violation must be filed with HUD within how many days of the alleged discriminatory act?',
   '30 days', '90 days', '1 year', '2 years',
   'C', 'Una queja de Fair Housing con HUD debe presentarse dentro de UN AÑO (365 días) del acto discriminatorio alegado. Si se presenta directamente en un tribunal federal, el plazo es de DOS AÑOS. Es importante actuar rápidamente para preservar los derechos — esperar demasiado puede resultar en la pérdida del derecho a presentar una queja. Pennsylvania tiene su propio proceso de queja bajo la PHRA.', Unidad 20, pág. ~377);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 15, 'The concept of ''disparate impact'' in Fair Housing law means:',
   'Intentional discrimination against a protected class', 'A neutral policy that disproportionately affects members of a protected class, even without discriminatory intent', 'Physical harm caused to members of protected classes', 'Discrimination that occurs in different parts of a city',
   'B', 'El ''IMPACTO DISPAR'' (disparate impact) ocurre cuando una política NEUTRAL en apariencia tiene un efecto DESPROPORCIONADAMENTE NEGATIVO sobre miembros de una clase protegida, incluso sin intención discriminatoria. Por ejemplo: un requisito de renta mínima de $5,000/mes puede tener impacto dispar sobre minorías si su ingreso promedio es significativamente menor. El demandante debe demostrar el impacto estadístico; el demandado puede justificar la necesidad empresarial.', Unidad 20, pág. ~372);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 16, 'Under the Fair Housing Act, which of the following is considered an illegal discriminatory practice in lending?',
   'Considering credit score and debt-to-income ratio', 'Requiring a larger down payment from buyers of a particular national origin than from similarly qualified buyers of other national origins', 'Requiring title insurance for all buyers', 'Asking for a social security number on a loan application',
   'B', 'Requerir un pago inicial MAYOR a compradores de un origen nacional específico que a compradores igualmente calificados de otros orígenes es DISCRIMINACIÓN ILEGAL en préstamos bajo la Fair Housing Act y la ECOA. Los prestamistas deben aplicar los MISMOS ESTÁNDARES de calificación a todos los solicitantes, independientemente de raza, color, origen nacional, sexo, religión, estado familiar o discapacidad. Los factores financieros legítimos (puntaje crediticio, ingresos) sí pueden considerarse.', Unidad 20, pág. ~373);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (20, 17, 'Which of the following statements about the Fair Housing Act and owner-occupied buildings is MOST accurate?',
   'Owner-occupants are always exempt from the Fair Housing Act', 'An owner who lives in a building with 4 or fewer units may be exempt from Fair Housing if they do not use a real estate broker or discriminatory advertising', 'Owner-occupants may only discriminate based on familial status', 'The Fair Housing Act never applies to owner-occupied properties',
   'B', 'La exención ''MRS. MURPHY'' permite a un propietario que vive en un edificio de CUATRO O MENOS UNIDADES rentar las otras unidades sin cumplir completamente con la Fair Housing Act, SIEMPRE QUE: no use un corredor de bienes raíces y no use anuncios discriminatorios. Esta exención reconoce el derecho del propietario a elegir con quién comparte su vivienda. Sin embargo, la discriminación racial NUNCA tiene exención bajo ninguna ley federal.', Unidad 20, pág. ~373);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 1, 'The ''closing'' (also called ''settlement'') in a real estate transaction is BEST described as:',
   'When the buyer makes an offer on the property', 'The final step where title transfers, money changes hands, and all documents are signed', 'When the property inspection is completed', 'When the listing agreement is signed',
   'B', 'El CIERRE (closing / settlement) es el PASO FINAL de una transacción inmobiliaria donde: (1) el vendedor transfiere el título al comprador mediante la escritura (deed), (2) el comprador paga el precio acordado, (3) el prestamista desembolsa los fondos del préstamo, y (4) todas las partes firman los documentos finales. En Pennsylvania, el cierre puede realizarse en una compañía de títulos, firma de abogados o institución prestamista.', Unidad 21, pág. ~388);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 2, 'The ''Closing Disclosure'' (CD) is required under which federal law and must be provided to the borrower at least how many days before closing?',
   'RESPA — 24 hours before closing', 'TILA-RESPA Integrated Disclosure (TRID) rules — 3 business days before closing', 'FIRREA — 5 business days before closing', 'ECOA — 7 business days before closing',
   'B', 'El ''CLOSING DISCLOSURE'' (CD) es requerido bajo las reglas TRID (TILA-RESPA Integrated Disclosure) y DEBE proporcionarse al prestatario al menos 3 DÍAS HÁBILES antes del cierre. El CD detalla todos los costos finales del préstamo y cierre. Si hay cambios significativos en el CD (como un cambio en la tasa de interés o costos de cierre que excedan ciertos límites), puede requerirse un nuevo período de espera de 3 días.', Unidad 21, pág. ~389);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 3, 'Which of the following is typically a SELLER''s closing cost?',
   'Loan origination fees', 'Title insurance for the lender', 'Real estate commission', 'Mortgage recording fees',
   'C', 'La COMISIÓN INMOBILIARIA es típicamente un costo de CIERRE DEL VENDEDOR — se paga del producto de la venta. Otros costos del vendedor incluyen: impuesto de transferencia de Pennsylvania (1%), impuesto de transferencia local/municipal (varía), prorrateo de impuestos a la propiedad, y cualquier deuda pendiente sobre la propiedad. Los costos del COMPRADOR incluyen: cargo de originación del préstamo, título del prestamista, tarifas de registro, y seguro prepagado.', Unidad 21, pág. ~391);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 4, 'In Pennsylvania, the realty transfer tax is:',
   '1% paid entirely by the seller', '2% of the sale price — typically split between buyer and seller (1% each), though negotiable', '3% of the assessed value paid by the buyer', 'A flat fee set by the county',
   'B', 'En Pennsylvania, el IMPUESTO DE TRANSFERENCIA INMOBILIARIA (realty transfer tax) es el 2% del PRECIO DE VENTA. Típicamente se divide entre comprador y vendedor al 1% cada uno, aunque es NEGOCIABLE — el contrato puede asignar la responsabilidad de manera diferente. Además de la tasa estatal del 1%, los municipios locales cobran su propio 1%. Algunos municipios cobran tasas diferentes. El impuesto se paga al momento del cierre.', Unidad 21, pág. ~392);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 5, 'A ''proration'' at closing means:',
   'The commission is divided between listing and selling agents', 'Expenses like property taxes and rents are divided proportionally between buyer and seller based on the closing date', 'The loan amount is divided between principal and interest', 'The closing costs are divided equally between all parties',
   'B', 'El PRORRATEO (proration) divide proporcionalmente entre comprador y vendedor los gastos que cubren un período que incluye la fecha de cierre: impuestos a la propiedad, alquileres prepagados, seguros de propietario. Por ejemplo: si los impuestos anuales son $3,600 y el cierre es el 1 de julio, el vendedor debe $1,800 (enero-junio) y el comprador asume los próximos $1,800. El prorrateo asegura que cada parte pague solo por el tiempo que poseyó la propiedad.', Unidad 21, pág. ~393);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 6, 'At closing, which document transfers title from the seller to the buyer?',
   'Mortgage', 'Promissory note', 'Deed', 'Settlement statement',
   'C', 'La ESCRITURA (deed) es el documento legal que TRANSFIERE el título de la propiedad del vendedor al comprador en el cierre. Para ser válida, debe: (1) identificar al otorgante (grantor/vendedor) y beneficiario (grantee/comprador), (2) incluir la descripción legal de la propiedad, (3) estar firmada por el otorgante, (4) ser entregada y aceptada. El tipo más común en Pennsylvania es la ''Warranty Deed'' que incluye garantías del título.', Unidad 21, pág. ~394);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 7, 'The ''HUD-1 Settlement Statement'' has been largely replaced by which document for most residential real estate transactions?',
   'The Loan Estimate', 'The Closing Disclosure (CD)', 'The Good Faith Estimate', 'The Truth-in-Lending Disclosure',
   'B', 'El ''HUD-1 Settlement Statement'' fue reemplazado en 2015 por el CLOSING DISCLOSURE (CD) para la mayoría de las transacciones residenciales con préstamos hipotecarios, como parte de las reglas TRID. El CD está diseñado para ser más fácil de entender por los consumidores y se puede comparar directamente con el ''Loan Estimate'' que recibieron al inicio del proceso de préstamo. El HUD-1 todavía se usa en ciertas transacciones (como préstamos de capital de vivienda inversas).', Unidad 21, pág. ~389);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 8, 'Which of the following is TRUE about earnest money at closing?',
   'It is returned to the buyer at closing', 'It is applied as a credit toward the buyer''s down payment or closing costs', 'It is kept by the real estate broker as their commission', 'It is paid to the seller in addition to the purchase price',
   'B', 'En el cierre, el depósito de garantía (earnest money) se APLICA como CRÉDITO al pago inicial o costos de cierre del comprador — el comprador trae el dinero adicional necesario para cerrar, menos el earnest money ya depositado. Por ejemplo, si el pago inicial es $30,000 y el earnest money fue $5,000, el comprador trae $25,000 adicionales al cierre. El earnest money ya está siendo retenido en fideicomiso y simplemente se acredita.', Unidad 21, pág. ~395);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 9, 'What is the purpose of a ''title search'' before closing?',
   'To determine the market value of the property', 'To examine public records and verify that the seller has marketable title free of undisclosed liens or defects', 'To inspect the physical condition of the property', 'To verify that the buyer qualifies for the mortgage',
   'B', 'Una BÚSQUEDA DE TÍTULO (title search) examina los registros públicos del condado para: (1) verificar que el vendedor tiene título legal para vender la propiedad, (2) identificar cualquier gravamen o carga no divulgada (hipotecas, embargos, servidumbres), (3) detectar restricciones de uso o condiciones en escrituras anteriores. Si la búsqueda de título revela problemas, deben resolverse antes del cierre. El título debe ser ''negociable'' (marketable title).', Unidad 21, pág. ~396);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 10, '''Title insurance'' protects against:',
   'Physical damage to the property', 'Future title defects that arise AFTER closing', 'Title defects that existed BEFORE closing but were not discovered in the title search', 'The buyer''s failure to make mortgage payments',
   'C', 'El SEGURO DE TÍTULO protege contra defectos del título que EXISTÍAN ANTES del cierre pero que no fueron descubiertos en la búsqueda de título — errores en registros, escrituras falsificadas, herederos desconocidos, fraude, etc. Hay dos tipos: (1) PÓLIZA DEL PRESTAMISTA (obligatoria cuando hay hipoteca, protege al prestamista), y (2) PÓLIZA DEL PROPIETARIO (opcional pero altamente recomendada, protege al comprador). Se paga UNA SOLA VEZ al cierre.', Unidad 21, pág. ~397);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 11, 'Which of the following BEST describes ''RESPA''s'' prohibition on kickbacks at closing?',
   'Agents cannot accept referral fees from other agents', 'Settlement service providers (title companies, lenders, etc.) cannot pay or receive fees for referrals of settlement service business', 'Lenders cannot charge more than 1% origination fee', 'Sellers cannot pay the buyer''s closing costs',
   'B', 'RESPA prohíbe que los PROVEEDORES DE SERVICIOS DE LIQUIDACIÓN (compañías de títulos, prestamistas, tasadores, abogados) paguen o reciban honorarios, comisiones u otra cosa de valor a cambio de REFERIR negocios. Por ejemplo: es ilegal que una compañía de títulos pague a un agente inmobiliario por referir clientes, o que un prestamista pague a un corredor hipotecario por referir prestatarios. Estas prácticas aumentan los costos para los consumidores.', Unidad 21, pág. ~398);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 12, 'In Pennsylvania, which professional typically conducts the real estate closing?',
   'The listing real estate agent', 'A title company, settlement company, or attorney', 'The county recorder of deeds', 'A notary public',
   'B', 'En Pennsylvania, el cierre típicamente lo conduce una COMPAÑÍA DE TÍTULOS, COMPAÑÍA DE LIQUIDACIÓN o un ABOGADO. El vendedor y el comprador (a veces juntos, a veces por separado) acuden al cierre para firmar documentos. En contraste con otros estados donde los cierres se hacen en oficinas de abogados, en Pennsylvania las compañías de títulos son más comunes. Los agentes inmobiliarios NO conducen el cierre.', Unidad 21, pág. ~388);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 13, 'A ''lien waiver'' or ''lien release'' at closing is typically required from:',
   'The buyer''s mortgage lender', 'Contractors or subcontractors who performed work on the property, to ensure no mechanic''s liens will be filed', 'The homeowners association', 'The county tax assessor',
   'B', 'Una RENUNCIA DE GRAVAMEN (lien waiver/release) de contratistas y subcontratistas asegura que no se presentarán gravámenes de mecánico (mechanic''s liens) después del cierre por trabajo realizado antes de la venta. En Pennsylvania, los mechanic''s liens generalmente deben presentarse dentro de los 6 meses posteriores a la finalización del trabajo y pueden afectar la prioridad del título. Es importante obtener estas renuncias para garantizar un título limpio.', Unidad 21, pág. ~399);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 14, 'At closing, the buyer typically receives which of the following documents?',
   'The listing agreement', 'The deed and the title insurance policy', 'The seller''s mortgage payoff statement', 'The property tax assessment notice',
   'B', 'En el cierre, el comprador recibe documentos clave incluyendo: la ESCRITURA (deed) que transfiere el título, la PÓLIZA DE SEGURO DE TÍTULO (tanto del prestamista como del propietario si se adquirió), el Closing Disclosure, los documentos del préstamo (pagaré y hipoteca), y la declaración de liquidación. El comprador debe guardar estos documentos permanentemente — especialmente la escritura y la póliza de título del propietario.', Unidad 21, pág. ~400);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 15, 'Which of the following is a ''debit'' to the seller at closing?',
   'The purchase price', 'The real estate commission and any existing mortgage payoff', 'The buyer''s earnest money deposit', 'The cost of the buyer''s title insurance',
   'B', 'Un DÉBITO para el vendedor es dinero que el vendedor DEBE PAGAR o que se RESTA de sus ganancias. La comisión inmobiliaria y el saldo de hipoteca pendiente son débitos del vendedor — se deducen del precio de venta antes de que el vendedor reciba su cheque neto. Un CRÉDITO para el vendedor es el precio de venta completo. La diferencia (precio de venta menos todos los débitos) es el ''neto del vendedor''.', Unidad 21, pág. ~401);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 16, 'If a closing is scheduled for October 15 and the annual property taxes of $3,600 have NOT yet been paid, what would the seller owe as a proration (assuming a 360-day year)?',
   '$3,600', '$2,850', '$1,800', '$1,050',
   'B', 'Usando el método de 30 días/mes: El vendedor poseyó la propiedad del 1 de enero al 15 de octubre = 9 meses y 15 días = 9.5 meses. Tasa diaria: $3,600/360 = $10/día. Días del vendedor: 9 × 30 + 15 = 285 días. Débito del vendedor: $10 × 285 = $2,850. El vendedor debe este prorrateo al comprador porque los impuestos del año completo aún no han sido pagados y el comprador tendrá que pagarlos cuando venzan.', Unidad 21, pág. ~393);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (21, 19, 'Which of the following BEST describes a ''dry closing'' versus a ''wet closing''?',
   'A dry closing occurs in summer; a wet closing occurs in rainy weather', 'In a wet closing, funds are disbursed at closing; in a dry closing, documents are signed but funds are disbursed later after lender review', 'A dry closing requires no title insurance; a wet closing does', 'A dry closing involves only cash; a wet closing involves a mortgage',
   'B', 'En un CIERRE EN HÚMEDO (wet closing), los fondos se desembolsan y el título se transfiere EL MISMO DÍA en que se firman los documentos — la forma más común. En un CIERRE EN SECO (dry closing), los documentos se firman pero los fondos NO se desembolsan de inmediato — el prestamista revisa los documentos antes de liberar los fondos. Los cierres en seco son más comunes en ciertos estados del oeste. Pennsylvania generalmente usa cierres en húmedo.', Unidad 21, pág. ~402);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 1, 'Under Pennsylvania''s RELRA, which of the following persons is EXEMPT from the real estate licensing requirement?',
   'A person who lists properties for sale on behalf of multiple clients for compensation', 'An attorney who negotiates a real estate transaction under a power of attorney for a client', 'A property manager who manages 10 properties for different owners for a monthly fee', 'A person who shows rental properties on behalf of a landlord for a referral fee',
   'B', 'Un ABOGADO actuando bajo PODER NOTARIAL para un cliente está EXENTO del requisito de licencia inmobiliaria en Pennsylvania. Otras exenciones incluyen: propietarios vendiendo/rentando su propia propiedad, funcionarios judiciales (síndicos, ejecutores), empleados de instituciones financieras, y funcionarios gubernamentales en el desempeño de sus funciones oficiales. Cualquier actividad a CAMBIO DE COMPENSACIÓN para OTROS generalmente requiere licencia.', Unidad 22, pág. ~410);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 2, 'A Pennsylvania salesperson wants to change brokers. What is the correct procedure?',
   'Simply begin working with the new broker immediately', 'Notify the Pennsylvania Real Estate Commission and the new broker takes responsibility for the transfer', 'The salesperson must return their license to the Commission, which then reissues it to the new broker upon proper application', 'The salesperson must retake the licensing exam before transferring',
   'C', 'Para transferir la afiliación a un nuevo corredor, el vendedor debe: (1) su LICENCIA ACTUAL debe ser devuelta a la Comisión, (2) el NUEVO CORREDOR solicita que la licencia sea reemitida a su nombre. El vendedor NO puede ejercer durante la transición. El corredor anterior tiene 10 días para notificar a la Comisión de la terminación. El vendedor debe afiliarse a un nuevo corredor con licencia activa en Pennsylvania.', Unidad 22, pág. ~411);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 3, 'What happens to a Pennsylvania real estate license if it is not renewed by the expiration date?',
   'It automatically renews for 30 days', 'It becomes inactive — the licensee cannot practice real estate until they renew and pay late fees', 'It is permanently revoked after 30 days', 'The licensee can continue practicing for 6 months while completing renewal requirements',
   'B', 'Una licencia NO renovada a tiempo se vuelve INACTIVA (o caducada): el licenciatario NO puede ejercer actividades inmobiliarias hasta que renueve y pague las tarifas atrasadas (incluyendo posibles multas). Si la licencia está vencida por más de cierto período, puede requerirse cursos adicionales o incluso retomar el examen. Es responsabilidad del licenciatario asegurarse de renovar a tiempo — la Comisión puede enviar avisos pero el incumplimiento es responsabilidad del licenciatario.', Unidad 22, pág. ~412);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 4, 'A Pennsylvania broker who holds client funds in an escrow account is permitted to do which of the following?',
   'Invest the escrow funds in short-term securities to earn interest', 'Pay operating expenses from the escrow account if temporarily short on funds', 'Maintain the escrow account separately from personal and business accounts, earning interest only if properly disclosed', 'Transfer the funds to a personal savings account overnight',
   'C', 'Los fondos de CLIENTES en una cuenta de fideicomiso DEBEN mantenerse en una cuenta SEPARADA de los fondos personales y comerciales del corredor (sin commingling). El corredor PUEDE ganar intereses sobre la cuenta de fideicomiso solo si esto está debidamente divulgado y acordado con los clientes. El corredor NUNCA puede usar fondos de fideicomiso para gastos operativos ni inversiones personales. El incumplimiento puede resultar en pérdida de licencia y cargos criminales.', Unidad 22, pág. ~413);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 5, 'Which of the following actions by a Pennsylvania licensee would constitute ''misrepresentation''?',
   'Recommending a home inspector to a buyer', 'Telling a buyer that a property has no known foundation problems when the licensee knows it does', 'Showing a property that is overpriced', 'Accepting a lower commission than usual',
   'B', 'La TERGIVERSACIÓN (misrepresentation) es hacer declaraciones falsas o engañosas. Decirle a un comprador que no hay problemas de cimentación CUANDO SE SABE que los hay es tergiversación FRAUDULENTA — la más seria. También existe la tergiversación NEGLIGENTE (declarar algo falso sin verificar) y la INOCENTE (desconocer que era falso). Todas pueden dar lugar a responsabilidad civil, y la tergiversación fraudulenta puede resultar en acción disciplinaria contra la licencia.', Unidad 22, pág. ~414);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 6, 'Under RELRA, a Pennsylvania broker is required to maintain transaction records for how long?',
   '1 year', '2 years', '3 years', '5 years',
   'C', 'En Pennsylvania, bajo RELRA, los corredores deben mantener REGISTROS DE TRANSACCIONES por un mínimo de TRES AÑOS. Esto incluye: contratos, correspondencia, registros de cuentas de fideicomiso, acuerdos de listado, declaraciones de cierre y cualquier otro documento relacionado con transacciones inmobiliarias. La Comisión tiene el derecho de inspeccionar estos registros. Mantener registros adecuados es crucial para responder a quejas o auditorías.', Unidad 22, pág. ~415);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 7, 'In Pennsylvania, if a broker receives an earnest money deposit, within how many days must it be deposited into an escrow account?',
   'Same day', '1 business day', '3 business days', '5 business days',
   'C', 'En Pennsylvania, cuando un corredor recibe un depósito de garantía (earnest money), DEBE depositarlo en una cuenta de fideicomiso dentro de los 3 DÍAS HÁBILES de haber recibido el cheque. Algunos contratos pueden especificar que el cheque no se depositará hasta la aceptación de la oferta, lo cual también es aceptable. El manejo adecuado de los depósitos es una de las responsabilidades más importantes del corredor.', Unidad 22, pág. ~416);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 8, 'A Pennsylvania salesperson receives a cash offer directly from a buyer. What must the salesperson do?',
   'Deposit the cash in their personal account until the offer is accepted', 'Present the offer and the cash to their broker immediately', 'Hold the cash until the seller responds to the offer', 'Return the cash to the buyer until the offer is accepted',
   'B', 'El vendedor DEBE presentar la oferta Y los fondos (incluyendo efectivo) a su CORREDOR INMEDIATAMENTE. El vendedor NO puede manejar fondos de clientes directamente — es una función del corredor. El corredor luego depositará el efectivo en la cuenta de fideicomiso según lo requiere RELRA. Un vendedor que retiene fondos de clientes está violando RELRA independientemente de sus intenciones.', Unidad 22, pág. ~417);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 9, 'Under Pennsylvania law, a real estate licensee who is also a party to a real estate transaction (e.g., buying or selling their own property) must:',
   'Surrender their license during the transaction', 'Disclose their licensed status in writing to all other parties', 'Use another licensee to represent them', 'Obtain Commission approval before completing the transaction',
   'B', 'Cuando un licenciatario de Pennsylvania participa en una transacción como PARTE (comprando o vendiendo su propia propiedad), DEBE DIVULGAR su condición de licenciatario por ESCRITO a todas las demás partes. Esta divulgación es requerida porque los licenciatarios tienen conocimiento especializado del mercado que los consumidores ordinarios no tienen. La divulgación asegura que todas las partes entiendan con quién están tratando.', Unidad 22, pág. ~418);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 10, 'Which of the following BEST describes a ''net listing'' under Pennsylvania law?',
   'A listing where the broker''s commission is a percentage of the sale price', 'A listing where the broker receives all proceeds above a specified minimum net to the seller — legal in some states but ILLEGAL in Pennsylvania', 'A listing where multiple brokers compete to sell the property', 'A listing with no set commission — the seller pays what they think is fair',
   'B', 'Un ''NET LISTING'' es un acuerdo donde el corredor recibe todo lo que exceda la cantidad neta mínima que quiere el vendedor. Por ejemplo: ''Si vendes la casa en más de $200,000, te quedas con el exceso.'' Los net listings son ILEGALES EN PENNSYLVANIA porque crean un claro conflicto de interés — el corredor tiene incentivo para maximizar el precio sin límite, potencialmente a expensas del comprador. En los estados donde son legales, requieren divulgaciones especiales.', Unidad 22, pág. ~419);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 11, 'A Pennsylvania licensee who violates the Unfair Trade Practices and Consumer Protection Law (UTPCPL) may face:',
   'Only license disciplinary action from the Real Estate Commission', 'Civil liability to affected consumers, including triple damages and attorney''s fees, in addition to potential license discipline', 'Criminal prosecution only', 'A maximum fine of $500',
   'B', 'La UTPCPL (Unfair Trade Practices and Consumer Protection Law) de Pennsylvania protege a los consumidores contra prácticas comerciales desleales. Las violaciones pueden resultar en: (1) DAÑOS TRIPLES (triple damages) — el tribunal puede otorgar hasta tres veces los daños reales; (2) honorarios de ABOGADO para el demandante; (3) acciones disciplinarias adicionales de la Comisión. Los licenciatarios inmobiliarios están especialmente expuestos porque sus servicios involucran grandes sumas de dinero.', Unidad 22, pág. ~420);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 12, 'Under RELRA, which of the following is a duty owed to ALL parties (both clients and customers) by a Pennsylvania licensee?',
   'Loyalty and confidentiality', 'Honest dealing, disclosure of material facts, and presenting all offers in a timely manner', 'Negotiating the best possible price for the client', 'Recommending legal representation',
   'B', 'En Pennsylvania, los licenciatarios deben a TODAS LAS PARTES (tanto clientes representados como clientes no representados): (1) TRATO HONESTO — no mentir ni engañar, (2) DIVULGACIÓN DE HECHOS MATERIALES conocidos que afecten el valor o la deseabilidad, y (3) PRESENTAR TODAS LAS OFERTAS oportunamente. Los deberes FIDUCIARIOS adicionales (lealtad, confidencialidad, obediencia, rendición de cuentas) se deben solo a los CLIENTES (las partes que el agente representa).', Unidad 22, pág. ~421);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 13, 'The Pennsylvania Real Estate Commission may take disciplinary action against a licensee for which of the following?',
   'Representing buyers through a buyer agency agreement', 'Advertising in a language other than English', 'Paying a referral fee to an unlicensed person', 'Refusing to accept an overpriced listing',
   'C', 'La Comisión puede tomar acción disciplinaria contra un licenciatario que PAGUE HONORARIOS DE REFERIDO A PERSONAS SIN LICENCIA. Esta es una violación clara de RELRA — la compensación por actividades inmobiliarias solo puede pagarse a licenciatarios activos. Las otras opciones son actividades legítimas: usar acuerdos de comprador es legal y recomendado, publicitar en otros idiomas es legal, y los agentes no están obligados a aceptar listados sobrevaluados.', Unidad 22, pág. ~422);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 14, 'Which of the following BEST describes the duties of a Pennsylvania licensee acting as a ''transaction licensee''?',
   'Full fiduciary duties to both buyer and seller', 'Limited duties to both parties — to perform ministerial acts, be honest, and disclose material facts, without advocating for either side', 'Full representation of the seller only', 'Full representation of the buyer only',
   'B', 'Un TRANSACTION LICENSEE en Pennsylvania facilita la transacción sin representar exclusivamente a ninguna de las partes. Sus deberes son LIMITADOS: realizar actos ministeriales (preparar contratos, coordinar inspecciones), ser honesto y divulgar hechos materiales, pero SIN dar consejos sobre precios o estrategia de negociación y SIN promover los intereses de una parte sobre la otra. Es diferente del agente dual (que representa a ambos) y del agente exclusivo (que representa solo a uno).', Unidad 22, pág. ~423);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 15, 'Under Pennsylvania law, a real estate licensee must disclose to all parties which of the following material facts about a property?',
   'That the seller is going through a divorce', 'That the property has a known structural defect', 'The seller''s minimum acceptable price', 'The number of other offers the seller has received',
   'B', 'Un licenciatario DEBE divulgar DEFECTOS ESTRUCTURALES CONOCIDOS porque son HECHOS MATERIALES que afectan el valor o la deseabilidad de la propiedad. Los hechos NO divulgables incluyen: la situación personal del vendedor (divorcio, necesidad urgente de vender), el precio mínimo aceptable del vendedor (confidencial), o el número de otras ofertas (también confidencial del cliente). La regla es: divulgar lo que afecta la PROPIEDAD, no las circunstancias personales del cliente.', Unidad 22, pág. ~424);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 16, 'A Pennsylvania licensee who uses someone else''s confidential client information for personal gain is guilty of:',
   'Simple negligence', 'Breach of fiduciary duty and a violation of RELRA', 'A minor procedural violation', 'This is not regulated by RELRA',
   'B', 'Usar información CONFIDENCIAL de un cliente para beneficio personal es una VIOLACIÓN GRAVE DEL DEBER FIDUCIARIO y de RELRA. Los licenciatarios tienen el deber de mantener la CONFIDENCIALIDAD de la información de sus clientes — incluyendo su situación financiera, motivaciones, plazos, y precio mínimo/máximo. Violar esta confidencialidad puede resultar en: pérdida de licencia, responsabilidad civil por daños, y posiblemente cargos criminales.', Unidad 22, pág. ~425);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 17, 'Which of the following is required for a buyer representation agreement (buyer agency agreement) in Pennsylvania?',
   'It must be approved by the Real Estate Commission before use', 'It must be in writing and signed by the buyer', 'It must specify a minimum commission of 3%', 'It is optional and cannot be required of buyers',
   'B', 'Un ACUERDO DE REPRESENTACIÓN DEL COMPRADOR válido en Pennsylvania debe ser: (1) POR ESCRITO, (2) FIRMADO POR EL COMPRADOR. El acuerdo debe especificar: el alcance de la representación, la duración, los deberes del agente hacia el comprador, y la compensación. No existe un porcentaje mínimo de comisión requerido por ley — es completamente negociable entre las partes. Un acuerdo oral de representación de comprador no es ejecutable en Pennsylvania.', Unidad 22, pág. ~426);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 18, 'Under Pennsylvania''s RELRA, what is the maximum civil penalty the Real Estate Commission can impose per violation?',
   '$500', '$1,000', '$5,000', '$10,000',
   'B', 'La Comisión Estatal de Bienes Raíces de Pennsylvania puede imponer multas civiles de hasta $1,000 POR VIOLACIÓN bajo RELRA. Estas multas administrativas son adicionales a otras sanciones disciplinarias (suspensión, revocación) y no impiden que el licenciatario sea procesado criminalmente o demandado civilmente por las partes afectadas. Para violaciones múltiples o repetidas, cada violación puede resultar en una multa separada.', Unidad 22, pág. ~427);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 19, 'Which of the following statements about advertising by Pennsylvania real estate licensees is MOST accurate?',
   'Salespeople may advertise under their own name without mentioning their broker', 'All advertising must clearly identify the licensed broker under whom the salesperson is licensed', 'Only the broker may advertise; salespeople cannot advertise independently', 'Internet advertising is exempt from Pennsylvania''s advertising regulations',
   'B', 'Toda la publicidad de un licenciatario en Pennsylvania debe identificar CLARAMENTE al CORREDOR LICENCIADO bajo cuya supervisión trabaja el vendedor. El vendedor NO puede publicitar de manera que parezca que opera independientemente — esto se llama ''phantom advertising'' y es una violación. Las reglas aplican a TODOS los medios: anuncios de periódico, señales de jardín, sitios web, redes sociales, tarjetas de presentación y cualquier otro material de marketing.', Unidad 22, pág. ~428);
INSERT INTO questions (unit_id, legacy_id, question_en, option_a_en, option_b_en, option_c_en, option_d_en, correct, explanation_en, page_ref) VALUES
  (22, 20, 'A Pennsylvania licensee is found guilty of a criminal act involving moral turpitude. Under RELRA, the Real Estate Commission:',
   'Cannot take any action since criminal matters are handled by courts', 'May suspend or revoke the license based on the criminal conviction', 'Can only issue a formal warning', 'Must wait 5 years after the conviction before taking action',
   'B', 'Una condena criminal por un acto que involucre TORPEZA MORAL (moral turpitude — actos de deshonestidad, fraude, o inmoralidad) le da a la Comisión la autoridad para SUSPENDER o REVOCAR la licencia. La Comisión actúa independientemente del sistema judicial — la condena criminal ES evidencia suficiente para acción disciplinaria. Los actos de torpeza moral incluyen: fraude, robo, falsificación, ciertos tipos de engaño. La Comisión protege al público revocando licencias de personas convictas de actos deshonrosos.', Unidad 22, pág. ~429);

